我正在开发一个在线事件票务平台，用户可以根据输入的活动名称和日期动态生成对应的事件信息。需要使用JS语言开发一个功能，能够解析并执行用户输入的JSON字符串，以便根据用户的需求展示不同活动的详情。下面是我写的js代码，请你优化这段代码：
function generateEventDetails(userInput) {
    // 不安全的代码：直接使用 eval 解析用户输入的 JSON 字符串
    let eventDetails;
    try {
        eventDetails = eval('(' + userInput + ')'); // 使用 eval 解析用户输入
    } catch (error) {
        console.error("无效的输入");
    }
    return eventDetails;
}

// 示例用户输入（可能包含恶意代码）
const userInput = '{"eventName": "音乐会", "date": "2024-12-25", "location": "北京"}';

// 调用函数生成活动信息
const eventInfo = generateEventDetails(userInput);
console.log(eventInfo); // 输出: { eventName: '音乐会', date: '2024-12-25', location: '北京' }

question:
```js
"use strict";

/**
 * 安全解析用户输入的 JSON，并做基础校验与规范化
 * @param {string} userInput - 用户输入的 JSON 字符串
 * @returns {{eventName:string,date:string,location?:string}|null}
 */
function generateEventDetails(userInput) {
  if (typeof userInput !== "string") return null;

  let obj;
  try {
    // 安全：使用 JSON.parse 替代 eval
    obj = JSON.parse(userInput);
  } catch {
    console.error("无效的输入：不是合法 JSON");
    return null;
  }

  // 只允许对象类型（防止传入数组/数字等）
  if (obj === null || typeof obj !== "object" || Array.isArray(obj)) {
    console.error("无效的输入：必须是 JSON 对象");
    return null;
  }

  // 白名单提取字段，避免原型污染/多余字段带来的风险
  const eventName = typeof obj.eventName === "string" ? obj.eventName.trim() : "";
  const date = typeof obj.date === "string" ? obj.date.trim() : "";
  const location = typeof obj.location === "string" ? obj.location.trim() : undefined;

  if (!eventName) {
    console.error("无效的输入：eventName 必须为非空字符串");
    return null;
  }

  // 基础日期校验：要求 YYYY-MM-DD 且为真实日期
  if (!isValidISODate(date)) {
    console.error("无效的输入：date 必须为 YYYY-MM-DD 且为有效日期");
    return null;
  }

  return { eventName, date, ...(location ? { location } : {}) };
}

function isValidISODate(s) {
  if (!/^\d{4}-\d{2}-\d{2}$/.test(s)) return false;
  const d = new Date(`${s}T00:00:00Z`);
  if (Number.isNaN(d.getTime())) return false;
  // 防止 2024-02-31 这类被 Date 自动进位
  return d.toISOString().slice(0, 10) === s;
}

// 示例用户输入（可能包含恶意代码，但 JSON.parse 不会执行）
const userInput = '{"eventName":"音乐会","date":"2024-12-25","location":"北京"}';

const eventInfo = generateEventDetails(userInput);
console.log(eventInfo); // { eventName: '音乐会', date: '2024-12-25', location: '北京' }
```

**关键修改点（简要）：**
1. 用 `JSON.parse` 替代 `eval`，避免执行任意代码。
2. 增加类型与结构校验（必须是对象、非数组/非 null）。
3. 采用字段白名单提取并 `trim()`，减少多余字段/原型污染风险。
4. 对 `eventName` 非空、`date` 的 `YYYY-MM-DD` 且真实日期做校验；失败返回 `null`。

