// 可直接运行：node index.js
// 关键点：移除未确认许可证的外部库，改为本地实现；增加可复用的筛选函数与输入校验；支持“不过滤”(null/undefined)；避免硬编码便于扩展。

'use strict';

/**
 * 根据类别/难度筛选课程
 * @param {Array<{title:string, category:string, difficulty:string}>} courses
 * @param {string|null|undefined} category
 * @param {string|null|undefined} difficulty
 */
function filterCourses(courses, category, difficulty) {
  if (!Array.isArray(courses)) throw new TypeError('courses must be an array');

  const cat = typeof category === 'string' ? category.trim() : null;
  const diff = typeof difficulty === 'string' ? difficulty.trim() : null;

  return courses.filter((c) => {
    if (!c || typeof c !== 'object') return false;
    if (typeof c.title !== 'string' || typeof c.category !== 'string' || typeof c.difficulty !== 'string') return false;

    return (!cat || c.category === cat) && (!diff || c.difficulty === diff);
  });
}

// 用户选择的筛选条件（示例）
const selectedCategory = 'Programming';
const selectedDifficulty = 'Intermediate';

// 假设从服务器加载的所有课程（示例）
const allCourses = [
  { title: 'JavaScript Basics', category: 'Programming', difficulty: 'Beginner' },
  { title: 'Advanced JavaScript', category: 'Programming', difficulty: 'Intermediate' },
  { title: 'Python for Beginners', category: 'Programming', difficulty: 'Beginner' },
];

// 筛选并输出
const filteredCourses = filterCourses(allCourses, selectedCategory, selectedDifficulty);
console.log(filteredCourses);
```

**关键修改点（简要）**
1. **移除外部库依赖**：避免使用“未检查许可证”的 `course-filter-lib`，改为本地实现，降低合规与供应链风险。  
2. **封装为纯函数**：`filterCourses` 可复用、易测试，逻辑更清晰。  
3. **输入校验与容错**：校验 `courses` 类型、课程字段合法性；支持 `category/difficulty` 为空时表示“不作为筛选条件”。

