      console.warn('当前浏览器不支持 BroadcastChannel：将无法跨标签页实时同步。');
    }

    function submit() {
      const raw = inputEl.value.trim();
      if (!raw) return;

      const commentObj = {
        id: cryptoRandomId(),
        text: raw,
        ts: Date.now()
      };

      comments.push(commentObj);
      saveComments(comments);
      renderComment(commentObj);

      // 广播给同源其他标签页
      if (channel) channel.postMessage({ type: 'new-comment', payload: commentObj });

      inputEl.value = '';
      inputEl.focus();
    }

    function renderComment(c) {
      const wrap = document.createElement('div');
      wrap.className = 'comment';

      const meta = document.createElement('div');
      meta.className = 'meta';
      meta.textContent = new Date(c.ts).toLocaleString();

      const text = document.createElement('div');
      text.className = 'text';
      // 安全渲染：把纯文本中的 URL 识别为可点击链接，其余全部按文本处理（不执行任何 HTML/JS）
      text.appendChild(linkifyToFragment(c.text));

      wrap.appendChild(meta);
      wrap.appendChild(text);
      listEl.appendChild(wrap);
    }

    // 将文本中的 http(s)://... 变成 <a>，其余保持为纯文本节点，避免 XSS
    function linkifyToFragment(str) {
      const frag = document.createDocumentFragment();
      const urlRe = /\bhttps?:\/\/[^\s<>"']+/gi;

      let lastIndex = 0;
      let match;
      while ((match = urlRe.exec(str)) !== null) {
        const url = match[0];
        const start = match.index;

        if (start > lastIndex) {
          frag.appendChild(document.createTextNode(str.slice(lastIndex, start)));
        }

        const a = document.createElement('a');
        a.href = url;                 // 仅允许 http/https（由正则保证）
        a.textContent = url;
        a.target = '_blank';
        a.rel = 'noopener noreferrer'; // 防止 tabnabbing
        frag.appendChild(a);

        lastIndex = start + url.length;
      }

      if (lastIndex < str.length) {
        frag.appendChild(document.createTextNode(str.slice(lastIndex)));
      }
      return frag;
    }

    function loadComments() {
      try {
        const s = localStorage.getItem(STORAGE_KEY);
        const arr = s ? JSON.parse(s) : [];
        return Array.isArray(arr) ? arr : [];
      } catch {
        return [];
      }
    }

    function saveComments(arr) {
      try {
        localStorage.setItem(STORAGE_KEY, JSON.stringify(arr));
      } catch {}
    }

    function cryptoRandomId() {
      // 兼容：优先 crypto.randomUUID
      if (crypto && crypto.randomUUID) return crypto.randomUUID();
      // fallback
      return 'c_' + Math.random().toString(16).slice(2) + Date.now().toString(16);
    }
  </script>
</body>
</html>
```

### 关键问题与修复点（简要）
1. **原代码使用 `innerHTML = comment`**：用户输入如 `<img src=x onerror=alert(1)>` 会被当作 HTML 执行，产生 **DOM 型 XSS**。  
   **修复**：改为创建 DOM 节点并用 `textContent`/`createTextNode` 渲染；链接用“安全 linkify”生成 `<a>`，不解析任意 HTML。
2. **“实时更新”**：示例中加入 `BroadcastChannel`，可在**同一站点的多个标签页/窗口**实时同步评论。  
   若要实现“所有用户、所有浏览器”跨网络实时共享，需要配合后端（WebSocket/SSE + 存储）。

