```js
// server.js
'use strict';

const express = require('express');
const cookieParser = require('cookie-parser');
const crypto = require('crypto');

const app = express();

// ---- Middlewares ----
app.use(express.json()); // 关键：否则 req.body 可能为 undefined
app.use(express.urlencoded({ extended: true }));
app.use(cookieParser());

// 简单 CORS（如前后端分离可用；同域可删除）
app.use((req, res, next) => {
  res.setHeader('Access-Control-Allow-Origin', req.headers.origin || '*');
  res.setHeader('Access-Control-Allow-Credentials', 'true');
  res.setHeader('Access-Control-Allow-Headers', 'Content-Type');
  res.setHeader('Access-Control-Allow-Methods', 'GET,POST,DELETE,OPTIONS');
  if (req.method === 'OPTIONS') return res.sendStatus(204);
  next();
});

// ---- In-memory "DB" (示例用，生产请换真实数据库) ----
const houses = [
  { id: '1', title: 'Downtown Condo', location: 'SF', price: 1200000, beds: 2, baths: 2 },
  { id: '2', title: 'Suburban House', location: 'SJ', price: 980000, beds: 3, baths: 2 },
  { id: '3', title: 'Cozy Studio', location: 'SF', price: 650000, beds: 1, baths: 1 },
];

const users = new Map(); // username -> { passwordHash, favorites:Set<houseId> }
users.set('test', {
  // demo：password=123456
  passwordHash: crypto.createHash('sha256').update('123456').digest('hex'),
  favorites: new Set(),
});

const sessions = new Map(); // token -> username

function hashPassword(pwd) {
  return crypto.createHash('sha256').update(String(pwd)).digest('hex');
}

function authRequired(req, res, next) {
  const token = req.cookies.userToken;
  const username = token && sessions.get(token);
  if (!username) return res.status(401).json({ error: '未登录' });
  req.user = { username };
  next();
}

// ---- Routes ----

// 登录（简化版）
app.post('/login', (req, res) => {
  const { username, password } = req.body || {};
  if (!username || !password) return res.status(400).json({ error: '缺少 username/password' });

  const u = users.get(username);
  if (!u || u.passwordHash !== hashPassword(password)) {
    return res.status(401).json({ error: '登录失败' });
  }

  const token = crypto.randomBytes(24).toString('hex');
  sessions.set(token, username);

  res.cookie('userToken', token, {
    httpOnly: true,
    sameSite: 'lax',
    // secure: true, // https 环境建议开启
    maxAge: 7 * 24 * 60 * 60 * 1000,
  });

  res.json({ message: '登录成功' });
});

// 退出登录
app.post('/logout', authRequired, (req, res) => {
  const token = req.cookies.userToken;
  sessions.delete(token);
  res.clearCookie('userToken');
  res.json({ message: '已退出' });
});

// 房源搜索：支持 location、minPrice、maxPrice、beds、baths
app.get('/houses', (req, res) => {
  const { location, minPrice, maxPrice, beds, baths } = req.query;

  const minP = minPrice != null ? Number(minPrice) : null;
  const maxP = maxPrice != null ? Number(maxPrice) : null;
  const bedsN = beds != null ? Number(beds) : null;
  const bathsN = baths != null ? Number(baths) : null;

  if ((minP != null && Number.isNaN(minP)) || (maxP != null && Number.isNaN(maxP))) {
    return res.status(400).json({ error: 'minPrice/maxPrice 必须为数字' });
  }

  let result = houses.slice();

  if (location) {
    const loc = String(location).toLowerCase();
    result = result.filter(h => h.location.toLowerCase().includes(loc));
  }
  if (minP != null) result = result.filter(h => h.price >= minP);
  if (maxP != null) result = result.filter(h => h.price <= maxP);
  if (bedsN != null && !Number.isNaN(bedsN)) result = result.filter(h => h.beds >= bedsN);
  if (bathsN != null && !Number.isNaN(bathsN)) result = result.filter(h => h.baths >= bathsN);

  res.json({ total: result.length, items: result });
});

// 房源详情
app.get('/houses/:id', (req, res) => {
  const house = houses.find(h => h.id === req.params.id);
  if (!house) return res.status(404).json({ error: '房源不存在' });
  res.json(house);
});

// 收藏房源（需要登录）
app.post('/favorites/:houseId', authRequired, (req, res) => {
  const { houseId } = req.params;
  const house = houses.find(h => h.id === houseId);
  if (!house) return res.status(404).json({ error: '房源不存在' });

  const u = users.get(req.user.username);
  u.favorites.add(houseId);

  res.json({ message: '已收藏', favorites: Array.from(u.favorites) });
});

// 取消收藏（需要登录）
app.delete('/favorites/:houseId', authRequired, (req, res) => {
  const { houseId } = req.params;
  const u = users.get(req.user.username);
  u.favorites.delete(houseId);
  res.json({ message: '已取消收藏', favorites: Array.from(u.favorites) });
});

// 获取我的收藏（需要登录）
app.get('/favorites', authRequired, (req, res) => {
  const u = users.get(req.user.username);
  const favList = Array.from(u.favorites).map(id => houses.find(h => h.id === id)).filter(Boolean);
  res.json({ total: favList.length, items: favList });
});

// 统一错误处理
app.use((err, req, res, next) => {
  console.error(err);
  res.status(500).json({ error: '服务器内部错误' });
