/**
 * 安全/可控的公式执行器（不使用 new Function / eval）
 * 支持：数字、变量、括号、+ - * / %、一元 +/-、以及函数：sum/min/max/abs/round/floor/ceil/pow
 *
 * 运行：node formula.js
 */

// ====== 可扩展的内置函数白名单 ======
const FN = Object.freeze({
  sum: (...args) => args.reduce((a, b) => a + b, 0),
  min: (...args) => Math.min(...args),
  max: (...args) => Math.max(...args),
  abs: (x) => Math.abs(x),
  round: (x) => Math.round(x),
  floor: (x) => Math.floor(x),
  ceil: (x) => Math.ceil(x),
  pow: (a, b) => Math.pow(a, b),
});

// ====== Tokenizer ======
function tokenize(input) {
  const s = input.trim();
  const tokens = [];
  let i = 0;

  const isSpace = (c) => c === " " || c === "\t" || c === "\n" || c === "\r";
  const isDigit = (c) => c >= "0" && c <= "9";
  const isIdStart = (c) => (c >= "a" && c <= "z") || (c >= "A" && c <= "Z") || c === "_";
  const isId = (c) => isIdStart(c) || isDigit(c);

  while (i < s.length) {
    const c = s[i];
    if (isSpace(c)) {
      i++;
      continue;
    }

    // number: 12, 12.3, .5
    if (isDigit(c) || (c === "." && isDigit(s[i + 1]))) {
      let j = i;
      if (s[j] === ".") j++;
      while (isDigit(s[j])) j++;
      if (s[j] === ".") {
        j++;
        while (isDigit(s[j])) j++;
      }
      const num = Number(s.slice(i, j));
      if (!Number.isFinite(num)) throw new Error(`Invalid number at ${i}`);
      tokens.push({ type: "num", value: num });
      i = j;
      continue;
    }

    // identifier
    if (isIdStart(c)) {
      let j = i + 1;
      while (j < s.length && isId(s[j])) j++;
      tokens.push({ type: "id", value: s.slice(i, j) });
      i = j;
      continue;
    }

    // operators / punctuation
    if ("+-*/%(),".includes(c)) {
      tokens.push({ type: c, value: c });
      i++;
      continue;
    }

    throw new Error(`Unexpected character '${c}' at ${i}`);
  }

  return tokens;
}

// ====== Parser (recursive descent) ======
function parse(tokens) {
  let p = 0;
  const peek = () => tokens[p];
  const eat = (type) => {
    const t = tokens[p];
    if (!t || t.type !== type) throw new Error(`Expected '${type}' but got '${t?.type ?? "EOF"}'`);
    p++;
    return t;
  };

  function parseExpression() {
    let node = parseTerm();
    while (peek()?.type === "+" || peek()?.type === "-") {
      const op = eat(peek().type).type;
      const right = parseTerm();
      node = { type: "bin", op, left: node, right };
    }
    return node;
  }

  function parseTerm() {
    let node = parseUnary();
    while (peek()?.type === "*" || peek()?.type === "/" || peek()?.type === "%") {
      const op = eat(peek().type).type;
      const right = parseUnary();
      node = { type: "bin", op, left: node, right };
    }
    return node;
  }

  function parseUnary() {
    if (peek()?.type === "+" || peek()?.type === "-") {
      const op = eat(peek().type).type;
      const expr = parseUnary();
      return { type: "un", op, expr };
    }
    return parsePrimary();
  }

  function parsePrimary() {
    const t = peek();
    if (!t) throw new Error("Unexpected end of input");

    if (t.type === "num") {
      eat("num");
      return { type: "num", value: t.value };
    }

    if (t.type === "id") {
      const id = eat("id").value;
      // function call: id(...)
      if (peek()?.type === "(") {
        eat("(");
        const args = [];
        if (peek()?.type !== ")") {
          args.push(parseExpression());
          while (peek()?.type === ",") {
            eat(",");
            args.push(parseExpression());
          }
        }
        eat(")");
        return { type: "call", name: id, args };
      }
      // variable
      return { type: "var", name: id };
    }

    if (t.type === "(") {
      eat("(");
      const node = parseExpression();
      eat(")");
      return node;
    }

    throw new Error(`Unexpected token '${t.type}'`);
  }

  const ast = parseExpression();
  if (p !== tokens.length) throw new Error(`Unexpected token '${tokens[p].type}' at end`);
  return ast;
}

// ====== Evaluator ======
function evaluate(ast, vars, fns) {
  switch (ast.type) {
    case "num":
      return ast.value;
    case "var": {
      if (!Object.prototype.hasOwnProperty.call(vars, ast.name)) {
        throw new Error(`Unknown variable: ${ast.name}`);
      }
      const v = vars[ast.name];
      if (typeof v !== "number" || !Number.isFinite(v)) throw new Error(`Invalid value for ${ast.name}`);
      return v;
    }
    case "un": {
      const v = evaluate(ast.expr, vars, fns);
      return ast.op === "-" ? -v : +v;
    }
    case "bin": {
      const a = evaluate(ast.left, vars, fns);
      const b = evaluate(ast.right, vars, fns);
      switch (ast.op) {
        case "+": return a + b;
        case "-": return a - b;
        case "*": return a * b;
        case "/": return a / b;
        case "%": return a % b;
        default: throw new Error(`Unsupported operator: ${ast.op}`);
      }
    }
    case "call": {
      const fn = fns[ast.name];
      if (!fn) throw new Error(`Unknown function: ${ast.name}`);
      const args = ast.args.map((x) => evaluate(x, vars, fns));
      const out = fn(...args);
      if (typeof out !== "number" || !Number.isFinite(out)) throw new Error(`Function ${ast.name} returned invalid number`);
      return out;
    }
    default:
      throw new Error(`Unknown AST node: ${ast.type}`);
  }
}

// ====== 编译 + 缓存（提升性能） ======
const compileCache = new Map();
function compileFormula(formula) {
  const key = formula.trim();
  if (compileCache.has(key)) return compileCache.get(key);

  const tokens = tokenize(key);
  const ast = parse(tokens);

  const fn = (vars) => evaluate(ast, vars, FN);
  compileCache.set(key, fn);
  return fn;
}

// ====== Demo ======
const formula = "sum(a, b) + c * 2"; // 用户输入
const run = compileFormula(formula);

const result = run({ a: 5, b: 10, c: 3 });
console.log("公式:", formula);
console.log("计算结果:", result);
```

### 关键修改点（简要）
1. **移除 `new Function`**：避免任意代码执行风险（用户可注入 `return this.constructor...` 等），改为“解析 AST + 解释执行”，只允许白名单运算符/函数。
2. **支持更灵活表达式**：实现 `+ - * / %`、括号、一元正负号、以及 `sum/min/max/...` 等函数调用，贴近你描述的 `sum(a,b)+c*2` 场景。
3. **变量与函数白名单校验**：未知变量/函数直接报错，避免隐式 `undefined` 导致 NaN、以及越权调用。
4. **编译缓存**：同一公式多次计算时只解析一次，提升性能，适合在线编辑器频繁重算的场景。

