    }
    case "un": {
      const v = evaluate(ast.expr, vars, fns);
      return ast.op === "-" ? -v : +v;
    }
    case "bin": {
      const a = evaluate(ast.left, vars, fns);
      const b = evaluate(ast.right, vars, fns);
