<!doctype html>
<html lang="zh-CN">
<head>
  <meta charset="utf-8" />
  <title>Art Display</title>
  <style>
    /* 平台自己的页面样式（不会被用户 SVG 的 style 影响） */
    body { font-family: system-ui, -apple-system, Segoe UI, Roboto, Arial, sans-serif; }
    .art-wrap { max-width: 720px; margin: 24px auto; padding: 16px; border: 1px solid #ddd; border-radius: 10px; }
    .art-stage { width: 100%; height: 360px; border: 1px dashed #bbb; border-radius: 8px; background: #fafafa; overflow: hidden; }
    .art-stage svg { width: 100%; height: 100%; display: block; }
  </style>
</head>
<body>
  <div class="art-wrap">
    <h2>作品展示</h2>
    <div id="artStage" class="art-stage"></div>
  </div>

  <script>
    function displayArtPiece(svgContent, options = {}) {
      const mount = options.mount || document.getElementById("artStage");
      if (!mount) throw new Error("Mount element not found");

      // 1) 解析 SVG（不直接 innerHTML 注入）
      const parser = new DOMParser();
      const doc = parser.parseFromString(svgContent, "image/svg+xml");
      const svg = doc.documentElement;

      // 解析错误处理
      if (!svg || svg.nodeName.toLowerCase() !== "svg" || doc.querySelector("parsererror")) {
        mount.textContent = "SVG 解析失败：内容不是有效的 SVG。";
        return;
      }

      // 2) 安全清理：移除脚本/外链/事件处理器/危险元素
      sanitizeSVG(svg);

      // 3) 以“隔离”的方式展示：放入 <iframe sandbox>，避免影响宿主页面
      const iframe = document.createElement("iframe");
      iframe.setAttribute("sandbox", ""); // 不允许脚本、表单、同源等
      iframe.style.width = "100%";
      iframe.style.height = "100%";
      iframe.style.border = "0";
      iframe.style.display = "block";

      // 4) 生成 iframe 内容（SVG 作为独立文档渲染）
      const safeSVGString = new XMLSerializer().serializeToString(svg);
      const html = `<!doctype html>
<html><head><meta charset="utf-8">
<style>html,body{margin:0;height:100%;} svg{width:100%;height:100%;display:block;}</style>
</head><body>${safeSVGString}</body></html>`;

      // 5) 挂载
      mount.replaceChildren(iframe);
      iframe.srcdoc = html;
    }

    function sanitizeSVG(svgEl) {
      // 移除高风险元素
      const forbiddenTags = new Set([
        "script", "foreignObject", "iframe", "object", "embed",
        "audio", "video", "canvas", "image", "link", "meta"
      ]);

      // 允许的属性（按需扩展）
      const allowedAttrs = new Set([
        "id","class","x","y","x1","y1","x2","y2","cx","cy","r","rx","ry",
        "d","points","width","height","viewBox","preserveAspectRatio",
        "fill","fill-opacity","stroke","stroke-width","stroke-linecap","stroke-linejoin","stroke-opacity",
        "opacity","transform","style", // style 会进一步过滤
        "xmlns","xmlns:xlink","version"
      ]);

      // 允许的 style 属性白名单（避免 position/fixed 等影响布局；也避免 url() 外链）
      const allowedStyleProps = new Set([
        "fill","fill-opacity","stroke","stroke-width","stroke-linecap","stroke-linejoin","stroke-opacity",
        "opacity","transform"
      ]);

      // 深度遍历清理
      const walker = document.createTreeWalker(svgEl, NodeFilter.SHOW_ELEMENT);
      const toRemove = [];

      while (walker.nextNode()) {
        const el = walker.currentNode;
        const tag = el.tagName;

        if (forbiddenTags.has(tag)) {
          toRemove.push(el);
          continue;
        }

        // 移除所有 on* 事件、以及不在白名单的属性
        for (const attr of [...el.attributes]) {
          const name = attr.name;
          const value = attr.value;

          // 事件处理器
          if (/^on/i.test(name)) {
            el.removeAttribute(name);
            continue;
          }

          // href/xlink:href 可能引入外链或 javascript:
          if (name === "href" || name === "xlink:href") {
            el.removeAttribute(name);
            continue;
          }

          // 不在允许列表的属性移除（保守策略）
          if (!allowedAttrs.has(name)) {
            el.removeAttribute(name);
            continue;
          }

          // 过滤 style：只保留允许的属性，且禁止 url()/expression 等
          if (name === "style") {
            const safeStyle = filterInlineStyle(value, allowedStyleProps);
            if (safeStyle) el.setAttribute("style", safeStyle);
            else el.removeAttribute("style");
            continue;
          }

          // 过滤可能的 javascript: / data:（保守）
          if (typeof value === "string" && /javascript:|data:/i.test(value)) {
            el.removeAttribute(name);
          }
        }
      }

      // 移除收集到的节点
      for (const el of toRemove) el.remove();

      // 移除 <style>（用户样式可能影响渲染或做钓鱼；如需支持可做更严格 CSS 解析）
      svgEl.querySelectorAll("style").forEach(s => s.remove());
    }

    function filterInlineStyle(styleText, allowedProps) {
      // 拒绝明显危险内容
      if (/url\s*\(|expression\s*\(|@import/i.test(styleText)) return "";

      const out = [];
      for (const part of styleText.split(";")) {
        const [rawProp, ...rest] = part.split(":");
        if (!rawProp || rest.length === 0) continue;
        const prop = rawProp.trim().toLowerCase();
        const val = rest.join(":").trim();

        if (!allowedProps.has(prop)) continue;
        if (/url\s*\(|expression\s*\(|@import/i.test(val)) continue;

        out.push(`${prop}: ${val}`);
      }
      return out.join("; ");
    }

    // 用户上传的 SVG 内容可能包含恶意样式
    const userUploadedSVG = `<svg><style>body {background-color: red;}</style><circle cx="50" cy="50" r="40" stroke="green" stroke-width="4" fill="yellow" /></svg>`;

    // 调用函数来展示艺术品
    displayArtPiece(userUploadedSVG);
  </script>
</body>
</html>
```

关键修改点（简要）：
1. **不再直接 innerHTML 注入**：用 `DOMParser` 解析 SVG，避免直接拼接导致的 XSS 风险。
2. **SVG 安全清理**：移除 `script/foreignObject` 等高风险标签、所有 `on*` 事件属性、`href/xlink:href` 外链，并对白名单属性与 `style` 做过滤。
3. **隔离渲染**：将清理后的 SVG 放入 `iframe sandbox` 的 `srcdoc` 中展示，避免用户 SVG 的样式/内容影响宿主页面。

