async function loadLegalContent(serviceId, options = {}) {
  const {
    baseUrl = "https://example.com/legal_services",
    container = document.getElementById("legal-content"),
    timeoutMs = 10000,
    signal, // 可选：外部传入 AbortController.signal
  } = options;

  if (!serviceId) throw new Error("serviceId 不能为空");
  if (!container) throw new Error("未找到展示容器，请传入 options.container 或提供 #legal-content");

  const url = `${baseUrl}/${encodeURIComponent(serviceId)}.js`;

  // 超时控制（若外部没传 signal，则内部创建）
  const controller = signal ? null : new AbortController();
  const finalSignal = signal || controller.signal;
  const timer = controller ? setTimeout(() => controller.abort(), timeoutMs) : null;

  try {
    const res = await fetch(url, {
      method: "GET",
      headers: { "Accept": "text/plain,*/*" },
      cache: "no-store",
      signal: finalSignal,
    });

    if (!res.ok) {
      throw new Error(`HTTP ${res.status} ${res.statusText}`);
    }

    const text = await res.text();

    // 等价于 Python 的 print(response.text)：展示到页面
    container.textContent = text;

    return text;
  } catch (e) {
    const msg = `加载外部脚本出现错误: ${e.name === "AbortError" ? "请求超时/被取消" : e.message}`;
    container.textContent = msg;
    console.error(msg, e);
    throw e;
  } finally {
    if (timer) clearTimeout(timer);
  }
}

