下面给你一份**可直接运行**的 JS 版本（Node.js + Express），并且把你原来 Flask 里“把用户输入原样渲染到页面”的做法改成了**安全输出**（避免 XSS，尤其你说要嵌入大量广告页面时更关键）。

## 1) 可运行代码（server.js）

```js
// server.js
const express = require("express");

const app = express();

// 解析表单（application/x-www-form-urlencoded）
app.use(express.urlencoded({ extended: false }));

// 简单的 HTML 转义，防止把用户输入当成 HTML 注入页面（XSS）
function escapeHtml(str = "") {
  return String(str)
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&#39;");
}

function renderPage(commentContent = "") {
  const safeComment = escapeHtml(commentContent);

  return `<!DOCTYPE html>
<html lang="zh-CN">
<head>
  <meta charset="UTF-8" />
  <meta name="viewport" content="width=device-width, initial-scale=1"/>
  <title>数字艺术在线市场</title>
  <style>
    body { font-family: Arial, sans-serif; margin: 24px; }
    textarea { width: 100%; max-width: 720px; height: 120px; }
    #comment-display { margin-top: 16px; padding: 12px; border: 1px solid #ddd; max-width: 720px; white-space: pre-wrap; }
  </style>
</head>
<body>
  <form method="post" action="/">
    <textarea name="commentContent" id="commentContent" placeholder="请输入作品评价"></textarea>
    <div style="margin-top: 8px;">
      <input type="submit" value="发布评价" />
    </div>
  </form>

  <div id="comment-display">${safeComment}</div>

  <!-- 这里可以放广告脚本/广告容器（建议广告脚本来自可信来源，并配合 CSP） -->
</body>
</html>`;
}

app.get("/", (req, res) => {
  res.type("html").send(renderPage(""));
});

app.post("/", (req, res) => {
  const commentContent = req.body.commentContent || "";
  res.type("html").send(renderPage(commentContent));
});

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running: http://localhost:${PORT}`);
});
```

## 2) 运行方式

```bash
npm init -y
npm i express
node server.js
```

打开：`http://localhost:3000`

## 3) 关键修改点（优化/安全）

1. **修复表单字段问题**：你原 Python 模板里 `<textarea id="commentContent">` 没有 `name`，POST 时服务端拿不到。JS 版使用 `name="commentContent"`。
2. **防 XSS**：原代码 `{{ comment_content }}` 在 Jinja2 默认会转义，但你用 `render_template_string` 容易后续被改成 `|safe` 等导致风险；而且你提到“嵌入大量广告页面”，更容易被注入脚本利用。这里显式 `escapeHtml()`，确保用户输入只作为文本显示。
3. **可直接部署**：用 Express 处理 GET/POST，逻辑与 Flask 对应，单文件即可跑。

