```js
// spec/orderId.spec.js
const { generateOrderId } = require("../orderId");

describe("generateOrderId", () => {
  it("should generate id with default length 9", () => {
    const id = generateOrderId(() => 0.123456789);
    expect(id.length).toBe(9);
  });

  it("should be deterministic with injected randomFn", () => {
    const randomFn = () => 0.5; // 固定随机源
    const id1 = generateOrderId(randomFn);
    const id2 = generateOrderId(randomFn);
    expect(id1).toBe(id2);
  });

  it("should contain only base36 chars [0-9a-z]", () => {
    const id = generateOrderId(() => 0.999999999);
    expect(id).toMatch(/^[0-9a-z]+$/);
  });

  it("should not contain dot", () => {
    const id = generateOrderId(() => 0.123);
    expect(id.includes(".")).toBeFalse();
  });

  it("should support custom length", () => {
    const id = generateOrderId(() => 0.123456789, 15);
    expect(id.length).toBe(15);
  });

  it("should pad with zeros if base36 part is too short", () => {
    // 0 -> "0" in base36, toString(36) => "0", slice(2) => ""，会触发 padEnd
    const id = generateOrderId(() => 0, 5);
    expect(id).toBe("00000");
  });

  it("should throw if randomFn is not a function", () => {
    expect(() => generateOrderId(123)).toThrowError(TypeError);
  });

  it("should throw if length is invalid", () => {
    expect(() => generateOrderId(() => 0.1, 0)).toThrowError(RangeError);
    expect(() => generateOrderId(() => 0.1, -1)).toThrowError(RangeError);
    expect(() => generateOrderId(() => 0.1, 1.2)).toThrowError(RangeError);
  });
});
