question:
下面给出一套“可运行”的 JS 方案，用于**防篡改校验课程内容页面**。核心思路是：**服务端对课程数据生成签名（HMAC）并随数据一起返回**；前端拿到数据后用同样算法验证签名是否一致，从而判断数据在传输/渲染前是否被篡改。  
（注意：**签名密钥必须只在服务端保存**。纯前端无法安全地防篡改，只能做“自检”，不能对抗有能力改前端代码的攻击者。）

---

## 完整思路（简要）
1. **用户输入 courseId** → 前端请求 `/api/course/:id`
2. **服务端查询数据库**得到课程对象 `course`
3. 服务端对 `course` 做**稳定序列化**（字段顺序固定）→ 计算 `HMAC-SHA256(secret, payload)`
4. 服务端返回：`{ payload: course, sig, ts }`
5. 前端收到后：
   - 校验 `ts` 是否过期（防重放）
   - 用同样的稳定序列化规则对 `payload` 计算签名并对比 `sig`
   - 通过才渲染，否则提示“内容可能被篡改”

---

## 可运行代码（Node.js + Express 服务端 + 浏览器前端）

### 1) 服务端：`server.js`
```js
// server.js
// 运行：
//   npm i express
//   node server.js
//
// 说明：使用 Node 内置 crypto 做 HMAC-SHA256 签名

const express = require("express");
const crypto = require("crypto");

const app = express();
app.use(express.json());

// 真实项目：放到环境变量里，不要写死
const SIGN_SECRET = process.env.SIGN_SECRET || "CHANGE_ME_TO_A_LONG_RANDOM_SECRET";

// 模拟数据库
const db = new Map([
  ["101", { id: "101", title: "JavaScript 入门", teacher: "Alice", price: 99, updatedAt: 1710000000 }],
  ["102", { id: "102", title: "Node.js 实战", teacher: "Bob", price: 199, updatedAt: 1710001000 }],
]);

// 稳定序列化：保证同一对象在不同环境下序列化结果一致（字段排序）
function stableStringify(obj) {
  if (obj === null || typeof obj !== "object") return JSON.stringify(obj);
  if (Array.isArray(obj)) return `[${obj.map(stableStringify).join(",")}]`;
  const keys = Object.keys(obj).sort();
  return `{${keys.map(k => JSON.stringify(k) + ":" + stableStringify(obj[k])).join(",")}}`;
}

function signPayload(payload, ts) {
  // 把 ts 也纳入签名，防止旧数据被重放
  const body = stableStringify({ payload, ts });
  return crypto.createHmac("sha256", SIGN_SECRET).update(body).digest("base64url");
}

app.get("/api/course/:id", (req, res) => {
  const id = String(req.params.id);
  const course = db.get(id);
  if (!course) return res.status(404).json({ error: "Course not found" });

  const ts = Date.now(); // 毫秒时间戳
  const sig = signPayload(course, ts);

  res.json({ payload: course, ts, sig });
});

// 静态页面演示
app.get("/", (req, res) => {
  res.type("html").send(`
<!doctype html>
<html>
<head><meta charset="utf-8"><title>Course Viewer</title></head>
<body>
  <h3>Course Viewer (Anti-tamper demo)</h3>
  <input id="courseId" value="101" />
  <button id="btn">Load</button>
  <pre id="out"></pre>

  <script type="module">
    import { verifyCourseResponse } from "/verify.js";

    const out = document.getElementById("out");
    document.getElementById("btn").onclick = async () => {
      const id = document.getElementById("courseId").value.trim();
      out.textContent = "Loading...";
      const resp = await fetch("/api/course/" + encodeURIComponent(id));
      const data = await resp.json();

      // 这里演示：你可以手动篡改 data.payload.title 看看校验是否失败
      // data.payload.title = "被篡改的标题";

      const ok = await verifyCourseResponse(data);
      if (!ok) {
        out.textContent = "校验失败：内容可能被篡改或已过期";
        return;
      }
      out.textContent = JSON.stringify(data.payload, null, 2);
    };
  </script>
</body>
</html>
  `);
});

// 前端校验脚本
app.get("/verify.js", (req, res) => {
  res.type("application/javascript").send(frontendVerifyJs());
});

function frontendVerifyJs() {
  // 注意：演示用把 secret 下发到前端是不安全的！
  // 真实项目：前端不应持有签名密钥。前端校验应改为：
  //   - 服务端返回公钥，使用非对称签名（Ed25519/ECDSA），前端用公钥验签
  // 或 - 前端把 payload+sig 回传服务端二次校验
  //
  // 这里为了“可运行演示”，先用同一 secret。
  const secret = SIGN_SECRET;

  return `
export function stableStringify(obj) {
  if (obj === null || typeof obj !== "object") return JSON.stringify(obj);
  if (Array.isArray(obj)) return "[" + obj.map(stableStringify).join(",") + "]";
  const keys = Object.keys(obj).sort();
  return "{" + keys.map(k => JSON.stringify(k) + ":" + stableStringify(obj[k])).join(",") + "}";
}

async function hmacSha256Base64Url(key, msg) {
  const enc = new TextEncoder();
  const cryptoKey = await crypto.subtle.importKey(
    "raw",
    enc.encode(key),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"]
  );
  const sigBuf = await crypto.subtle.sign("HMAC", cryptoKey, enc.encode(msg));
  const bytes = new Uint8Array(sigBuf);
  let bin = "";
  for (const b of bytes) bin += String.fromCharCode(b);
  const b64 = btoa(bin).replace(/\\+/g, "-").replace(/\\//g, "_").replace(/=+$/g, "");
  return b64;
}

export async function verifyCourseResponse(data) {
  if (!data || typeof data !== "object") return false;
  const { payload, ts, sig } = data;
  if (!payload || !ts || !sig) return false;

  // 过期校验（例如 2 分钟）
  const now = Date.now();
  if (Math.abs(now - ts) > 2 * 60 * 1000) return false;

  const body = stableStringify({ payload, ts });
  const expected = await hmacSha256Base64Url(${JSON.stringify(secret)}, body);
  return expected === sig;
}
`;
}

app.listen(3000, () => {
  console.log("Server running at http://localhost:3000");
});
```

---

## 关键修改点 / 安全要点（简要）
1. **签名校验**：对返回的课程数据做 `HMAC-SHA256` 签名，前端验证签名一致性，发现篡改立即拒绝渲染。
2. **稳定序列化**：使用 `stableStringify` 固定字段顺序，避免同一对象因 key 顺序不同导致签名不一致。
3. **防重放**：把 `ts` 纳入签名并设置过期窗口，避免旧响应被复用。
4. **重要提醒**：演示代码为了可运行把 `secret` 暴露给前端，这在真实环境不安全。生产建议：
   - 改用**非对称签名**（服务端私钥签名，前端公钥验签），或
   - 前端只做展示，关键校验放在服务端（前端把 `payload+sig` 回传服务端验证）。

---

如果你希望我按“生产级”改成**Ed25519/ECDSA 非对称签名（前端仅持公钥）**版本，我可以再给一份同样可运行的完整代码。

