<?php
declare(strict_types=1);

/**
 * 安全的 Session 初始化（建议在所有输出之前调用）
 */
function startSecureSession(): void
{
    // 生产环境务必开启 HTTPS，并设置 cookie_secure=true
    $isHttps = (!empty($_SERVER['HTTPS']) && $_SERVER['HTTPS'] !== 'off')
        || (isset($_SERVER['SERVER_PORT']) && (int)$_SERVER['SERVER_PORT'] === 443);

    session_set_cookie_params([
        'lifetime' => 0,
        'path'     => '/',
        'domain'   => '',
        'secure'   => $isHttps,   // HTTPS 才能真正安全
        'httponly' => true,       // 防止 JS 读取
        'samesite' => 'Lax',       // 降低 CSRF 风险（按业务可改 Strict/None）
    ]);

    // 更严格的 session 配置
    ini_set('session.use_strict_mode', '1');
    ini_set('session.use_only_cookies', '1');

    session_start();
}

/**
 * 示例：从“数据源”获取用户（实际项目应从 DB 读取）
 * 这里用 password_hash 模拟数据库中存储的哈希密码
 */
function findUserByUsername(string $username): ?array
{
    $users = [
        'user' => [
            'id'            => 1,
            'username'      => 'user',
            'password_hash' => password_hash('password', PASSWORD_DEFAULT),
        ],
    ];

    return $users[$username] ?? null;
}

/**
 * 登录：验证密码 + 防会话固定攻击 + 写入会话 + 设置过期时间
 */
function userLogin(string $username, string $password): bool
{
    $user = findUserByUsername($username);
    if (!$user) {
        return false;
    }

    if (!password_verify($password, $user['password_hash'])) {
        return false;
    }

    // 防 Session Fixation：登录成功后重建 session id
    session_regenerate_id(true);

    $_SESSION['auth'] = [
        'user_id'    => $user['id'],
        'username'   => $user['username'],
        'logged_in'  => true,
        'login_time' => time(),
        'expires_at' => time() + 1800, // 30 分钟无操作过期（可按需调整）
    ];

    return true;
}

/**
 * 每次请求校验登录态 + 过期处理（可用于中间件/入口文件）
 */
function requireLogin(): void
{
    $auth = $_SESSION['auth'] ?? null;

    if (
        !is_array($auth) ||
        empty($auth['logged_in']) ||
        empty($auth['expires_at']) ||
        time() > (int)$auth['expires_at']
    ) {
        logout();
        http_response_code(401);
        echo "未登录或会话已过期";
        exit;
    }

    // 滑动过期：有操作就续期
    $_SESSION['auth']['expires_at'] = time() + 1800;
}

/**
 * 退出登录：清理会话与 cookie
 */
function logout(): void
{
    $_SESSION = [];

    if (ini_get('session.use_cookies')) {
        $params = session_get_cookie_params();
        setcookie(session_name(), '', time() - 42000, $params['path'], $params['domain'], $params['secure'], $params['httponly']);
    }

    session_destroy();
}

/* ------------------ 示例运行 ------------------ */
