    if ($page > $totalPages) $page = $totalPages;
    $offset = ($page - 1) * $limit;

    // ===== 分页查询（只取需要字段）=====
    $sql = "
        SELECT product_name, price, stock, description
        FROM products
        WHERE (? = '' OR product_name LIKE ?)
        ORDER BY id DESC
        LIMIT ? OFFSET ?
    ";
    $stmt = $conn->prepare($sql);
    $stmt->bind_param('ssii', $keyword, $like, $limit, $offset);
    $stmt->execute();
    $result = $stmt->get_result();

    // ===== 输出 =====
    echo "<div>关键词: <b>" . h($keyword) . "</b> | 共 <b>{$total}</b> 条 | 第 <b>{$page}</b>/{$totalPages} 页</div><hr>";

    if ($total === 0) {
        echo "没有找到相关商品";
    } else {
        while ($row = $result->fetch_assoc()) {
            echo "商品名称: " . h((string)$row['product_name'])
                . " - 价格: " . h((string)$row['price'])
                . " - 库存: " . h((string)$row['stock'])
                . "<br>描述: " . nl2br(h((string)$row['description']))
                . "<hr>";
        }

        // 简单分页链接
        $base = '?keyword=' . rawurlencode($keyword) . '&page=';
        echo "<div>";
        if ($page > 1) echo '<a href="' . h($base . ($page - 1)) . '">上一页</a> ';
        if ($page < $totalPages) echo '<a href="' . h($base . ($page + 1)) . '">下一页</a>';
        echo "</div>";
    }

    $stmt->close();
    $conn->close();
} catch (mysqli_sql_exception $e) {
    http_response_code(500);
    // 生产环境建议记录日志，不直接输出详细错误
    echo "系统繁忙，请稍后再试";
}
```

**关键优化点（简要）**
1. **防 SQL 注入**：改用 `prepare + bind_param`，不再拼接 `$keyword/$limit/$offset`。
2. **分页完善**：增加 `COUNT(*)` 获取总数与总页数，校正越界页码，并输出上一页/下一页链接。
3. **输出安全**：对商品名称/描述等做 `htmlspecialchars`，避免 XSS。
4. **健壮性**：参数默认值与校验（`page>=1`、关键词长度限制），并用 `try/catch` 统一处理数据库异常。
5. **性能/规范**：只查询需要字段，设置 `utf8mb4`，并加 `ORDER BY` 保证分页结果稳定。

