```php
<?php
declare(strict_types=1);
session_start();

/**
 * 简易评论平台（优化版）
 * - JSON 文件持久化
 * - 输入校验 + 输出转义
 * - CSRF 防护
 * - 简单限流（防刷）
 */

const STORE_FILE = __DIR__ . '/messages.json';
const MAX_LEN = 500;          // 评论最大长度
const RATE_LIMIT_SECONDS = 10; // 同一会话提交间隔

// 初始化 CSRF Token
if (empty($_SESSION['csrf_token'])) {
    $_SESSION['csrf_token'] = bin2hex(random_bytes(32));
}

// 读取存储
function loadMessages(): array {
    if (!file_exists(STORE_FILE)) return [];
    $raw = file_get_contents(STORE_FILE);
    if ($raw === false) return [];
    $data = json_decode($raw, true);
    return is_array($data) ? $data : [];
}

// 写入存储（加锁）
function saveMessages(array $messages): void {
    $json = json_encode($messages, JSON_UNESCAPED_UNICODE | JSON_PRETTY_PRINT);
    if ($json === false) $json = "[]";
    file_put_contents(STORE_FILE, $json, LOCK_EX);
}

// 安全输出
function e(string $s): string {
    return htmlspecialchars($s, ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
}

// 初始示例数据（仅首次写入）
$messages = loadMessages();
if (!$messages) {
    $messages = [
        [
            'content' => '欢迎使用评论平台，请文明发言。',
            'created_at' => date('c'),
            'ip_hash' => hash('sha256', $_SERVER['REMOTE_ADDR'] ?? 'unknown'),
        ],
    ];
    saveMessages($messages);
}

$errors = [];
$success = null;

// 处理提交
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    // CSRF 校验
    $token = $_POST['csrf_token'] ?? '';
    if (!hash_equals($_SESSION['csrf_token'], $token)) {
        $errors[] = '请求无效（CSRF 校验失败）。';
    }

    // 限流
    $now = time();
    $last = $_SESSION['last_post_time'] ?? 0;
    if ($now - (int)$last < RATE_LIMIT_SECONDS) {
        $errors[] = '提交过于频繁，请稍后再试。';
    }

    // 输入校验
    $new = trim((string)($_POST['new_message'] ?? ''));
    if ($new === '') {
        $errors[] = '评论不能为空。';
    } elseif (mb_strlen($new, 'UTF-8') > MAX_LEN) {
        $errors[] = '评论过长，请控制在 ' . MAX_LEN . ' 字以内。';
    }

    // 通过校验则保存
    if (!$errors) {
        $messages[] = [
            'content' => $new, // 存原文，展示时再转义
            'created_at' => date('c'),
            'ip_hash' => hash('sha256', $_SERVER['REMOTE_ADDR'] ?? 'unknown'),
        ];
        saveMessages($messages);

        $_SESSION['last_post_time'] = $now;
        $success = '评论已成功提交！';

        // PRG：避免刷新重复提交
        header('Location: ' . strtok($_SERVER['REQUEST_URI'], '?') . '?ok=1');
        exit;
    }
}

if (isset($_GET['ok'])) {
    $success = '评论已成功提交！';
}
?>
