final class Course {
    public int $courseId;
    public string $title;
    public string $content;
    public int $teacherId;

    public function __construct(int $courseId, string $title, string $content, int $teacherId) {
        $this->courseId = $courseId;
        $this->title = $title;
        $this->content = $content;
        $this->teacherId = $teacherId;
    }
}

final class EducationPlatform {
    /** @var array<int,User> */
    private array $usersById = [];
    /** @var array<int,Course> */
    private array $coursesById = [];
    /** @var array<int,array<int,bool>> studentId => [courseId => true] */
    private array $enrollments = [];

    public function addUser(int $id, string $username, string $role): void {
        if (isset($this->usersById[$id])) {
            throw new InvalidArgumentException("User id already exists: {$id}");
        }
        if (!in_array($role, ['student', 'teacher', 'admin'], true)) {
            throw new InvalidArgumentException("Invalid role: {$role}");
        }
        $this->usersById[$id] = new User($id, $username, $role);
    }

    public function addCourse(int $courseId, string $title, string $content, int $teacherId): void {
        if (isset($this->coursesById[$courseId])) {
            throw new InvalidArgumentException("Course id already exists: {$courseId}");
        }
        $teacher = $this->requireUser($teacherId);
        if ($teacher->role !== 'teacher' && $teacher->role !== 'admin') {
            throw new InvalidArgumentException("teacherId must be a teacher/admin, got: {$teacher->role}");
        }
        $this->coursesById[$courseId] = new Course($courseId, $title, $content, $teacherId);
    }

    public function enrollStudent(int $studentId, int $courseId): void {
        $student = $this->requireUser($studentId);
        if ($student->role !== 'student') {
            throw new InvalidArgumentException("Only students can enroll, got: {$student->role}");
        }
        $this->requireCourse($courseId);
        $this->enrollments[$studentId][$courseId] = true;
    }

    /**
     * 权限规则：
     * - admin：可访问所有课程
     * - teacher：只能访问自己教授的课程
     * - student：只能访问自己已选课的课程
     */
    public function getCourse(int $userId, int $courseId): ?Course {
        $user = $this->requireUser($userId);
        $course = $this->requireCourse($courseId);

        if ($user->role === 'admin') {
            return $course;
        }

        if ($user->role === 'teacher') {
            return ($course->teacherId === $userId) ? $course : null;
        }

        if ($user->role === 'student') {
            return (!empty($this->enrollments[$userId][$courseId])) ? $course : null;
        }

        return null;
    }

    private function requireUser(int $userId): User {
        if (!isset($this->usersById[$userId])) {
            throw new RuntimeException("User not found: {$userId}");
        }
        return $this->usersById[$userId];
    }

    private function requireCourse(int $courseId): Course {
        if (!isset($this->coursesById[$courseId])) {
            throw new RuntimeException("Course not found: {$courseId}");
        }
        return $this->coursesById[$courseId];
    }
}

