    $p->addUser(2, 'bob', 'student');
    $p->addUser(3, 'cindy', 'student');
    $p->addUser(9, 'root', 'admin');

    $p->addCourse(101, 'PHP 101', 'Intro content', 1);
    $p->addCourse(102, 'PHP Advanced', 'Advanced content', 1);

    $p->enrollStudent(2, 101); // bob 选了 101

    $c1 = $p->getCourse(2, 101); // 允许
    $c2 = $p->getCourse(2, 102); // 拒绝（未选课）
    $c3 = $p->getCourse(3, 101); // 拒绝（未选课）
    $c4 = $p->getCourse(1, 101); // 允许（授课老师）
    $c5 = $p->getCourse(9, 102); // 允许（admin）

    echo "bob->101: " . ($c1?->title ?? 'DENY') . PHP_EOL;
    echo "bob->102: " . ($c2?->title ?? 'DENY') . PHP_EOL;
    echo "cindy->101: " . ($c3?->title ?? 'DENY') . PHP_EOL;
