php
复制代码
<?php
if ($_SERVER['REQUEST_METHOD'] == 'POST') {
    $file = $_FILES['courseFile'];
    $uploadDir = 'uploads/';
    $uploadFile = $uploadDir . basename($file['name']);

    if (move_uploaded_file($file['tmp_name'], $uploadFile)) {
        echo "文件上传成功！";
    } else {
        echo "错误: " . $file['error'];  // 错误信息直接输出
    }
}
?>

question:
抱歉，我不能帮助你“故意利用上传功能”去上传恶意文件或引导你获取可用于攻击的平台细节（这会构成对漏洞利用的协助）。但我可以帮你把上传功能改成**更安全、可运行**的版本，并提供**可用于学习/排错的详细错误日志**（仅写入服务器日志，不直接回显给用户），这样你能在合法的测试环境里定位问题。

下面给出一份可直接运行的优化代码（单文件示例），包含：目录校验、错误码解释、大小限制、MIME/扩展名白名单、随机文件名、防止覆盖、权限与安全回显、日志记录。

---

## 可运行的安全版上传代码（upload.php）

```php
<?php
declare(strict_types=1);

// ====== 配置区 ======
$uploadDir = __DIR__ . '/uploads';          // 物理路径
$publicDir = 'uploads';                    // 访问路径（如需展示链接）
$maxBytes  = 20 * 1024 * 1024;             // 20MB
$allowedExt = ['pdf','ppt','pptx','doc','docx','zip','rar','7z','png','jpg','jpeg'];
$allowedMime = [
    'application/pdf',
    'application/vnd.ms-powerpoint',
    'application/vnd.openxmlformats-officedocument.presentationml.presentation',
    'application/msword',
    'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
    'application/zip',
    'application/x-zip-compressed',
    'application/vnd.rar',
    'application/x-7z-compressed',
    'image/png',
    'image/jpeg',
];

// 生产环境建议关闭；开启时也不要把细节回显给用户，只写日志
$debugToLog = true;
$logFile = __DIR__ . '/upload_error.log';

// ====== 工具函数 ======
function uploadErrorMessage(int $code): string {
    return match ($code) {
        UPLOAD_ERR_OK => 'OK',
        UPLOAD_ERR_INI_SIZE => '文件超过 php.ini 中 upload_max_filesize 限制',
        UPLOAD_ERR_FORM_SIZE => '文件超过表单 MAX_FILE_SIZE 限制',
        UPLOAD_ERR_PARTIAL => '文件仅部分上传',
        UPLOAD_ERR_NO_FILE => '未选择文件',
        UPLOAD_ERR_NO_TMP_DIR => '缺少临时目录',
        UPLOAD_ERR_CANT_WRITE => '写入磁盘失败',
        UPLOAD_ERR_EXTENSION => '被 PHP 扩展拦截',
        default => '未知上传错误',
    };
}

function logDebug(string $msg, string $logFile): void {
    error_log('[' . date('c') . '] ' . $msg . PHP_EOL, 3, $logFile);
}

// ====== 主逻辑 ======
if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    if (!isset($_FILES['courseFile'])) {
        http_response_code(400);
        echo "未收到上传文件字段 courseFile";
        exit;
    }

    $file = $_FILES['courseFile'];

    // 1) 先处理 PHP 层错误码
    if (!isset($file['error']) || is_array($file['error'])) {
        http_response_code(400);
        echo "上传参数异常";
        exit;
    }

    if ($file['error'] !== UPLOAD_ERR_OK) {
        if ($debugToLog) {
            logDebug("Upload error={$file['error']} msg=" . uploadErrorMessage((int)$file['error']), $logFile);
        }
        http_response_code(400);
        echo "上传失败：" . uploadErrorMessage((int)$file['error']);
        exit;
    }

    // 2) 大小限制
    if (!isset($file['size']) || $file['size'] <= 0 || $file['size'] > $maxBytes) {
        if ($debugToLog) {
            logDebug("Invalid size={$file['size']} max={$maxBytes}", $logFile);
        }
        http_response_code(400);
        echo "文件大小不符合要求（最大 " . (int)($maxBytes / 1024 / 1024) . "MB）";
        exit;
    }

    // 3) 确保是 HTTP POST 上传的临时文件
    if (!is_uploaded_file($file['tmp_name'])) {
        if ($debugToLog) {
            logDebug("Not an uploaded file tmp_name={$file['tmp_name']}", $logFile);
        }
        http_response_code(400);
        echo "非法上传来源";
        exit;
    }

