## generate.php（带注释 + 更安全输出）

```php
<?php
/**
 * generate.php
 * 论文生成页：
 * - 接收 index.php 的 POST 数据
 * - 校验请求方法与 CSRF Token
 * - 对用户输入进行裁剪、转义与格式化
 * - 生成论文 HTML 并输出
 */

declare(strict_types=1);

session_start();

/**
 * HTML 转义工具函数：
 * - 防止 XSS（将 < > " ' 等字符转义）
 */
function e(string $value): string
{
    return htmlspecialchars($value, ENT_QUOTES, 'UTF-8');
}

/**
 * 将多行文本安全地显示为 HTML：
 * - 先转义，再把换行转换为 <br>
 */
function e_nl2br(string $value): string
{
    return nl2br(e($value));
}

// 仅允许 POST 请求
if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
    header('Location: index.php');
    exit();
}

// CSRF 校验：token 必须存在且匹配
$postedToken = $_POST['csrf_token'] ?? '';
$sessionToken = $_SESSION['csrf_token'] ?? '';
if (!$postedToken || !$sessionToken || !hash_equals($sessionToken, $postedToken)) {
    http_response_code(403);
    echo '非法请求（CSRF 校验失败）。';
    exit();
}

/**
 * 获取并裁剪输入：
 * - trim 去掉首尾空白
 * - 对缺失字段给默认空字符串（避免 undefined index）
 */
$title        = trim((string)($_POST['title'] ?? ''));
$author       = trim((string)($_POST['author'] ?? ''));
$abstract     = trim((string)($_POST['abstract'] ?? ''));
$keywordsRaw  = trim((string)($_POST['keywords'] ?? ''));
$introduction = trim((string)($_POST['introduction'] ?? ''));
$conclusion   = trim((string)($_POST['conclusion'] ?? ''));

// 简单必填校验（前端 required 不能替代后端校验）
if ($title === '' || $author === '' || $abstract === '' || $keywordsRaw === '' || $introduction === '' || $conclusion === '') {
    http_response_code(400);
    echo '表单字段不完整，请返回重新填写。';
    exit();
}

/**
 * 关键词格式化：
 * - 支持中文逗号/英文逗号/分号/顿号分隔
 * - 去空、去重、再用 “, ” 连接
 */
$keywords = preg_split('/[，,;；、]+/u', $keywordsRaw) ?: [];
$keywords = array_values(array_unique(array_filter(array_map('trim', $keywords), fn($k) => $k !== '')));
$keywordsText = implode(', ', $keywords);

// 生成论文内容（注意：输出时统一使用 e / e_nl2br）
$paperHtml = "
<div class='paper'>
    <h2>" . e($title) . "</h2>
    <p><strong>作者：</strong>" . e($author) . "</p>

    <p><strong>摘要：</strong><br>" . e_nl2br($abstract) . "</p>
    <p><strong>关键词：</strong>" . e($keywordsText) . "</p>

    <h3>1. 引言</h3>
    <p>" . e_nl2br($introduction) . "</p>

    <h3>2. 结论</h3>
    <p>" . e_nl2br($conclusion) . "</p>
</div>
";
?>
