```php
<?php
declare(strict_types=1);

/**
 * 生成更安全、更不易冲突的唯一文件名（保留原扩展名，做规范化）
 */
function generateUniqueFileName(string $originalFileName): string
{
    $ext = strtolower((string)pathinfo($originalFileName, PATHINFO_EXTENSION));
    // 只允许安全字符，避免奇怪扩展名注入；没有扩展名则留空
    $ext = preg_replace('/[^a-z0-9]+/i', '', $ext) ?? '';
    $suffix = $ext !== '' ? ('.' . $ext) : '';

    // random_bytes 比 uniqid 更适合做不可预测的唯一标识
    return 'file_' . bin2hex(random_bytes(16)) . $suffix;
}

/**
 * 上传文件到指定目录
 * - 校验上传错误
 * - 限制大小
 * - 白名单扩展名
 * - 自动创建目录
 * - 生成唯一文件名并落盘
 */
function uploadFile(array $file, string $uploadDir, array $allowedExts, int $maxBytes = 104857600): array
{
    if (!isset($file['error'], $file['name'], $file['tmp_name'], $file['size'])) {
        throw new RuntimeException('无效的上传参数');
    }

    if ($file['error'] !== UPLOAD_ERR_OK) {
        throw new RuntimeException('上传失败，错误码: ' . $file['error']);
    }

    if (!is_uploaded_file($file['tmp_name'])) {
        throw new RuntimeException('疑似非法上传');
    }

    if ($file['size'] <= 0 || $file['size'] > $maxBytes) {
        throw new RuntimeException('文件大小不符合限制');
    }

    $ext = strtolower((string)pathinfo($file['name'], PATHINFO_EXTENSION));
    $ext = preg_replace('/[^a-z0-9]+/i', '', $ext) ?? '';

    $allowed = array_map('strtolower', $allowedExts);
    if ($ext === '' || !in_array($ext, $allowed, true)) {
        throw new RuntimeException('不允许的文件类型: ' . ($ext ?: '(无扩展名)'));
    }

    $uploadDir = rtrim($uploadDir, DIRECTORY_SEPARATOR);
    if (!is_dir($uploadDir) && !mkdir($uploadDir, 0755, true)) {
        throw new RuntimeException('无法创建上传目录');
    }

    // 生成不冲突文件名（极小概率冲突时重试）
    for ($i = 0; $i < 5; $i++) {
        $uniqueName = generateUniqueFileName($file['name']);
        $targetPath = $uploadDir . DIRECTORY_SEPARATOR . $uniqueName;

        if (!file_exists($targetPath)) {
            if (!move_uploaded_file($file['tmp_name'], $targetPath)) {
                throw new RuntimeException('保存文件失败');
            }

            return [
                'original_name' => $file['name'],
                'stored_name'   => $uniqueName,
                'path'          => $targetPath,
                'size'          => (int)$file['size'],
                'extension'     => $ext,
            ];
        }
    }

    throw new RuntimeException('生成唯一文件名失败，请重试');
}

/* -------------------- 示例用法 -------------------- */
/*
<form method="post" enctype="multipart/form-data">
  <input type="file" name="upload">
  <button type="submit">Upload</button>
</form>
*/

if ($_SERVER['REQUEST_METHOD'] === 'POST') {
    try {
        $result = uploadFile(
            $_FILES['upload'],
            __DIR__ . '/uploads',
            // 按需扩展：图片/文档/视频等
            ['jpg','jpeg','png','gif','webp','pdf','doc','docx','xls','xlsx','ppt','pptx','txt','zip','mp4','mov','mkv'],
            100 * 1024 * 1024 // 100MB
        );

        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['ok' => true, 'data' => $result], JSON_UNESCAPED_UNICODE | JSON_UNESCAPED_SLASHES);
    } catch (Throwable $e) {
        http_response_code(400);
        header('Content-Type: application/json; charset=utf-8');
        echo json_encode(['ok' => false, 'error' => $e->getMessage()], JSON_UNESCAPED_UNICODE);
    }
} else {
    // 仅演示唯一文件名生成
    $originalFileName = "example.jpg";
    echo generateUniqueFileName($originalFileName);
}
```

**关键修改点（简要）**
1. 唯一名生成改用 `random_bytes()`（更安全、冲突概率更低），并规范化扩展名。
2. 增加完整上传流程：错误码校验、`is_uploaded_file` 校验、大小限制、扩展名白名单。
3. 自动创建上传目录、使用 `move_uploaded_file()` 安全落盘，并在极小概率冲突时重试生成文件名。

