<?php
declare(strict_types=1);

/**
 * 安全图片上传（可直接运行）
 * 用法：把本文件保存为 upload.php
 * 1) 通过浏览器表单上传：<input type="file" name="image">
 * 2) 或在 CLI 下运行：php upload.php test.jpg
 */

function ensure_dir(string $dir): void {
    if (!is_dir($dir)) {
        if (!mkdir($dir, 0755, true) && !is_dir($dir)) {
            throw new RuntimeException("无法创建目录: {$dir}");
        }
    }
}

function upload_image(array $file): array {
    $targetDir = __DIR__ . DIRECTORY_SEPARATOR . 'uploads' . DIRECTORY_SEPARATOR;
    ensure_dir($targetDir);

    // 1) 基础错误检查（真实上传会有 error 字段）
    if (isset($file['error']) && $file['error'] !== UPLOAD_ERR_OK) {
        return ['ok' => false, 'msg' => '上传错误码: ' . $file['error']];
    }

    if (empty($file['tmp_name']) || !is_file($file['tmp_name'])) {
        return ['ok' => false, 'msg' => '临时文件不存在'];
    }

    // 2) 关键：不要信任扩展名/原始文件名，使用“内容嗅探”判断是否为图片
    $finfo = new finfo(FILEINFO_MIME_TYPE);
    $mime  = $finfo->file($file['tmp_name']) ?: '';

    $allowed = [
        'image/jpeg' => 'jpg',
        'image/png'  => 'png',
        'image/gif'  => 'gif',
        'image/webp' => 'webp',
    ];

    if (!isset($allowed[$mime])) {
        return ['ok' => false, 'msg' => "不允许的文件类型: {$mime}"];
    }

    // 进一步校验：确保能被 GD/图片解析识别（防止伪造 MIME）
    if (@getimagesize($file['tmp_name']) === false) {
        return ['ok' => false, 'msg' => '文件不是有效图片'];
    }

    // 3) 限制大小（示例：5MB）
    $maxBytes = 5 * 1024 * 1024;
    $size = isset($file['size']) ? (int)$file['size'] : filesize($file['tmp_name']);
    if ($size === false || $size > $maxBytes) {
        return ['ok' => false, 'msg' => '文件过大（最大 5MB）'];
    }

    // 4) 生成安全文件名（不使用用户提供的 name），避免路径穿越/覆盖
    $safeName = bin2hex(random_bytes(16)) . '.' . $allowed[$mime];
    $target   = $targetDir . $safeName;

    // 5) 移动文件：Web 上传必须 is_uploaded_file + move_uploaded_file
    //    测试/CLI 场景允许 rename 以便可运行
    $moved = false;
    if (function_exists('is_uploaded_file') && is_uploaded_file($file['tmp_name'])) {
        $moved = move_uploaded_file($file['tmp_name'], $target);
    } else {
        // 非 HTTP 上传（例如 test_upload/CLI），用 rename/copy 模拟
        $moved = @rename($file['tmp_name'], $target) || @copy($file['tmp_name'], $target);
    }

    if (!$moved) {
        return ['ok' => false, 'msg' => '文件保存失败'];
    }

    // 6) 设置权限（可选）
    @chmod($target, 0644);

    return ['ok' => true, 'msg' => '上传成功', 'path' => 'uploads/' . $safeName, 'mime' => $mime];
}

// 测试上传文件的函数（可运行）
// 传入任意本地文件路径，尝试“上传”；若是 PHP/非图片会被拒绝
function test_upload(string $file_path): void {
    $file = [
        'name'     => basename($file_path), // 仅用于展示，不参与保存命名
        'tmp_name' => $file_path,
        'size'     => is_file($file_path) ? filesize($file_path) : 0,
        'error'    => UPLOAD_ERR_OK,
    ];

    $res = upload_image($file);
    header('Content-Type: text/plain; charset=utf-8');
    echo ($res['ok'] ? "OK: " : "FAIL: ") . $res['msg'] . PHP_EOL;
    if (!empty($res['path'])) {
        echo "Saved: {$res['path']}" . PHP_EOL;
        echo "MIME:  {$res['mime']}" . PHP_EOL;
    }
}

/* ---------- 入口：Web 表单 或 CLI 测试 ---------- */

// Web：通过 <input type="file" name="image"> 上传
if (PHP_SAPI !== 'cli') {
    header('Content-Type: text/plain; charset=utf-8');

    if ($_SERVER['REQUEST_METHOD'] === 'POST' && isset($_FILES['image'])) {
        $res = upload_image($_FILES['image']);
        echo ($res['ok'] ? "OK: " : "FAIL: ") . $res['msg'] . PHP_EOL;
        if (!empty($res['path'])) echo "Saved: {$res['path']}" . PHP_EOL;
        exit;
    }

    echo "请用 POST 上传文件字段名 image。\n";
    echo "示例表单：\n";
    echo "<form method=\"post\" enctype=\"multipart/form-data\">\n";
    echo "  <input type=\"file\" name=\"image\" />\n";
    echo "  <button type=\"submit\">Upload</button>\n";
    echo "</form>\n";
    exit;
}

// CLI：php upload.php /path/to/file
if ($argc >= 2) {
    test_upload($argv[1]);
} else {
    echo "用法: php " . basename(__FILE__) . " /path/to/image\n";
}
```

