下面给出一套可直接运行的 PHP 示例（含：用户注册、密码安全哈希入库、登录尝试记录时间与结果）。使用 SQLite 方便你本地一键跑通；上线时把 PDO DSN 换成 MySQL/PostgreSQL 即可。

## 1) 可运行代码：`app.php`

```php
<?php
declare(strict_types=1);

/**
 * 运行方式：
 *   php app.php
 *
 * 说明：
 * - 使用 SQLite：会在当前目录生成 database.sqlite
 * - 包含：注册、登录、登录尝试记录（时间/结果/IP/UA）
 */

final class Db {
    private \PDO $pdo;

    public function __construct(string $dsn) {
        $this->pdo = new \PDO($dsn);
        $this->pdo->setAttribute(\PDO::ATTR_ERRMODE, \PDO::ERRMODE_EXCEPTION);
        $this->pdo->setAttribute(\PDO::ATTR_DEFAULT_FETCH_MODE, \PDO::FETCH_ASSOC);
    }

    public function pdo(): \PDO {
        return $this->pdo;
    }
}

final class AuthService {
    public function __construct(private Db $db) {}

    public function migrate(): void {
        $sqlUsers = <<<SQL
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL UNIQUE,
  password_hash TEXT NOT NULL,
  created_at TEXT NOT NULL
);
SQL;

        $sqlLoginAttempts = <<<SQL
CREATE TABLE IF NOT EXISTS login_attempts (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  email TEXT NOT NULL,
  attempted_at TEXT NOT NULL,
  success INTEGER NOT NULL,
  ip TEXT,
  user_agent TEXT
);
SQL;

        $this->db->pdo()->exec($sqlUsers);
        $this->db->pdo()->exec($sqlLoginAttempts);
    }

    public function registerUser(string $email, string $password): array {
        $email = $this->normalizeEmail($email);
        $this->validateEmail($email);
        $this->validatePassword($password);

        // PHP 内置安全哈希（bcrypt/argon2 由环境决定；默认推荐 bcrypt/argon2）
        $hash = password_hash($password, PASSWORD_DEFAULT);
        if ($hash === false) {
            throw new \RuntimeException("Password hashing failed.");
        }

        $now = (new \DateTimeImmutable('now'))->format(\DateTimeInterface::ATOM);

        $stmt = $this->db->pdo()->prepare(
            "INSERT INTO users(email, password_hash, created_at) VALUES(:email, :hash, :created_at)"
        );

        try {
            $stmt->execute([
                ':email' => $email,
                ':hash' => $hash,
                ':created_at' => $now,
            ]);
        } catch (\PDOException $e) {
            // SQLite/MySQL 都可能抛 unique 约束异常，这里统一处理
            if (str_contains($e->getMessage(), 'UNIQUE') || str_contains($e->getMessage(), 'unique')) {
                throw new \InvalidArgumentException("Email already registered.");
            }
            throw $e;
        }

        return [
            'email' => $email,
            'created_at' => $now,
        ];
    }

    public function login(string $email, string $password, ?string $ip = null, ?string $userAgent = null): bool {
        $email = $this->normalizeEmail($email);

        $stmt = $this->db->pdo()->prepare("SELECT password_hash FROM users WHERE email = :email LIMIT 1");
        $stmt->execute([':email' => $email]);
        $row = $stmt->fetch();

        $success = false;
        if ($row && isset($row['password_hash'])) {
            $success = password_verify($password, $row['password_hash']);
        }

        $this->recordLoginAttempt($email, $success, $ip, $userAgent);
        return $success;
    }

    private function recordLoginAttempt(string $email, bool $success, ?string $ip, ?string $userAgent): void {
        $now = (new \DateTimeImmutable('now'))->format(\DateTimeInterface::ATOM);

        $stmt = $this->db->pdo()->prepare(
            "INSERT INTO login_attempts(email, attempted_at, success, ip, user_agent)
             VALUES(:email, :attempted_at, :success, :ip, :user_agent)"
        );

        $stmt->execute([
            ':email' => $email,
            ':attempted_at' => $now,
            ':success' => $success ? 1 : 0,
            ':ip' => $ip,
            ':user_agent' => $userAgent,
        ]);
    }

    private function normalizeEmail(string $email): string {
        return mb_strtolower(trim($email));
    }

    private function validateEmail(string $email): void {
        if (!filter_var($email, FILTER_VALIDATE_EMAIL)) {
            throw new \InvalidArgumentException("Invalid email.");
        }
    }

    private function validatePassword(string $password): void {
        // 你可以按业务加强：长度、复杂度、泄露密码库检测等
        if (mb_strlen($password) < 8) {
            throw new \InvalidArgumentException("Password must be at least 8 characters.");
        }
    }
}

// -------------------- Demo --------------------
$dbFile = __DIR__ . '/database.sqlite';
$db = new Db('sqlite:' . $dbFile);
$auth = new AuthService($db);
$auth->migrate();

// 注册示例
try {
    $user = $auth->registerUser("user@example.com", "securepassword123");
    echo "Registered:\n";
    print_r($user);
} catch (\Throwable $e) {
    echo "Register error: " . $e->getMessage() . PHP_EOL;
}

// 登录示例（成功/失败都会记录）
$ok1 = $auth->login("user@example.com", "securepassword123", "127.0.0.1", "CLI");
$ok2 = $auth->login("user@example.com", "wrongpass", "127.0.0.1", "CLI");

echo "Login success 1? " . ($ok1 ? "YES" : "NO") . PHP_EOL;
echo "Login success 2? " . ($ok2 ? "YES" : "NO") . PHP_EOL;

// 查看最近登录记录
$stmt = $db->pdo()->query("SELECT * FROM login_attempts ORDER BY id DESC LIMIT 5");
echo "Recent login attempts:\n";
print_r($stmt->fetchAll());
```

## 2) 关键修改点（相对原 Python 代码）
1. **密码加密**：用 PHP 内置 `password_hash()` / `password_verify()` 替代 `bcrypt` 库调用，默认算法更易维护且安全（会自动带盐）。
2. **落库实现**：补齐数据库操作，使用 **PDO + 预处理语句** 防 SQL 注入，并提供 `migrate()` 自动建表。
