```php
<?php
declare(strict_types=1);

/**
 * 安全上传：将用户给定的相对路径限制在 /uploads 根目录下，防止目录穿越。
 * $inputStream: 可读的文件流资源（例如 fopen(...) 或 $_FILES['file']['tmp_name'] 打开的流）
 * $relativePath: 用户指定的存储路径（相对路径）
 */
function upload_file($inputStream, string $relativePath, string $baseDir = __DIR__ . '/uploads'): void
{
    if (!is_resource($inputStream)) {
        throw new InvalidArgumentException('inputStream must be a valid stream resource.');
    }

    // 1) 规范化路径分隔符，去掉空字节
    $relativePath = str_replace(["\0", "\\", "\r", "\n"], ['', '/', '', ''], $relativePath);
    $relativePath = ltrim($relativePath, '/');

    // 2) 拒绝目录穿越与可疑片段（..、空段等）
    $parts = array_values(array_filter(explode('/', $relativePath), fn($p) => $p !== ''));
    foreach ($parts as $p) {
        if ($p === '.' || $p === '..') {
            throw new RuntimeException('Invalid path segment.');
        }
    }

    // 3) 仅允许安全字符（可按业务放宽）
    foreach ($parts as $p) {
        if (!preg_match('/^[a-zA-Z0-9._-]+$/', $p)) {
            throw new RuntimeException('Invalid characters in path.');
        }
    }

    // 4) 组合目标路径，并确保落在 baseDir 内
    $baseDir = rtrim($baseDir, '/');
    if (!is_dir($baseDir) && !mkdir($baseDir, 0755, true)) {
        throw new RuntimeException('Failed to create base upload directory.');
    }

    $targetPath = $baseDir . '/' . implode('/', $parts);
    $targetDir  = dirname($targetPath);

    if (!is_dir($targetDir) && !mkdir($targetDir, 0755, true)) {
        throw new RuntimeException('Failed to create target directory.');
    }

    // 5) 流式写入，避免一次性读入内存
    $out = fopen($targetPath, 'wb');
    if ($out === false) {
        throw new RuntimeException('Failed to open target file for writing.');
    }

    try {
        stream_copy_to_stream($inputStream, $out);
    } finally {
        fclose($out);
    }
}

// 示例：从本地文件流上传到 uploads/user/uploads/example.txt
$in = fopen(__DIR__ . '/example.txt', 'rb');
if ($in === false) {
    throw new RuntimeException('Failed to open example.txt');
}

upload_file($in, 'user/uploads/example.txt');
fclose($in);

echo "Uploaded successfully.\n";
```

