### index.php（安全输出标签 + CSP）
```php
<?php
declare(strict_types=1);

$assets = require __DIR__ . '/assets.php';

/**
 * 仅允许通过资源 ID 选择要加载的资源，避免任意 URL 注入
 * 实际项目中，这个列表应来自服务端配置/数据库（管理员维护），而不是用户输入。
 */
$requested = ['bootstrap_css', 'bootstrap_js'];

/**
 * 基础 CSP：只允许脚本/样式来自 self + jsdelivr
 * 你可以按实际 CDN 域名调整；更严格可使用 nonce/hash。
 */
header("Content-Security-Policy: default-src 'self'; script-src 'self' https://cdn.jsdelivr.net; style-src 'self' https://cdn.jsdelivr.net; object-src 'none'; base-uri 'self'; frame-ancestors 'none'");
header('X-Content-Type-Options: nosniff');
header('Referrer-Policy: strict-origin-when-cross-origin');

function renderAsset(array $asset): string
{
    // 强制 https
    if (!str_starts_with($asset['url'], 'https://')) {
        throw new RuntimeException('Only HTTPS assets are allowed.');
    }

    $url = htmlspecialchars($asset['url'], ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');
    $integrity = htmlspecialchars($asset['integrity'] ?? '', ENT_QUOTES | ENT_SUBSTITUTE, 'UTF-8');

    if (($asset['type'] ?? '') === 'css') {
        return sprintf(
            '<link rel="stylesheet" href="%s" integrity="%s" crossorigin="anonymous">',
            $url,
            $integrity
        );
    }

    if (($asset['type'] ?? '') === 'js') {
        return sprintf(
            '<script src="%s" integrity="%s" crossorigin="anonymous" defer></script>',
            $url,
            $integrity
        );
    }

    throw new RuntimeException('Unknown asset type.');
}

