  // 绝对过期：超过 7 天强制失效
  if (now - req.session.createdAt > ABSOLUTE_TIMEOUT_MS) {
    const sid = req.sessionID;
    req.session.destroy((_) => {
      res.clearCookie("sid");
      return res.status(401).json({ error: "Session expired (absolute timeout)" });
    });
    // 可选：记录审计日志
    console.log("Session absolute-expired:", sid);
    return;
  }

  next();
});

// ---- Auth helpers ----
function requireAuth(req, res, next) {
  if (!req.session?.user) return res.status(401).json({ error: "Unauthorized" });
  next();
}

// ---- Demo user store (replace with DB) ----
const USERS = new Map([
  ["alice", { id: "u1", username: "alice", password: "password123" }]
]);

// ---- Login: rotate session to prevent fixation ----
app.post("/api/login", async (req, res) => {
  const { username, password } = req.body ?? {};
  const u = USERS.get(username);
  if (!u || u.password !== password) return res.status(401).json({ error: "Bad credentials" });

  // rotate session id
  req.session.regenerate((err) => {
    if (err) return res.status(500).json({ error: "Failed to regenerate session" });

    req.session.user = { id: u.id, username: u.username };
    req.session.createdAt = Date.now();

    // 可选：绑定部分客户端特征（注意移动网络/代理会变）
    req.session.ua = req.get("user-agent") ?? "";
    req.session.ip = req.ip;

    res.json({ ok: true, user: req.session.user });
  });
});

// ---- Optional: detect suspicious changes ----
app.use((req, res, next) => {
  if (req.session?.user) {
    const ua = req.get("user-agent") ?? "";
    // UA 变化可疑（仅示例，生产需更谨慎）
    if (req.session.ua && req.session.ua !== ua) {
      const sid = req.sessionID;
      return req.session.destroy(() => {
        res.clearCookie("sid");
        console.log("Session killed due to UA change:", sid);
        res.status(401).json({ error: "Session invalidated" });
      });
    }
  }
  next();
});

// ---- Logout: server-side invalidation ----
app.post("/api/logout", requireAuth, (req, res) => {
  const sid = req.sessionID;
  req.session.destroy(() => {
    res.clearCookie("sid");
    console.log("Session destroyed:", sid);
    res.json({ ok: true });
  });
});

// ---- Example protected endpoint ----
app.get("/api/me", requireAuth, (req, res) => {
  res.json({ user: req.session.user });
});

const port = process.env.PORT ?? 3000;
app.listen(port, () => console.log(`Listening on http://127.0.0.1:${port}`));
