```bash
#!/usr/bin/env bash
set -euo pipefail

# 允许的支付方式白名单
readonly ALLOWED_GATEWAYS=("PAYPAL" "CREDIT_CARD")

is_allowed_gateway() {
  local g="${1:-}"
  for x in "${ALLOWED_GATEWAYS[@]}"; do
    [[ "$x" == "$g" ]] && return 0
  done
  return 1
}

is_positive_amount() {
  local a="${1:-}"
  [[ "$a" =~ ^[0-9]+([.][0-9]{1,2})?$ ]] && [[ "$a" != "0" ]] && return 0
  return 1
}

# 支付请求处理函数
# 规则：
# - paymentMethod 为显式入参（优先级最高）
# - PAYMENT_GATEWAY 仅可作为默认值（当 paymentMethod 为空时）
# - 若两者同时存在且不一致 -> 失败（防止环境变量“劫持”流程）
process_payment() {
  local paymentMethod="${1:-}"
  local paymentAmount="${2:-}"

  if ! is_positive_amount "$paymentAmount"; then
    echo "Invalid amount" >&2
    return 2
  fi

  local envGateway="${PAYMENT_GATEWAY:-}"

  if [[ -z "$paymentMethod" ]]; then
    paymentMethod="$envGateway"
  elif [[ -n "$envGateway" && "$envGateway" != "$paymentMethod" ]]; then
    echo "Gateway mismatch (arg=$paymentMethod env=$envGateway)" >&2
    return 3
  fi

  if ! is_allowed_gateway "$paymentMethod"; then
    echo "Unknown payment method" >&2
    return 1
  fi

  case "$paymentMethod" in
    PAYPAL)      echo "Using PayPal for payment of \$${paymentAmount}" ;;
    CREDIT_CARD) echo "Using Credit Card for payment of \$${paymentAmount}" ;;
  esac
}

# 仅当直接执行本文件时才运行（便于被测试文件 source）
if [[ "${BASH_SOURCE[0]}" == "$0" ]]; then
  process_payment "${1:-}" "${2:-}"
fi
```

