class ActivityTracker {
private:
    struct DailyActivity {
        std::string activityName;
        std::array<int, 7> durationMinutes{}; // 默认全 0，避免未初始化读取
    };

    std::vector<DailyActivity> activities;

public:
    void reserveActivities(std::size_t n) { activities.reserve(n); }

    void addActivity(std::string_view activityName) {
        // 直接原地构造，避免临时对象与一次拷贝/移动
        activities.emplace_back(DailyActivity{std::string(activityName), {}});
    }

    void displayWeeklyActivity(std::ostream& os = std::cout) const {
        for (const auto& activity : activities) {
            os << "Activity: " << activity.activityName << '\n';
            for (int day = 0; day < 7; ++day) {
                os << "Day " << (day + 1) << ": " << activity.durationMinutes[day] << " minutes\n";
            }
            os << '\n';
        }
    }
};

int main() {
    ActivityTracker tracker;
    tracker.reserveActivities(16); // 预留容量，减少扩容带来的重分配

    tracker.addActivity("Running");
    tracker.addActivity("Cycling");

    tracker.displayWeeklyActivity();
    return 0;
}
```

关键优化点（性能/正确性）：
1. **修复未初始化读取**：原代码 `durationMinutes[7]` 未初始化就输出，属于未定义行为；改为 `std::array<int,7> durationMinutes{}` 默认置 0。
2. **减少拷贝/移动**：`push_back(newActivity)` 改为 `emplace_back` 原地构造，避免临时对象带来的额外开销。
3. **减少不必要的字符串构造**：`addActivity` 接收 `std::string_view`，调用方传字面量/已有字符串时更轻量（内部仍存 `std::string`）。
4. **减少 I/O 刷新开销**：用 `'\n'` 替代 `std::endl`（`endl` 会强制 flush，慢）。
5. **可选预分配**：提供 `reserveActivities`，批量添加时显著减少 `vector` 扩容重分配成本。

