class Logger {
public:
    // 传值 + move：对右值/临时字符串可避免一次拷贝；对左值也只多一次可接受的拷贝
    void log(std::string message) {
        std::cout << "Log: " << message << '\n';
    }
};

// 原 unsafeMemoryManagement() 存在 use-after-free（未定义行为），直接移除并用 RAII 替代
void safeMemoryManagement() {
    auto logger = std::make_unique<Logger>();
    logger->log("This is a safe log message.");
}

int main() {
    safeMemoryManagement();
    return 0;
}
```

关键修改点（性能/稳定性）：
