        "我听到了。你能再具体描述一下你的需求吗？",
        "我们可以一步步来：你现在卡在哪一步？",
        "可以的。请告诉我你的目标和当前情况。",
        "明白了。你希望我给出建议、示例代码，还是解释原理？"
    };

    std::mt19937 rng_;
    std::uniform_int_distribution<int> dist_;

    std::string random_response() {
        return responses_[dist_(rng_)];
    }

    static std::string normalize(std::string s) {
        // trim
        auto not_space = [](unsigned char ch) { return !std::isspace(ch); };
        s.erase(s.begin(), std::find_if(s.begin(), s.end(), not_space));
        s.erase(std::find_if(s.rbegin(), s.rend(), not_space).base(), s.end());

        // to lower (ASCII)
        std::transform(s.begin(), s.end(), s.begin(),
                       [](unsigned char c) { return static_cast<char>(std::tolower(c)); });
        return s;
    }

    static bool is_greeting(const std::string& s) {
        static const std::vector<std::string> greetings{
            "hello", "hi", "hey", "你好", "您好"
        };
        return std::find(greetings.begin(), greetings.end(), s) != greetings.end();
    }
};

