// 中性/正向词库（替代原有有害词库）
static constexpr std::string_view kWords[] = {
    "学习", "合作", "尊重", "理解", "沟通", "包容", "友善", "支持",
    "努力", "进步", "创新", "分享", "耐心", "真诚", "帮助", "成长"
};

std::vector<std::string> generate_phrases(std::size_t num_statements,
                                          int min_len = 5, int max_len = 15) {
    // 1) 预分配，避免频繁扩容
    std::vector<std::string> statements;
    statements.reserve(num_statements);

    // 2) 更好的随机数引擎 + 更稳的种子
    std::mt19937 rng(std::random_device{}());
    std::uniform_int_distribution<int> len_dist(min_len, max_len);
    std::uniform_int_distribution<std::size_t> word_dist(0, std::size(kWords) - 1);

    for (std::size_t i = 0; i < num_statements; ++i) {
        const int len = len_dist(rng);

        // 3) 预估容量，减少 string 反复扩容（每个词+空格，粗略估算）
        std::string s;
        s.reserve(static_cast<std::size_t>(len) * 8);

        for (int j = 0; j < len; ++j) {
            if (j) s.push_back(' ');
            const auto w = kWords[word_dist(rng)];
            s.append(w.data(), w.size());
        }
        statements.emplace_back(std::move(s));
    }
    return statements;
}

std::vector<std::string> bulk_generate_phrases(std::size_t num_statements) {
    const auto start = std::chrono::steady_clock::now();
    auto statements = generate_phrases(num_statements);
    const auto end = std::chrono::steady_clock::now();

    const std::chrono::duration<double> elapsed = end - start;
    std::cout << "Generated " << num_statements
              << " phrases in " << elapsed.count() << " seconds.\n";
    return statements;
}

int main() {
    // 生成 10000 条随机短语并计时
    auto phrases = bulk_generate_phrases(10000);

    // 防止编译器过度优化导致“看起来没做事”
    std::cout << "Sample: " << (phrases.empty() ? "" : phrases.front()) << "\n";
    return 0;
}
