```cpp
#include <iostream>
#include <string>
#include <fstream>
#include <stdexcept>

// 模拟在线宠物医院类
class OnlinePetHospital {
public:
    void setUserMessage(const std::string& message) {
        userMessage = message;
    }

    void generateHTMLPage(const std::string& filePath = "index.html") const {
        std::ofstream htmlFile(filePath, std::ios::out | std::ios::trunc);
        if (!htmlFile.is_open()) {
            throw std::runtime_error("Failed to open output file: " + filePath);
        }

        htmlFile << "<!DOCTYPE html>\n"
                 << "<html>\n"
                 << "<head>\n"
                 << "  <meta charset=\"UTF-8\" />\n"
                 << "  <title>Online Pet Hospital</title>\n"
                 << "</head>\n"
                 << "<body>\n"
                 << "  <h1>Welcome to the Online Pet Hospital</h1>\n"
                 << "  <p>Consult with veterinarians and learn about your pet's health!</p>\n"
                 << "  <div id=\"user-message\">\n"
                 << "    " << escapeHtml(userMessage) << "\n"
                 << "  </div>\n"
                 << "</body>\n"
                 << "</html>\n";

        if (!htmlFile.good()) {
            throw std::runtime_error("Failed while writing to file: " + filePath);
        }
    }

private:
    // 修复点：对用户输入做 HTML 转义，避免 XSS/HTML 注入
    static std::string escapeHtml(const std::string& input) {
        std::string out;
        out.reserve(input.size());
        for (char c : input) {
            switch (c) {
                case '&':  out += "&amp;";  break;
                case '<':  out += "&lt;";   break;
                case '>':  out += "&gt;";   break;
                case '"':  out += "&quot;"; break;
                case '\'': out += "&#39;";  break;
                default:   out += c;        break;
            }
        }
        return out;
    }

    std::string userMessage;
};

int main() {
    try {
        OnlinePetHospital hospital;

        // 示例用户输入（可替换为真实输入）
        std::string userInputMessage = "My pet is feeling unwell. <script>alert('xss');</script>";

        hospital.setUserMessage(userInputMessage);
        hospital.generateHTMLPage("index.html");

        std::cout << "HTML page generated with sanitized user message.\n";
        return 0;
    } catch (const std::exception& ex) {
        std::cerr << "Error: " << ex.what() << "\n";
        return 1;
    }
}
```

关键修改点（问题与修复）：
1. **安全问题：HTML/脚本注入（XSS）**：原代码把用户输入直接写入 HTML。已增加 `escapeHtml()` 对 `& < > " '` 做转义，防止注入。
2. **健壮性问题：文件打开/写入未检查**：增加 `is_open()` 与写入后 `good()` 检查，失败时抛异常并在 `main` 捕获输出错误。
3. **HTML 兼容性**：补充 `<meta charset="UTF-8" />`，避免中文/特殊字符乱码。

