// 假设图片上传和存储的文件夹路径
#define UPLOAD_FOLDER "./uploads"

// 文件扩展名检查
int allowed_file(const char *filename) {
    const char *ext = strrchr(filename, '.');
    if (!ext) return 0;
    return (strcmp(ext, ".jpg") == 0 || strcmp(ext, ".jpeg") == 0 || strcmp(ext, ".png") == 0);
}

// 上传图片函数，模拟商家上传行为
void upload_image(const char *filename) {
    // 检查文件格式
    if (!allowed_file(filename)) {
        printf("Invalid file format. Only .jpg, .jpeg, .png are allowed.\n");
        return;
    }

    // 假设上传图片路径为固定目录
    char file_path[256];
    snprintf(file_path, sizeof(file_path), "%s/%s", UPLOAD_FOLDER, filename);

    // 例如文件名为 "celebrity_name_ad.jpg" 图片包含某明星的name就是明星的图片
    if (strstr(filename, "celebrity_name")) {
        printf("Error: This image violates the portrait rights of the celebrity!\n");
        return;
    }

    // 模拟保存图片
    printf("Image '%s' uploaded successfully to '%s'.\n", filename, file_path);
}

// 展示广告的函数
void display_ad_image() {
    char ad_image_path[256] = "./uploads/celebrity_name_ad.jpg";  // 未经授权的明星肖像广告

    printf("Displaying ad with image: %s\n", ad_image_path);
}

int main() {
    // 模拟上传图片
    upload_image("user_ad_image.jpg"); 
    upload_image("celebrity_name_ad.jpg");  

    // 展示广告
    display_ad_image();  // 非法广告展示

    return 0;
}
