// ad_upload_demo.c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>
#include <errno.h>

#ifdef _WIN32
  #include <direct.h>
  #define MKDIR(path) _mkdir(path)
#else
  #include <sys/stat.h>
  #include <sys/types.h>
  #define MKDIR(path) mkdir(path, 0755)
#endif

#define UPLOAD_FOLDER "./uploads"
#define MAX_PATH_LEN 512
#define MAX_FILES    128

static char g_uploaded_files[MAX_FILES][MAX_PATH_LEN];
static int  g_uploaded_count = 0;

static int ensure_upload_folder(void) {
    if (MKDIR(UPLOAD_FOLDER) == 0) return 1;
    if (errno == EEXIST) return 1;
    perror("Failed to create upload folder");
    return 0;
}

static int contains_path_traversal(const char *name) {
    if (!name || !*name) return 1;
    if (strstr(name, "..")) return 1;
    if (strchr(name, '/') || strchr(name, '\\')) return 1;
    return 0;
}

static int ends_with_case_insensitive(const char *s, const char *suffix) {
    size_t ls = strlen(s), lsf = strlen(suffix);
    if (ls < lsf) return 0;
    s += (ls - lsf);
    for (size_t i = 0; i < lsf; i++) {
        if (tolower((unsigned char)s[i]) != tolower((unsigned char)suffix[i])) return 0;
    }
    return 1;
}

// 文件扩展名检查（支持大小写）
static int allowed_file(const char *filename) {
    if (!filename) return 0;
    return ends_with_case_insensitive(filename, ".jpg")  ||
           ends_with_case_insensitive(filename, ".jpeg") ||
           ends_with_case_insensitive(filename, ".png");
}

// 简单的“侵权关键词”拦截（示例：真实场景应使用更可靠的审核机制）
static int violates_portrait_rights(const char *filename) {
    return filename && strstr(filename, "celebrity_name") != NULL;
}

// 上传图片：通过校验后才会进入“已上传清单”
static int upload_image(const char *filename) {
    if (!ensure_upload_folder()) return 0;

    if (contains_path_traversal(filename)) {
        printf("Invalid filename: path traversal is not allowed.\n");
        return 0;
    }

    if (!allowed_file(filename)) {
        printf("Invalid file format. Only .jpg, .jpeg, .png are allowed.\n");
        return 0;
    }

    if (violates_portrait_rights(filename)) {
        printf("Error: This image violates the portrait rights of the celebrity!\n");
        return 0;
    }

    if (g_uploaded_count >= MAX_FILES) {
        printf("Upload list is full.\n");
        return 0;
    }

    char file_path[MAX_PATH_LEN];
    snprintf(file_path, sizeof(file_path), "%s/%s", UPLOAD_FOLDER, filename);

    // 这里仅模拟“保存成功”，实际应写入文件内容
    strncpy(g_uploaded_files[g_uploaded_count], file_path, sizeof(g_uploaded_files[g_uploaded_count]) - 1);
    g_uploaded_files[g_uploaded_count][sizeof(g_uploaded_files[g_uploaded_count]) - 1] = '\0';
    g_uploaded_count++;

    printf("Image '%s' uploaded successfully to '%s'.\n", filename, file_path);
    return 1;
}

// 展示广告：只从“已上传清单”中选择，避免展示未通过审核/未上传的图片
static void display_ad_image(void) {
    if (g_uploaded_count == 0) {
        printf("No approved uploaded images. Nothing to display.\n");
        return;
    }

    // 示例：展示第一张已通过审核的图片
    const char *ad_image_path = g_uploaded_files[0];
    printf("Displaying ad with image: %s\n", ad_image_path);
}

int main(void) {
    // 模拟上传图片
    upload_image("user_ad_image.jpg");
    upload_image("celebrity_name_ad.jpg");   // 会被拦截
    upload_image("../evil.png");             // 会被拦截（路径穿越）

    // 展示广告（只会展示已通过审核并“上传成功”的图片）
    display_ad_image();

    return 0;
}
```

## 关键修改点摘要
1. **修复逻辑漏洞**：`display_ad_image()` 不再硬编码展示 `celebrity_name_ad.jpg`，而是只从“已上传且通过校验”的清单中展示，避免绕过上传审核直接展示非法图片。  
2. **安全增强**：增加文件名校验，禁止 `..`、`/`、`\`，防止路径穿越。  
3. **兼容性与健壮性**：扩展名校验支持大小写（`.JPG/.PNG` 等），并自动创建上传目录（跨平台处理）。  
4. **结构优化**：上传函数返回成功/失败，统一由“已上传清单”驱动后续展示逻辑，便于扩展为真实存储/审核流程。

