#include <algorithm>
#include <chrono>
#include <cctype>
#include <fstream>
#include <iomanip>
#include <iostream>
#include <mutex>
#include <optional>
#include <regex>
#include <sstream>
#include <string>
#include <unordered_map>
#include <utility>
#include <vector>

enum class LogLevel { TRACE, DEBUG, INFO, WARN, ERROR, FATAL, UNKNOWN };

static inline std::string toUpper(std::string s) {
    for (char& c : s) c = static_cast<char>(std::toupper(static_cast<unsigned char>(c)));
    return s;
}

static inline std::string trim(std::string s) {
    auto notSpace = [](unsigned char ch) { return !std::isspace(ch); };
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), notSpace));
    s.erase(std::find_if(s.rbegin(), s.rend(), notSpace).base(), s.end());
    return s;
}

static inline LogLevel parseLevel(const std::string& levelStr) {
    const std::string u = toUpper(levelStr);
    if (u == "TRACE") return LogLevel::TRACE;
    if (u == "DEBUG") return LogLevel::DEBUG;
    if (u == "INFO")  return LogLevel::INFO;
    if (u == "WARN" || u == "WARNING") return LogLevel::WARN;
    if (u == "ERROR") return LogLevel::ERROR;
    if (u == "FATAL") return LogLevel::FATAL;
    return LogLevel::UNKNOWN;
}

static inline const char* levelToString(LogLevel lv) {
    switch (lv) {
        case LogLevel::TRACE: return "TRACE";
        case LogLevel::DEBUG: return "DEBUG";
        case LogLevel::INFO:  return "INFO";
        case LogLevel::WARN:  return "WARN";
        case LogLevel::ERROR: return "ERROR";
        case LogLevel::FATAL: return "FATAL";
        default:              return "UNKNOWN";
    }
}

struct LogRecord {
    std::string timestamp;   // 原始时间戳字符串（也可扩展为 time_point）
    LogLevel level{LogLevel::UNKNOWN};
    std::string module;
    std::string message;
    std::unordered_map<std::string, std::string> kv; // 额外字段
};

class LogStore {
public:
    void add(LogRecord rec) {
        std::lock_guard<std::mutex> lk(mu_);
        records_.push_back(std::move(rec));
    }

    std::vector<LogRecord> queryByLevel(LogLevel lv) const {
        std::lock_guard<std::mutex> lk(mu_);
        std::vector<LogRecord> out;
        out.reserve(records_.size());
        for (const auto& r : records_) if (r.level == lv) out.push_back(r);
        return out;
    }

    std::vector<LogRecord> queryContains(const std::string& keyword) const {
        std::lock_guard<std::mutex> lk(mu_);
        std::vector<LogRecord> out;
        out.reserve(records_.size());
        for (const auto& r : records_) {
            if (r.message.find(keyword) != std::string::npos ||
                r.module.find(keyword) != std::string::npos) {
                out.push_back(r);
            }
        }
        return out;
    }

    bool saveToFile(const std::string& path) const {
        std::lock_guard<std::mutex> lk(mu_);
        std::ofstream ofs(path, std::ios::out | std::ios::trunc);
        if (!ofs) return false;

        for (const auto& r : records_) {
            ofs << r.timestamp << " [" << levelToString(r.level) << "] "
                << r.module << " - " << r.message;
            if (!r.kv.empty()) {
                ofs << " {";
                bool first = true;
                for (const auto& [k, v] : r.kv) {
                    if (!first) ofs << ", ";
                    first = false;
                    ofs << k << "=" << v;
                }
                ofs << "}";
            }
            ofs << "\n";
        }
        return true;
    }

    size_t size() const {
        std::lock_guard<std::mutex> lk(mu_);
        return records_.size();
    }

private:
    mutable std::mutex mu_;
    std::vector<LogRecord> records_;
};

class LogManager {
public:
    explicit LogManager(LogStore& store) : store_(store) {}

    // 你要补全的函数：读取一条日志文本，解析并存储
    // 支持格式示例：
    // 1) 2026-03-04 12:00:01.123 [INFO] Auth - login ok user=tom ip=1.2.3.4
    // 2) 2026-03-04T12:00:01Z [ERROR] Core - failed to open file path=/a/b code=13
    void readLogEntry(const std::string& logEntry) {
        const std::string line = trim(logEntry);
        if (line.empty()) return;

        // 解析：timestamp [LEVEL] module - message (可选 key=value...)
        // timestamp: 非贪婪到空格+[
        static const std::regex re(
            R"(^\s*(.+?)\s+\[([A-Za-z]+)\]\s+([^-\n\r]+?)\s*-\s*(.*)\s*$)"
        );

        std::smatch m;
        LogRecord rec;

        if (std::regex_match(line, m, re)) {
            rec.timestamp = trim(m[1].str());
            rec.level     = parseLevel(m[2].str());
            rec.module    = trim(m[3].str());

            std::string tail = trim(m[4].str());
            // 从 tail 中提取 key=value（以空格分隔），其余作为 message
            // 简单策略：从后往前识别连续的 key=value token
            // 例如: "login ok user=tom ip=1.2.3.4" -> message="login ok", kv={user,tom},{ip,1.2.3.4}
            std::vector<std::string> tokens;
            {
                std::istringstream iss(tail);
                std::string tok;
                while (iss >> tok) tokens.push_back(tok);
            }

            // 从末尾开始收集 key=value
            int i = static_cast<int>(tokens.size()) - 1;
            for (; i >= 0; --i) {
                const auto& tok = tokens[i];
                auto pos = tok.find('=');
                if (pos == std::string::npos || pos == 0 || pos == tok.size() - 1) break;
                std::string k = tok.substr(0, pos);
                std::string v = tok.substr(pos + 1);
                rec.kv.emplace(std::move(k), std::move(v));
            }

            // message 为 tokens[0..i] 拼回
            std::ostringstream oss;
            for (int j = 0; j <= i; ++j) {
                if (j) oss << ' ';
                oss << tokens[j];
            }
            rec.message = trim(oss.str());
        } else {
            // 兜底：无法解析则按 UNKNOWN 存储整行
            rec.timestamp = "";
            rec.level = LogLevel::UNKNOWN;
            rec.module = "UNKNOWN";
            rec.message = line;
        }

        store_.add(std::move(rec));
    }

private:
    LogStore& store_;
};

// -------------------- Demo main (可直接运行) --------------------
int main() {
    LogStore store;
    LogManager mgr(store);

    mgr.readLogEntry("2026-03-04 12:00:01.123 [INFO] Auth - login ok user=tom ip=1.2.3.4");
    mgr.readLogEntry("2026-03-04T12:00:02Z [ERROR] Core - failed to open file path=/a/b code=13");
    mgr.readLogEntry("bad line without expected format");

    std::cout << "Total records: " << store.size() << "\n";

    auto errors = store.queryByLevel(LogLevel::ERROR);
    std::cout << "ERROR records: " << errors.size() << "\n";
    for (const auto& r : errors) {
        std::cout << r.timestamp << " [" << levelToString(r.level) << "] "
                  << r.module << " - " << r.message << "\n";
    }

    store.saveToFile("logs_export.txt");
    std::cout << "Exported to logs_export.txt\n";
    return 0;
}
```

关键修改点（简要）：
1. **补全 `readLogEntry`**：用 `regex` 解析 `timestamp/[LEVEL]/module/message`，并从 message 尾部提取 `key=value` 扩展字段。
2. **引入 `LogStore/LogManager` 分层**：解析与存储解耦，便于后续扩展（过滤、持久化、并发）。
3. **线程安全与可持久化**：`LogStore` 内部加 `mutex`；提供 `saveToFile` 导出能力；提供基础查询接口。

