#include <iostream>
#include <memory>
#include <string>
#include <unordered_map>

class SmartHomeDevice {
public:
    SmartHomeDevice(std::string device_id, std::string name)
        : device_id_(std::move(device_id)), name_(std::move(name)) {
        std::cout << "Device " << name_ << " created.\n";
    }

    ~SmartHomeDevice() {
        std::cout << "Device " << name_ << " destroyed.\n";
    }

    const std::string& id() const { return device_id_; }
    const std::string& name() const { return name_; }

private:
    std::string device_id_;
    std::string name_;
};

class SmartHomeController {
public:
    void add_device(const std::string& device_id, const std::string& name) {
        auto device = std::make_shared<SmartHomeDevice>(device_id, name);
        devices_[device_id] = device;          // 强引用：保持对象存活
        weak_devices_[device_id] = device;     // 弱引用：不影响生命周期
    }

    void remove_device(const std::string& device_id) {
        auto it = devices_.find(device_id);
        if (it != devices_.end()) {
            devices_.erase(it); // 删除强引用：若无其他 shared_ptr，设备会立刻析构
            std::cout << "Device " << device_id << " removed.\n";
        } else {
            std::cout << "Device not found.\n";
        }
    }

    void control_device(const std::string& device_id, const std::string& command) const {
        auto it = devices_.find(device_id);
        if (it != devices_.end() && it->second) {
            std::cout << "Controlling device " << it->second->name()
                      << " with command: " << command << ".\n";
        } else {
            std::cout << "Device not found.\n";
        }
    }

    // 模拟：if 'light1' in controller.weak_devices
    bool weak_device_exists_and_alive(const std::string& device_id) const {
        auto it = weak_devices_.find(device_id);
        if (it == weak_devices_.end()) return false;
        return !it->second.expired(); // expired 表示对象已被释放
    }

private:
    std::unordered_map<std::string, std::shared_ptr<SmartHomeDevice>> devices_;
    std::unordered_map<std::string, std::weak_ptr<SmartHomeDevice>> weak_devices_;
};

int main() {
    SmartHomeController controller;

    // 添加设备
    controller.add_device("light1", "Living Room Light");
    controller.add_device("thermostat", "Smart Thermostat");

    // 控制设备
    controller.control_device("light1", "turn on");

    // 移除设备
    controller.remove_device("light1");

    // 尝试控制已被移除的设备
    controller.control_device("light1", "turn off");

    // 尝试访问弱引用的设备（如果设备已经被释放，则视为不存在/已回收）
    if (controller.weak_device_exists_and_alive("light1")) {
        std::cout << "Weak reference to device light1 still exists.\n";
    } else {
        std::cout << "Weak reference to device light1 has been garbage collected.\n";
    }

    return 0;
}
