static std::string trim(std::string s) {
    auto notSpace = [](unsigned char c) { return !std::isspace(c); };
    s.erase(s.begin(), std::find_if(s.begin(), s.end(), notSpace));
    s.erase(std::find_if(s.rbegin(), s.rend(), notSpace).base(), s.end());
    return s;
}

struct HttpResponse {
    long status_code = 0;
    std::unordered_map<std::string, std::string> headers; // lower-case key
    std::string body;
};

static size_t writeBodyCallback(char* ptr, size_t size, size_t nmemb, void* userdata) {
    auto* out = static_cast<std::string*>(userdata);
    out->append(ptr, size * nmemb);
    return size * nmemb;
}

static size_t headerCallback(char* buffer, size_t size, size_t nitems, void* userdata) {
    auto* headers = static_cast<std::unordered_map<std::string, std::string>*>(userdata);
    const size_t len = size * nitems;
    std::string line(buffer, len);

    // Header lines look like: "Key: value\r\n"
    auto pos = line.find(':');
    if (pos != std::string::npos) {
        std::string key = toLower(trim(line.substr(0, pos)));
        std::string value = trim(line.substr(pos + 1));
        // strip trailing CRLF
        while (!value.empty() && (value.back() == '\r' || value.back() == '\n')) value.pop_back();
        (*headers)[key] = value;
    }
    return len;
}

static std::optional<HttpResponse> httpGet(const std::string& url,
                                          const std::vector<std::string>& requestHeaders,
                                          long timeoutSeconds,
                                          std::string& errOut) {
    CURL* curl = curl_easy_init();
    if (!curl) {
        errOut = "curl_easy_init failed";
        return std::nullopt;
    }

    HttpResponse resp;
    curl_easy_setopt(curl, CURLOPT_URL, url.c_str());
    curl_easy_setopt(curl, CURLOPT_FOLLOWLOCATION, 1L);

    // timeouts
    curl_easy_setopt(curl, CURLOPT_TIMEOUT, timeoutSeconds);
    curl_easy_setopt(curl, CURLOPT_CONNECTTIMEOUT, timeoutSeconds);

    // capture body + headers
    curl_easy_setopt(curl, CURLOPT_WRITEFUNCTION, writeBodyCallback);
    curl_easy_setopt(curl, CURLOPT_WRITEDATA, &resp.body);
    curl_easy_setopt(curl, CURLOPT_HEADERFUNCTION, headerCallback);
    curl_easy_setopt(curl, CURLOPT_HEADERDATA, &resp.headers);

    // request headers
    curl_slist* slist = nullptr;
    for (const auto& h : requestHeaders) slist = curl_slist_append(slist, h.c_str());
    if (slist) curl_easy_setopt(curl, CURLOPT_HTTPHEADER, slist);

    // error buffer
    char errbuf[CURL_ERROR_SIZE];
    errbuf[0] = 0;
    curl_easy_setopt(curl, CURLOPT_ERRORBUFFER, errbuf);

    CURLcode code = curl_easy_perform(curl);
    if (code != CURLE_OK) {
        errOut = (errbuf[0] ? std::string(errbuf) : curl_easy_strerror(code));
        if (slist) curl_slist_free_all(slist);
        curl_easy_cleanup(curl);
        return std::nullopt;
    }

    curl_easy_getinfo(curl, CURLINFO_RESPONSE_CODE, &resp.status_code);

    if (slist) curl_slist_free_all(slist);
    curl_easy_cleanup(curl);
    return resp;
}

static std::optional<std::string> checkCspFrameAncestors(const HttpResponse& response) {
    auto it = response.headers.find("content-security-policy");
    if (it == response.headers.end()) {
        std::cout << "No CSP Header found.\n";
        return std::nullopt;
    }

    const std::string& csp = it->second;
    std::cout << "CSP Header found: " << csp << "\n";

    // split by ';' and find frame-ancestors directive
    std::stringstream ss(csp);
    std::string part;
