            return d;
        }
    }

    std::cout << "No Frame-Ancestors Directive found.\n";
    return std::nullopt;
}

static void testEmbedFromDomain(const std::string& domain, const std::optional<std::string>& referrer) {
    std::vector<std::string> headers;
    if (referrer.has_value()) {
