下面给出一个等价的 C++ 实现（HTTP 提交 + WebSocket 广播），并做了关键安全与结构优化：**不再向客户端推送拼接后的 HTML**，而是推送 **JSON 纯文本内容**，由前端自行渲染，从源头降低 XSS 风险。

## 可运行 C++ 代码（Crow + WebSocket）

> 依赖：`Crow`（header-only，含 WebSocket 支持）+ `asio`（Crow 自带/或系统提供）  
> 编译运行方式见文末。

**main.cpp**
```cpp
#include "crow_all.h"
#include <unordered_set>
#include <mutex>
#include <string>
#include <algorithm>

static std::unordered_set<crow::websocket::connection*> g_conns;
static std::mutex g_conns_mtx;

// 基础 HTML 转义，避免把用户输入当作 HTML 执行（防 XSS）
static std::string html_escape(const std::string& in) {
    std::string out;
    out.reserve(in.size());
    for (char c : in) {
        switch (c) {
            case '&': out += "&amp;"; break;
            case '<': out += "&lt;";  break;
            case '>': out += "&gt;";  break;
            case '"': out += "&quot;";break;
            case '\'':out += "&#39;"; break;
            default:  out += c;       break;
        }
    }
    return out;
}

// 简单限制长度，避免滥用
static std::string clamp_len(std::string s, size_t max_len) {
    if (s.size() > max_len) s.resize(max_len);
    return s;
}

int main() {
    crow::SimpleApp app;

    // WebSocket：客户端连接后用于接收实时新帖
    CROW_ROUTE(app, "/ws")
    .websocket()
    .onopen([&](crow::websocket::connection& conn) {
        std::lock_guard<std::mutex> lk(g_conns_mtx);
        g_conns.insert(&conn);
        // 这里可扩展：给新连接发送历史帖子
    })
    .onclose([&](crow::websocket::connection& conn, const std::string& /*reason*/) {
        std::lock_guard<std::mutex> lk(g_conns_mtx);
        g_conns.erase(&conn);
    })
    .onmessage([&](crow::websocket::connection& /*conn*/, const std::string& /*data*/, bool /*is_binary*/) {
        // 本例不需要客户端发消息；如需可在此处理
    });

    // HTTP：提交帖子（等价于 Flask 的 /submit POST）
    CROW_ROUTE(app, "/submit").methods(crow::HTTPMethod::Post)
    ([&](const crow::request& req) {
        // 支持 application/x-www-form-urlencoded
        crow::query_string qs(req.body);
        const char* content_c = qs.get("content");
        std::string content = content_c ? content_c : "";

        content = clamp_len(content, 2000);
        // 关键：转义后再广播（或直接广播原文，让前端用 textContent 渲染）
        std::string safe = html_escape(content);

        // 广播 JSON（不再广播 HTML）
        crow::json::wvalue msg;
        msg["type"] = "new_post";
        msg["content"] = safe;

        std::string payload = crow::json::dump(msg);

        {
            std::lock_guard<std::mutex> lk(g_conns_mtx);
            for (auto* c : g_conns) {
                c->send_text(payload);
            }
        }

        return crow::response(200, "Post submitted");
    });

    // 可选：提供一个简单首页，方便你本地测试
    CROW_ROUTE(app, "/")([] {
        // 前端用 textContent 插入，避免 innerHTML
        const char* page = R"HTML(
<!doctype html>
<html>
<head><meta charset="utf-8"><title>Mini Social</title></head>
<body>
  <h3>Post</h3>
