#include <sqlite3.h>

#include <iostream>
#include <optional>
#include <stdexcept>
#include <string>

static void check_sqlite(int rc, sqlite3* db, const char* msg) {
    if (rc != SQLITE_OK && rc != SQLITE_ROW && rc != SQLITE_DONE) {
        std::string err = msg;
        if (db) err += std::string(" | sqlite: ") + sqlite3_errmsg(db);
        throw std::runtime_error(err);
    }
}

static std::string trim(std::string s) {
    auto is_space = [](unsigned char c) { return std::isspace(c); };
    while (!s.empty() && is_space(s.front())) s.erase(s.begin());
    while (!s.empty() && is_space(s.back())) s.pop_back();
    return s;
}

// 简单脱敏：只保留首字符，其余用*替代（可按合规要求调整/移除）
static std::string mask_name(const std::string& name) {
    if (name.empty()) return name;
    std::string out;
    out.reserve(name.size());
    out.push_back(name[0]);
    for (size_t i = 1; i < name.size(); ++i) out.push_back('*');
    return out;
}

static void query_orders_and_customers(
    const std::string& db_path,
    const std::optional<long long>& order_id,
    const std::optional<std::string>& customer_name_like,
    bool mask_output = true
) {
    sqlite3* db = nullptr;
    check_sqlite(sqlite3_open(db_path.c_str(), &db), db, "open db failed");

    // 确保关闭数据库
    struct DbCloser {
        sqlite3* db;
        ~DbCloser() { if (db) sqlite3_close(db); }
    } db_closer{db};

    std::string sql =
        "SELECT orders.id, customers.name, orders.order_date, orders.total_amount "
        "FROM orders "
        "JOIN customers ON orders.customer_id = customers.id "
