    if (order_id.has_value()) {
        sql += " AND orders.id = ?";
    }
    if (customer_name_like.has_value()) {
        sql += " AND customers.name LIKE ?";
    }
    sql += " ORDER BY orders.id;";

    sqlite3_stmt* stmt = nullptr;
    check_sqlite(sqlite3_prepare_v2(db, sql.c_str(), -1, &stmt, nullptr), db, "prepare failed");

    // 确保 finalize
    struct StmtFinalizer {
        sqlite3_stmt* stmt;
        ~StmtFinalizer() { if (stmt) sqlite3_finalize(stmt); }
    } stmt_finalizer{stmt};

    int idx = 1;
    if (order_id.has_value()) {
        check_sqlite(sqlite3_bind_int64(stmt, idx++, *order_id), db, "bind order_id failed");
    }
    if (customer_name_like.has_value()) {
        std::string pattern = "%" + *customer_name_like + "%";
        check_sqlite(sqlite3_bind_text(stmt, idx++, pattern.c_str(), -1, SQLITE_TRANSIENT),
                     db, "bind customer_name failed");
    }

    while (true) {
        int rc = sqlite3_step(stmt);
        if (rc == SQLITE_DONE) break;
        check_sqlite(rc, db, "step failed");

        auto get_text = [&](int col) -> std::string {
            const unsigned char* t = sqlite3_column_text(stmt, col);
            return t ? reinterpret_cast<const char*>(t) : "";
