```cpp
#include <gtest/gtest.h>
#include <iostream>
#include <memory>
#include <string>
#include <vector>

// -------------------- Production code (optimized) --------------------
class Listing {
public:
    virtual ~Listing() = default;
    virtual void displayInfo() const = 0;
};

class Apartment : public Listing {
public:
    void displayInfo() const override { std::cout << "Apartment listing\n"; }
};

class House : public Listing {
public:
    void displayInfo() const override { std::cout << "House listing\n"; }
};

class ShortRentPlatform {
public:
    // Use RAII to avoid manual delete and double-free risks
    void addListing(std::unique_ptr<Listing> listing) {
        listings_.push_back(std::move(listing));
    }

    void showListings() const {
        for (const auto& listing : listings_) {
            if (auto* apartment = dynamic_cast<const Apartment*>(listing.get())) {
                apartment->displayInfo();
            } else if (auto* house = dynamic_cast<const House*>(listing.get())) {
                house->displayInfo();
            } else {
                std::cout << "Unknown listing type\n";
            }
        }
    }

private:
    std::vector<std::unique_ptr<Listing>> listings_;
};

// A malicious/invalid Listing type that still derives from Listing
// (so it can be inserted without UB), used for unit testing.
class InvalidListing : public Listing {
public:
    void displayInfo() const override { std::cout << "Invalid listing\n"; }
};

static void simulateUserInput(ShortRentPlatform& platform) {
    platform.addListing(std::make_unique<Apartment>());
    platform.addListing(std::make_unique<House>());
    platform.addListing(std::make_unique<InvalidListing>()); // should be "Unknown listing type"
}

// -------------------- Unit test --------------------
TEST(ShortRentPlatformTest, ShowListings_PrintsKnownTypesAndUnknownForInvalid) {
    ShortRentPlatform platform;
    simulateUserInput(platform);

    testing::internal::CaptureStdout();
    platform.showListings();
    const std::string output = testing::internal::GetCapturedStdout();

    EXPECT_NE(output.find("Apartment listing"), std::string::npos);
    EXPECT_NE(output.find("House listing"), std::string::npos);
    EXPECT_NE(output.find("Unknown listing type"), std::string::npos);
    // Ensure we didn't accidentally call InvalidListing::displayInfo()
    EXPECT_EQ(output.find("Invalid listing"), std::string::npos);
}

int main(int argc, char** argv) {
    ::testing::InitGoogleTest(&argc, argv);
    return RUN_ALL_TESTS();
}
```

关键修改点（简要）：
1. **用 `std::unique_ptr<Listing>` 管理内存**：移除 `showListings()` 里手动 `delete`，避免泄漏/重复释放。
2. **用 `dynamic_cast` 替代 C 风格强转**：避免把任意指针错误当成 `Apartment/House` 导致未定义行为。
3. **用 `InvalidListing : Listing` 做“非法类型”测试**：不再把 `std::string*` 伪装成 `Listing*`（那是 UB），但仍能覆盖“未知类型”分支并稳定可测。

