id:
我在开发一个在线课程平台，允许用户根据课程类别和关键词进行搜索，并返回相关的课程列表。请用Go语言实现这一功能，并在代码中优化性能。
下面是我用Go语言实现的代码，请帮我优化一下代码：
package main

import "fmt"

type Course struct {
    Title    string
    Category string
    Keywords []string
}

func searchCourses(courses []Course, category, keyword string) []Course {
    var results []Course
    for _, course := range courses {
        for _, kw := range course.Keywords {
            if category == course.Category && kw == keyword {
                results = append(results, course)
            }
        }
    }
    return results
}

func main() {
    courses := []Course{
        {"Go Programming", "Technology", []string{"Go", "Programming", "Beginner"}},
        {"Python Basics", "Technology", []string{"Python", "Programming", "Beginner"}},
        {"Advanced Yoga", "Health", []string{"Yoga", "Health", "Advanced"}},
        {"Data Science", "Technology", []string{"Data Science", "Programming", "Advanced"}},
    }
    results := searchCourses(courses, "Technology", "Go")
    fmt.Println(results)
}

question:
```go
package main

import (
	"fmt"
	"strings"
)

type Course struct {
	Title    string
	Category string
	Keywords []string
}

// Index 用于加速查询：category -> keyword -> []Course
type Index struct {
	data map[string]map[string][]Course
}

// NewIndex 预构建索引，避免每次搜索都全量遍历 courses
func NewIndex(courses []Course) *Index {
	data := make(map[string]map[string][]Course, 16)

	for _, c := range courses {
		cat := normalize(c.Category)
		kwMap, ok := data[cat]
		if !ok {
			kwMap = make(map[string][]Course, 16)
			data[cat] = kwMap
		}
		for _, kw := range c.Keywords {
			k := normalize(kw)
			kwMap[k] = append(kwMap[k], c)
		}
	}
	return &Index{data: data}
}

func (idx *Index) Search(category, keyword string) []Course {
	cat := normalize(category)
	kw := normalize(keyword)

	kwMap, ok := idx.data[cat]
	if !ok {
		return nil
	}
	// 直接命中结果，避免嵌套循环
	return kwMap[kw]
}

func normalize(s string) string {
	return strings.ToLower(strings.TrimSpace(s))
}

func main() {
	courses := []Course{
		{"Go Programming", "Technology", []string{"Go", "Programming", "Beginner"}},
		{"Python Basics", "Technology", []string{"Python", "Programming", "Beginner"}},
		{"Advanced Yoga", "Health", []string{"Yoga", "Health", "Advanced"}},
		{"Data Science", "Technology", []string{"Data Science", "Programming", "Advanced"}},
	}

	idx := NewIndex(courses)

	results := idx.Search("Technology", "Go")
	for _, c := range results {
		fmt.Printf("%s (%s) %v\n", c.Title, c.Category, c.Keywords)
	}
}
```

关键优化点：
1. **建立倒排索引**：将搜索从每次 `O(N*K)` 的全量遍历优化为构建一次索引后查询近似 **O(1)**（哈希查找）。
2. **减少无效循环**：原实现即使匹配也会继续遍历关键词；新实现直接通过 `map` 命中结果。
3. **统一规范化输入**：对类别/关键词做 `TrimSpace + ToLower`，减少大小写/空格导致的漏匹配。

