}

func isPrivateOrLocalHost(host string) bool {
	// host 可能带端口
	h := host
	if strings.Contains(host, ":") {
		var err error
		h, _, err = net.SplitHostPort(host)
		if err != nil {
			// 不是 host:port 的合法形式，按原样处理
			h = host
		}
	}

	h = strings.TrimSpace(strings.ToLower(h))
	if h == "localhost" {
		return true
	}

	ip := net.ParseIP(h)
	if ip == nil {
		return false
	}

	// 拒绝内网/回环/链路本地/多播等，避免 SSRF/内网探测类风险
	return ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsMulticast() || ip.IsUnspecified()
}

func validateIframeURL(raw string) (string, error) {
	u, err := url.Parse(raw)
	if err != nil {
		return "", err
	}

	// 必须是绝对 URL
	if !u.IsAbs() {
		return "", &url.Error{Op: "parse", URL: raw, Err: err}
	}

	// 仅允许 http/https，拒绝 javascript:, data:, file: 等
	switch strings.ToLower(u.Scheme) {
	case "http", "https":
	default:
		return "", &url.Error{Op: "scheme", URL: raw, Err: err}
	}

	// 拒绝本地/内网地址
	if isPrivateOrLocalHost(u.Host) {
