		}
	}

	// 规范化输出
	u.Fragment = "" // 一般不需要 fragment
	return u.String(), nil
}

func iframeHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	raw := r.URL.Query().Get("iframe_url")
	if strings.TrimSpace(raw) == "" {
		http.Error(w, "iframe_url is missing", http.StatusBadRequest)
		return
	}

	safeURL, err := validateIframeURL(raw)
	if err != nil {
		http.Error(w, "invalid iframe_url", http.StatusBadRequest)
		return
	}

	// 基础安全响应头（按需调整）
	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	w.Header().Set("X-Content-Type-Options", "nosniff")
	w.Header().Set("Referrer-Policy", "no-referrer")
