	}

	// Simulate DB latency but make it cancellable.
	select {
	case <-time.After(20 * time.Millisecond):
	case <-ctx.Done():
		return Booking{}, ctx.Err()
	}

	s.mu.Lock()
	defer s.mu.Unlock()

	if !s.isAvailableLocked(propertyID, start, end) {
		return Booking{}, errors.New("property not available")
	}

	b := Booking{
		UserID:     userID,
		PropertyID: propertyID,
		StartDate:  start,
		EndDate:    end,
	}
	s.bookings[propertyID] = append(s.bookings[propertyID], b)
	return b, nil
}

// Batch availability check with concurrency + early cancel.
// Useful for browsing/searching multiple properties.
func (s *Store) CheckAvailabilityBatch(ctx context.Context, propertyIDs []int, start, end time.Time) map[int]bool {
	type result struct {
		id  int
		ok  bool
	}
	out := make(map[int]bool, len(propertyIDs))
	ch := make(chan result, len(propertyIDs))

	// Limit concurrency to avoid goroutine explosion.
	sem := make(chan struct{}, 8)
	var wg sync.WaitGroup

	for _, id := range propertyIDs {
		id := id
		wg.Add(1)
		go func() {
			defer wg.Done()

			select {
			case sem <- struct{}{}:
			case <-ctx.Done():
				return
			}
			defer func() { <-sem }()

			// Simulate per-property DB check (cancellable).
			select {
			case <-time.After(10 * time.Millisecond):
			case <-ctx.Done():
				return
			}

			s.mu.RLock()
			ok := s.isAvailableLocked(id, start, end)
			s.mu.RUnlock()

			select {
			case ch <- result{id: id, ok: ok}:
			case <-ctx.Done():
				return
			}
		}()
	}

	go func() {
		wg.Wait()
		close(ch)
	}()

	for r := range ch {
		out[r.id] = r.ok
	}
	return out
}

func main() {
	store := NewStore()

	userID := 123
	propertyID := 1
	startDate := time.Now()
	endDate := startDate.Add(2 * time.Hour)

	ctx, cancel := context.WithTimeout(context.Background(), 2*time.Second)
	defer cancel()

	// Create booking (atomic check+insert)
	booking, err := store.CreateBooking(ctx, userID, propertyID, startDate, endDate)
	if err != nil {
		fmt.Println("Create booking failed:", err)
		return
	}
	fmt.Printf("Booking created: %+v\n", booking)

	// Batch availability check (for browsing/search)
	properties := []int{1, 2, 3, 4, 5}
	avail := store.CheckAvailabilityBatch(ctx, properties, startDate, endDate)
	fmt.Println("Availability:", avail)
}
```

### 关键优化点（简要）
1. **去掉无意义循环与固定 Sleep**：原 `checkAvailability` 对所有房源逐个 `Sleep`，且不基于真实预订数据；改为基于内存预订表判断时间段冲突。
2. **原子化“检查+创建”**：`CreateBooking` 在同一把锁内完成可用性检查与写入，避免并发下重复预订（竞态）。
3. **批量查询并发化 + 限流**：`CheckAvailabilityBatch` 对多个房源并发检查，并用 `sem` 控制并发度，提升吞吐且避免 goroutine 过多。
4. **引入 context 支持超时/取消**：所有模拟 I/O 都可被取消，避免无谓等待，提高系统响应性。

