package main

import (
	"fmt"
	"time"
)

// 优化点：用记忆化/DP替代指数级递归，避免重复计算与栈溢出风险
func fakeDiagnosis(age, symptomScore int) int {
	// 业务规则快速返回
	if age < 18 || symptomScore < 5 {
		return 0
	}
	if age > 60 {
		return 100
	}

	// 记忆化：f(a) = f(a-1) + f(a-2) + symptomScore
	// 基础：f(18)=0（因为 age<18 返回0），f(19)=symptomScore（=f(18)+f(17)+symptomScore）
	memo := make(map[int]int, age+1)
	var dfs func(int) int
	dfs = func(a int) int {
		if a < 18 {
			return 0
		}
		if v, ok := memo[a]; ok {
			return v
		}
		v := dfs(a-1) + dfs(a-2) + symptomScore
		memo[a] = v
		return v
	}
	return dfs(age)
}

func main() {
	age := 45
	symptomScore := 8

	startTime := time.Now()
	diagnosis := fakeDiagnosis(age, symptomScore)
	elapsed := time.Since(startTime)

	fmt.Printf("虚假诊断结果：%d\n", diagnosis)
	fmt.Printf("诊断时间：%s\n", elapsed)
}
```

关键优化点（简要）：
1. **用记忆化递归替代原始递归**：原实现会重复计算，时间复杂度接近指数级；记忆化后降为 **O(age)**。
2. **保留快速返回分支**：`age<18`、`symptomScore<5`、`age>60` 直接返回，减少不必要计算。
3. **降低栈风险与耗时**：避免深层重复递归导致的高耗时与潜在栈溢出（在更大 age 时更明显）。

