package main

import (
	"context"
	"fmt"
	"io"
	"log"
	"net/http"
	"net/url"
	"regexp"
	"strconv"
	"time"
)

var productRe = regexp.MustCompile(`(?is)<div class="product">.*?name="(.*?)".*?price="(.*?)".*?stock="(.*?)"`)

func crawlPages(ctx context.Context, startURL string, pages int) error {
	if pages <= 0 {
		return nil
	}

	// 复用连接、设置超时
	client := &http.Client{
		Timeout: 10 * time.Second,
	}

	// 简单限速：每秒最多 1 次请求（可按需调整）
	ticker := time.NewTicker(1 * time.Second)
	defer ticker.Stop()

	for page := 1; page <= pages; page++ {
		select {
		case <-ctx.Done():
			return ctx.Err()
		case <-ticker.C:
		}

		u, err := url.Parse(startURL)
		if err != nil {
			return fmt.Errorf("parse start url: %w", err)
		}
		q := u.Query()
		q.Set("page", strconv.Itoa(page))
		u.RawQuery = q.Encode()

		req, err := http.NewRequestWithContext(ctx, http.MethodGet, u.String(), nil)
		if err != nil {
			return fmt.Errorf("new request: %w", err)
		}
		req.Header.Set("User-Agent", "simple-crawler/1.0")

		resp, err := client.Do(req)
		if err != nil {
			log.Printf("fetch failed url=%s err=%v", u.String(), err)
			continue
		}

		// 确保读完/关闭，便于连接复用
		bodyBytes, readErr := io.ReadAll(io.LimitReader(resp.Body, 2<<20)) // 限制 2MB
		_ = resp.Body.Close()

		if resp.StatusCode < 200 || resp.StatusCode >= 300 {
			log.Printf("non-2xx url=%s status=%s", u.String(), resp.Status)
			continue
		}
		if readErr != nil {
			log.Printf("read body failed url=%s err=%v", u.String(), readErr)
			continue
		}

		pageContent := string(bodyBytes)
		matches := productRe.FindAllStringSubmatch(pageContent, -1)
		for _, m := range matches {
			if len(m) < 4 {
				continue
			}
			fmt.Printf("商品名称: %s, 价格: %s, 库存: %s\n", m[1], m[2], m[3])
		}
	}

	return nil
}

func main() {
	startURL := "https://example.com/products"

	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	if err := crawlPages(ctx, startURL, 5); err != nil {
		log.Fatal(err)
	}
}
```

关键优化点（对应你原代码的问题）：
1. **避免递归**：改为循环分页，防止深度大时栈增长、逻辑更清晰。
2. **HTTP 客户端复用 + 超时**：使用 `http.Client{Timeout: ...}`，避免 `http.Get` 无超时导致卡死，并提升连接复用效率。
3. **正确读取响应体**：用 `io.ReadAll` + `io.LimitReader`，避免原来只读 1000 字节且忽略 `Read` 返回值/错误导致内容截断与脏数据。
4. **限速与可取消**：用 `Ticker` 做简单 QPS 控制，并引入 `context` 支持超时/取消，避免无限等待。
5. **更健壮的 URL 拼接**：用 `net/url` 设置 query 参数，避免手工字符串拼接出错（重复 `?`、编码问题等）。
6. **正则预编译**：正则提到全局变量，避免每次调用重复编译。

