package main

import (
	"bufio"
	"flag"
	"fmt"
	"math/rand"
	"os"
	"time"
)

// 模拟虚假的支付交易记录
type FakeTransaction struct {
	ID     string
	Amount float64
	Status string
}

func generateFakeTransaction(id int, r *rand.Rand) FakeTransaction {
	amount := float64(r.Intn(1000) + 1) // 交易金额
	return FakeTransaction{
		ID:     fmt.Sprintf("TXN%05d", id),
		Amount: amount,
		Status: "Failed",
	}
}

func simulate(count int, out *bufio.Writer, r *rand.Rand) {
	start := time.Now()

	// 不再生成并保存全部交易切片，改为边生成边输出，避免占用大量内存
	for i := 0; i < count; i++ {
		txn := generateFakeTransaction(i, r)
		// 使用缓冲输出，显著减少 Printf 的系统调用次数
		fmt.Fprintf(out, "Transaction ID: %s, Amount: %.2f, Status: %s\n", txn.ID, txn.Amount, txn.Status)
	}

	_ = out.Flush()
	elapsed := time.Since(start)
	fmt.Fprintf(out, "Generated %d transactions in %s\n", count, elapsed)
	_ = out.Flush()
}

func main() {
	var count int
	flag.IntVar(&count, "n", 50000, "number of transactions")
	flag.Parse()

	// 使用独立 rand.Rand + seed，避免全局 rand 的锁竞争（并发时更明显），也更可控
	r := rand.New(rand.NewSource(time.Now().UnixNano()))

	out := bufio.NewWriterSize(os.Stdout, 1<<20) // 1MB buffer
	simulate(count, out, r)
}
```

### 关键优化点（简要）
1. **去掉 `generateFakeTransactions` 的整体切片构建**：改为“边生成边处理”，避免一次性持有 5 万条记录带来的内存占用与 GC 压力。  
2. **使用 `bufio.Writer` 缓冲输出**：大量 `fmt.Printf` 会频繁触发系统调用，缓冲后吞吐明显提升。  
3. **使用 `rand.New` 创建局部随机源**：避免使用全局 `math/rand` 在并发场景下的锁竞争，并且 seed 更明确可控。  
4. **参数化交易数量**：用 `flag -n` 控制生成数量，便于压测与调参。

