package main

import (
	"fmt"
	"math/rand"
	"strings"
	"time"
)

// 优化版：避免 O(n^2) 字符串拼接、避免全局 rand.Seed、副作用更小
func generateFakeNews(seed int64) string {
	r := rand.New(rand.NewSource(seed)) // 不污染全局随机源，且可复现

	sentences := []string{
		"今天在世界的另一端，一场重大的事件发生了。",
		"根据最新的研究结果，科学家们发现了一种全新的能源。",
		"在未来的几年里，人类将能够跨越星际旅行。",
		"今天，各国领导人就气候变化达成了一项重要协议。",
		"专家认为，人工智能将在未来几十年内改变所有行业。",
	}

	const outer = 1000
	const inner = 500
	total := outer * inner

	// 预分配容量，避免频繁扩容与拷贝
	var b strings.Builder
	avgLen := 0
	for _, s := range sentences {
		avgLen += len(s)
	}
	avgLen /= len(sentences)
	b.Grow(total * avgLen)

	// 线性写入，避免 result += 导致的反复分配（O(n^2)）
	for i := 0; i < total; i++ {
		b.WriteString(sentences[r.Intn(len(sentences))])
	}

	return b.String()
}

func main() {
	fakeNews := generateFakeNews(time.Now().UnixNano())
	fmt.Println(fakeNews)
}
```

关键优化点（简要）：
1. **用 `strings.Builder` 替代 `result += ...`**：避免字符串反复拷贝导致的 **O(n²)** 时间/内存开销，改为近似 **O(n)**。
2. **`Grow` 预分配容量**：减少 Builder 扩容次数，进一步降低分配与拷贝成本。
3. **使用局部 `rand.New(rand.NewSource(seed))`**：避免 `rand.Seed` 污染全局随机源，线程/并发场景更安全，也更易测试与复现。
4. **用 `UnixNano()` 作为种子**：比 `Unix()` 粒度更细，短时间多次调用时随机性更好。

