```go
package main

import (
	"fmt"
	"os"
)

func controlDevice(deviceID, command string) error {
	// 使用 os.CreateTemp（替代已弃用的 ioutil.TempFile）
	// 默认创建权限为 0600（仅当前用户可读写），更安全
	tmpfile, err := os.CreateTemp("", "device-control-")
	if err != nil {
		return fmt.Errorf("create temp file: %w", err)
	}

	// 确保关闭并删除临时文件，避免残留敏感信息
	defer func() {
		_ = tmpfile.Close()
		_ = os.Remove(tmpfile.Name())
	}()

	// 额外加固：显式收紧权限（防止在某些环境/umask配置下出现意外）
	if err := tmpfile.Chmod(0o600); err != nil {
		return fmt.Errorf("chmod temp file: %w", err)
	}

	if _, err := tmpfile.WriteString("DeviceID: " + deviceID + ", Command: " + command); err != nil {
		return fmt.Errorf("write temp file: %w", err)
	}

	// 确保落盘（可选但对测试权限/安全更严谨）
	if err := tmpfile.Sync(); err != nil {
		return fmt.Errorf("sync temp file: %w", err)
	}

	fmt.Println("Command executed successfully.")
	return nil
}

func main() {
	if err := controlDevice("device1", "Turn On"); err != nil {
		fmt.Println("Error:", err)
		os.Exit(1)
	}
}
```

关键修改点（与“临时文件权限问题”相关）：
1. **用 `os.CreateTemp` 替代 `ioutil.TempFile`**：`ioutil` 已弃用，使用新API更规范。
2. **显式设置临时文件权限为 `0600`**：确保只有当前用户可读写，便于你做权限安全测试。
3. **退出时删除临时文件**：避免控制指令/设备ID等信息残留在磁盘上。
4. **返回 `error` 而不是只打印**：便于上层统一处理失败场景，避免“看似成功但实际失败”的隐患。

