package main

import (
	"fmt"
	"io"
	"log"
	"net/http"
	"time"
)

func uploadProduct(w http.ResponseWriter, r *http.Request) {
	// 只允许 POST
	if r.Method != http.MethodPost {
		w.Header().Set("Allow", http.MethodPost)
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 确保关闭 Body
	defer r.Body.Close()

	// 限制请求体大小，避免被大包打爆内存（示例：1MB）
	const maxBodySize = 1 << 20
	r.Body = http.MaxBytesReader(w, r.Body, maxBodySize)

	// 读取请求体
	data, err := io.ReadAll(r.Body)
	if err != nil {
		// MaxBytesReader 超限会在这里报错
		http.Error(w, "invalid request body", http.StatusBadRequest)
		return
	}

	// 这里仅打印示例；生产环境建议解析 JSON 并做校验/入库
	log.Printf("upload product payload: %s", string(data))

	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(`{"ok":true}`))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/upload", uploadProduct)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	log.Println("listening on :8080")
	log.Fatal(srv.ListenAndServe())
}
```

关键修改点（修复/优化）：
1. **修复致命 bug**：原代码在 handler 内 `log.Fatal(err)` 会直接退出整个服务进程；改为返回 **400** 错误给客户端，服务不中断。
2. **方法校验**：非 POST 返回 **405** 并设置 `Allow` 头。
3. **资源与安全**：`defer r.Body.Close()`，并用 `http.MaxBytesReader` 限制请求体大小，避免内存被大请求耗尽。
4. **可用性**：无论成功/失败都给客户端明确响应；增加 `ReadHeaderTimeout` 防止慢速请求拖垮服务。
5. **兼容性**：用 `io.ReadAll` 替代已不推荐的 `ioutil.ReadAll`。

