下面给出一个可运行的、面向“上传配置文件”的 Go 实现，并修复你原代码中的关键问题（原代码用 `scp` 执行外部命令上传且文件名写死，存在严重安全风险与功能不匹配）。

## 可执行代码（HTTP 上传配置文件）

> 运行：`go run main.go`  
> 上传示例：`curl -F "file=@./config.yaml" http://localhost:8080/upload`

```go
package main

import (
	"crypto/sha256"
	"encoding/hex"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"strings"
	"time"
)

const (
	maxUploadSize = 5 << 20 // 5MB
	uploadDir     = "./uploads/configs"
)

type uploadResp struct {
	Filename string `json:"filename"`
	Size     int64  `json:"size"`
	SHA256   string `json:"sha256"`
	SavedAs  string `json:"saved_as"`
}

func main() {
	if err := os.MkdirAll(uploadDir, 0o755); err != nil {
		panic(err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /upload", uploadHandler)
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
	}

	fmt.Println("listening on http://localhost:8080")
	if err := srv.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		panic(err)
	}
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	// 限制请求体大小，避免内存/磁盘被打爆
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)
	if err := r.ParseMultipartForm(maxUploadSize); err != nil {
		http.Error(w, "invalid multipart form or file too large", http.StatusBadRequest)
		return
	}

	f, fh, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "missing form field 'file'", http.StatusBadRequest)
		return
	}
	defer f.Close()

	if err := validateConfigFile(fh); err != nil {
		http.Error(w, "invalid file: "+err.Error(), http.StatusBadRequest)
		return
	}

	// 生成安全文件名：时间戳 + 原始文件名（清理后）
	orig := sanitizeFilename(fh.Filename)
	saveName := fmt.Sprintf("%d_%s", time.Now().UnixNano(), orig)
	savePath := filepath.Join(uploadDir, saveName)

	// O_EXCL 防止覆盖；0600 避免其他用户读取敏感配置
	out, err := os.OpenFile(savePath, os.O_CREATE|os.O_WRONLY|os.O_EXCL, 0o600)
	if err != nil {
		http.Error(w, "failed to create file", http.StatusInternalServerError)
		return
	}
	defer out.Close()

	// 计算 hash + 写入文件
	h := sha256.New()
	n, err := io.Copy(io.MultiWriter(out, h), f)
	if err != nil {
		http.Error(w, "failed to save file", http.StatusInternalServerError)
		return
	}

	resp := uploadResp{
		Filename: orig,
		Size:     n,
		SHA256:   hex.EncodeToString(h.Sum(nil)),
		SavedAs:  saveName,
	}

	w.Header().Set("Content-Type", "application/json")
	_ = json.NewEncoder(w).Encode(resp)
}

func validateConfigFile(fh *multipart.FileHeader) error {
	// 仅允许常见配置文件后缀（可按业务扩展）
	ext := strings.ToLower(filepath.Ext(fh.Filename))
	switch ext {
	case ".yaml", ".yml", ".json", ".toml", ".ini", ".conf":
		return nil
	default:
		return fmt.Errorf("unsupported extension %q", ext)
	}
}

func sanitizeFilename(name string) string {
	// 去掉路径，防止 ../ 路径穿越
	name = filepath.Base(name)
	// 简单替换危险字符
	name = strings.ReplaceAll(name, string(os.PathSeparator), "_")
	name = strings.ReplaceAll(name, "..", "_")
	name = strings.TrimSpace(name)
	if name == "" {
		return "config"
	}
	return name
}
```

