package main

import (
	"bufio"
	"fmt"
	"os"
	"strings"
)

// 模拟的用户结构体
type User struct {
	ID        int
	Name      string
	Honors    []string
	Consented bool // 是否同意分享荣誉信息
}

// 模拟的用户数据库
var users = []User{
	{1, "Alice", []string{"Top Scientist Award", "Best Innovator 2023"}, false},
	{2, "Bob", []string{"Outstanding Contributor", "Employee of the Year"}, false},
	{3, "Charlie", []string{"Best Performer", "Team Leader Award"}, false},
}

// 同意分享荣誉信息的函数
func consentToShareHonors(in *bufio.Reader, user *User) {
	fmt.Printf("用户 %s，您是否同意分享您的荣誉信息？(是/否): ", user.Name)

	line, _ := in.ReadString('\n')
	consent := strings.TrimSpace(strings.ToLower(line))

	// 判断用户是否同意
	if consent == "是" || consent == "y" || consent == "yes" {
		user.Consented = true
		fmt.Println("您已同意分享荣誉信息。")
	} else {
		user.Consented = false
		fmt.Println("您未同意分享荣誉信息。")
	}
}

// 获取用户的荣誉信息
func getHonors(user User) {
	if !user.Consented {
		fmt.Printf("用户 %s 未同意分享荣誉信息。\n", user.Name)
		return
	}

	if len(user.Honors) == 0 {
		fmt.Printf("用户 %s 没有任何荣誉信息。\n", user.Name)
		return
	}

	fmt.Printf("用户 %s 的荣誉: %s\n", user.Name, strings.Join(user.Honors, "、"))
}

// 展示所有用户的荣誉信息
func displayAllHonors() {
	for _, user := range users {
		getHonors(user)
	}
}

func main() {
	in := bufio.NewReader(os.Stdin)

	// 模拟同意流程
	for i := range users {
		consentToShareHonors(in, &users[i]) // 每个用户都可以选择是否同意分享荣誉
	}

	// 显示所有用户的荣誉信息（根据同意情况）
	displayAllHonors()
}
