//
// 参数：
//   - r: 随机数生成器（建议由 main 统一创建并传入）
//   - topic: 主题，例如“气候变化”
//
// 返回：
//   - 随机生成的标题字符串
func generateTitle(r *rand.Rand, topic string) string {
	adj := adjectives[r.Intn(len(adjectives))]
	act := actions[r.Intn(len(actions))]
	ev := events[r.Intn(len(events))]
	return fmt.Sprintf("%s！%s %s的%s", adj, act, topic, ev)
}

// generateContent 基于标题生成随机内容。
//
// 参数：
