//
// 返回：
//   - 内容字符串（包含标题 + 换行 + 随机陈述句）
func generateContent(r *rand.Rand, title string) string {
	stmt := statements[r.Intn(len(statements))]
	return fmt.Sprintf("%s\n%s", title, stmt)
}

func main() {
	// 主题：可替换为任意字符串
	topic := "气候变化"

