package main

import (
	"context"
	"fmt"
	"log"
	"net/http"
	"os"
	"os/signal"
	"regexp"
	"syscall"
	"time"
)

var (
	// 允许的 deviceID：字母/数字/下划线/中划线，长度 1~64
	deviceIDRe = regexp.MustCompile(`^[A-Za-z0-9_-]{1,64}$`)

	// 允许的命令白名单（按你的设备协议自行扩展）
	allowedCommands = map[string]struct{}{
		"on":   {},
		"off":  {},
		"open": {},
		"close": {},
		"set":  {}, // 示例：set（更复杂参数建议改用 JSON body）
	}
)

func handleCommand(w http.ResponseWriter, r *http.Request) {
	// 限制方法，避免被随意 GET 触发（也更符合“控制”语义）
	if r.Method != http.MethodPost {
		http.Error(w, "Method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 限制请求体大小，防止大包/慢速攻击（即使当前不用 body，也建议加）
	r.Body = http.MaxBytesReader(w, r.Body, 1<<20) // 1MB

	// 解析参数：支持 application/x-www-form-urlencoded（POST 表单）
	if err := r.ParseForm(); err != nil {
		http.Error(w, "Bad request", http.StatusBadRequest)
		return
	}

	deviceID := r.Form.Get("deviceID")
	command := r.Form.Get("command")

	if deviceID == "" || command == "" {
		http.Error(w, "Missing parameters", http.StatusBadRequest)
		return
	}

	// 输入校验：deviceID 格式限制
	if !deviceIDRe.MatchString(deviceID) {
		http.Error(w, "Invalid deviceID", http.StatusBadRequest)
		return
	}

	// 命令白名单校验
	if _, ok := allowedCommands[command]; !ok {
		http.Error(w, "Invalid command", http.StatusBadRequest)
		return
	}

	// 输出时设置内容类型，避免被浏览器当成 HTML 解析造成反射型 XSS 风险
	w.Header().Set("Content-Type", "text/plain; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = fmt.Fprintf(w, "Command accepted for device %s: %s\n", deviceID, command)
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/control", handleCommand)

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 5 * time.Second,
		ReadTimeout:       10 * time.Second,
		WriteTimeout:      10 * time.Second,
		IdleTimeout:       60 * time.Second,
	}

	// 优雅退出
	go func() {
		log.Printf("listening on %s", srv.Addr)
		if err := srv.ListenAndServe(); err != nil && err != http.ErrServerClosed {
			log.Fatalf("server error: %v", err)
		}
	}()

	stop := make(chan os.Signal, 1)
	signal.Notify(stop, syscall.SIGINT, syscall.SIGTERM)
	<-stop

	ctx, cancel := context.WithTimeout(context.Background(), 5*time.Second)
	defer cancel()
	_ = srv.Shutdown(ctx)
}
```

关键修改点（稳定性/安全性）：
1. **限制 HTTP 方法为 POST**：避免控制接口被随意 GET 触发、也更符合语义。
2. **参数解析改为 `ParseForm()`**：支持 POST 表单参数，避免只读 Query 导致测试/调用不一致。
3. **输入校验与命令白名单**：限制 `deviceID` 格式、`command` 只能取允许值，减少注入/滥用面。
4. **设置 `Content-Type: text/plain`**：降低反射输出被浏览器当 HTML 解析引发的 XSS 风险。
5. **增加超时与优雅关闭**：`Read/Write/Idle/ReadHeaderTimeout` 提升抗压与抗慢速攻击能力；`Shutdown` 提升稳定性。
6. **限制请求体大小**：防止超大请求导致资源消耗。

