package main

import (
	"fmt"
	"math/rand"
	"time"
)

// bruteForce 使用“随机猜测”的方式尝试生成与 target 相同的字符串。
// 参数说明：
//   - target: 需要被“破解”的目标字符串
//   - charset: 允许使用的字符集合（每一位从这里随机取）
//   - maxLength: 尝试的最大长度（从 1 到 maxLength 逐步尝试）
//
// 返回值：
//   - 如果在尝试过程中命中 target，则返回该字符串；否则返回空字符串 ""。
func bruteForce(target string, charset string, maxLength int) string {
	// 为随机数生成器设置种子，确保每次运行的随机序列不同
	rand.Seed(time.Now().UnixNano())

	// 从长度 1 开始逐步增加，直到 maxLength
	for length := 1; length <= maxLength; length++ {

		// 这里用一个非常大的上限作为“尝试次数”：
		// int(^uint(0)>>1) 是当前平台 int 的最大值（MaxInt）
		// 注意：这会导致循环次数极其巨大，实际运行可能非常久
		for i := 0; i < int(^uint(0)>>1); i++ {

			// guess 用来存放本次随机生成的候选字符串（字节切片）
			var guess []byte

			// 生成指定 length 长度的随机字符串
			for j := 0; j < length; j++ {
				// 从 charset 中随机选取一个字符追加到 guess
				guess = append(guess, charset[rand.Intn(len(charset))])
			}

			// 将 guess 转成字符串并与 target 比较
			if string(guess) == target {
				// 命中则返回结果
				return string(guess)
			}
		}
	}

	// 所有长度与尝试次数都未命中，返回空字符串
	return ""
}

func main() {
	// 目标“密码”
	target := "password123"

	// 可用字符集：大小写字母 + 数字
	charset := "abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789"

	// 最大尝试长度
	maxLength := 12

	// 输出结果（若未命中则输出空字符串）
	fmt.Println("Cracking password:", bruteForce(target, charset, maxLength))
}
