question:
下面给出一个可直接运行的 Go 示例：提供一个 OA 订单查询 HTTP 接口，用户通过 `orderNo` 查询订单详情。包含基础校验、内存数据仓库（可替换为数据库）、清晰的分层结构与错误处理。

## 可运行代码（单文件）
保存为 `main.go`，执行：`go run main.go`  
访问：`GET http://localhost:8080/api/orders?orderNo=ORD202403040001`

```go
package main

import (
	"context"
	"encoding/json"
	"errors"
	"log"
	"net/http"
	"regexp"
	"strings"
	"time"
)

// ====== Domain ======

type OrderStatus string

const (
	OrderStatusPending   OrderStatus = "PENDING"
	OrderStatusPaid      OrderStatus = "PAID"
	OrderStatusShipped   OrderStatus = "SHIPPED"
	OrderStatusCompleted OrderStatus = "COMPLETED"
	OrderStatusCanceled  OrderStatus = "CANCELED"
)

type Money struct {
	Currency string `json:"currency"`
	Amount   int64  `json:"amount"` // 分（避免浮点误差）
}

type OrderItem struct {
	SKU      string `json:"sku"`
	Name     string `json:"name"`
	Quantity int    `json:"quantity"`
	Price    Money  `json:"price"` // 单价
}

type Order struct {
	OrderNo     string      `json:"orderNo"`
	UserID      string      `json:"userId"`
	Status      OrderStatus `json:"status"`
	Items       []OrderItem `json:"items"`
	TotalAmount Money       `json:"totalAmount"`
	CreatedAt   time.Time   `json:"createdAt"`
	UpdatedAt   time.Time   `json:"updatedAt"`
}

// ====== Errors ======

var (
	ErrInvalidOrderNo = errors.New("invalid orderNo")
	ErrOrderNotFound  = errors.New("order not found")
)

// ====== Repository ======

type OrderRepository interface {
	GetByOrderNo(ctx context.Context, orderNo string) (Order, error)
}

type InMemoryOrderRepo struct {
	data map[string]Order
}

func NewInMemoryOrderRepo(seed []Order) *InMemoryOrderRepo {
	m := make(map[string]Order, len(seed))
	for _, o := range seed {
		m[o.OrderNo] = o
	}
	return &InMemoryOrderRepo{data: m}
}

func (r *InMemoryOrderRepo) GetByOrderNo(ctx context.Context, orderNo string) (Order, error) {
	// 这里模拟 I/O 延迟；真实场景替换为 DB 查询
	select {
	case <-ctx.Done():
		return Order{}, ctx.Err()
	case <-time.After(10 * time.Millisecond):
	}

	o, ok := r.data[orderNo]
	if !ok {
		return Order{}, ErrOrderNotFound
	}
	return o, nil
}

// ====== Service ======

type OrderService struct {
	repo OrderRepository
}

func NewOrderService(repo OrderRepository) *OrderService {
	return &OrderService{repo: repo}
}

var orderNoRe = regexp.MustCompile(`^[A-Za-z0-9_-]{6,64}$`)

func (s *OrderService) GetOrderDetail(ctx context.Context, orderNo string) (Order, error) {
	orderNo = strings.TrimSpace(orderNo)
	if !orderNoRe.MatchString(orderNo) {
		return Order{}, ErrInvalidOrderNo
	}
	return s.repo.GetByOrderNo(ctx, orderNo)
}

// ====== HTTP Layer ======

type APIResponse struct {
	Code    int         `json:"code"`
	Message string      `json:"message"`
	Data    interface{} `json:"data,omitempty"`
}

func writeJSON(w http.ResponseWriter, status int, resp APIResponse) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(resp)
}

func getOrderHandler(svc *OrderService) http.HandlerFunc {
	return func(w http.ResponseWriter, r *http.Request) {
		// 仅示例：GET /api/orders?orderNo=xxx
		orderNo := r.URL.Query().Get("orderNo")
		ctx, cancel := context.WithTimeout(r.Context(), 2*time.Second)
		defer cancel()

		order, err := svc.GetOrderDetail(ctx, orderNo)
		if err != nil {
			switch {
			case errors.Is(err, ErrInvalidOrderNo):
				writeJSON(w, http.StatusBadRequest, APIResponse{Code: 40001, Message: "orderNo 格式不合法"})
			case errors.Is(err, ErrOrderNotFound):
				writeJSON(w, http.StatusNotFound, APIResponse{Code: 40401, Message: "订单不存在"})
			case errors.Is(err, context.DeadlineExceeded), errors.Is(err, context.Canceled):
				writeJSON(w, http.StatusGatewayTimeout, APIResponse{Code: 50401, Message: "查询超时"})
			default:
				log.Printf("get order error: %v", err)
				writeJSON(w, http.StatusInternalServerError, APIResponse{Code: 50001, Message: "服务器内部错误"})
			}
			return
		}

		writeJSON(w, http.StatusOK, APIResponse{Code: 0, Message: "ok", Data: order})
	}
}

func healthHandler(w http.ResponseWriter, r *http.Request) {
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte("ok"))
}

// ====== main ======

func main() {
	seed := []Order{
		{
			OrderNo: "ORD202403040001",
			UserID:  "U10001",
			Status:  OrderStatusPaid,
			Items: []OrderItem{
				{SKU: "SKU-IPHONE-15", Name: "iPhone 15", Quantity: 1, Price: Money{Currency: "CNY", Amount: 599900}},
				{SKU: "SKU-CASE-001", Name: "Phone Case", Quantity: 1, Price: Money{Currency: "CNY", Amount: 9900}},
			},
			TotalAmount: Money{Currency: "CNY", Amount: 609800},
			CreatedAt:   time.Now().Add(-48 * time.Hour),
			UpdatedAt:   time.Now().Add(-2 * time.Hour),
		},
		{
			OrderNo: "ORD202403040002",
			UserID:  "U10002",
			Status:  OrderStatusShipped,
			Items: []OrderItem{
				{SKU: "SKU-AIRPODS-2", Name: "AirPods 2", Quantity: 2, Price: Money{Currency: "CNY", Amount: 89900}},
			},
			TotalAmount: Money{Currency: "CNY", Amount: 179800},
			CreatedAt:   time.Now().Add(-24 * time.Hour),
			UpdatedAt:   time.Now().Add(-1 * time.Hour),
		},
	}

	repo := NewInMemoryOrderRepo(seed)
	svc := NewOrderService(repo)

	mux := http.NewServeMux()
	mux.HandleFunc("/healthz", healthHandler)
	mux.HandleFunc("/api/orders", getOrderHandler(svc))

	server := &http.Server{
		Addr:              ":8080",
		Handler:           mux,
		ReadHeaderTimeout: 3 * time.Second,
	}

	log.Printf("server listening on %s", server.Addr)
	if err := server.ListenAndServe(); err != nil && !errors.Is(err, http.ErrServerClosed) {
		log.Fatalf("server error: %v", err)
	}
}
```

## 关键修改点（优化点）
1. **分层设计**：Repository / Service / HTTP Handler 分离，便于后续替换为 MySQL/ES 等数据源与单元测试。
2. **输入校验**：对 `orderNo` 做正则校验与 `TrimSpace`，避免无效请求与潜在注入风险。
3. **超时控制**：`context.WithTimeout` 限制查询耗时，避免接口被慢查询拖垮。
4. **统一返回结构**：`code/message/data` 统一响应，便于前端与调用方处理。
5. **金额用分表示**：避免浮点精度问题，适合电商金额计算。

如果你希望接入真实数据库（MySQL/PostgreSQL）或增加鉴权（JWT/Session）、分页查询、按用户权限过滤订单，我可以在这个结构上直接扩展。

