```go
package main

import (
	"context"
	"fmt"
	"io"
	"net/http"
	"time"
)

func fetchProductData(url string) ([]byte, error) {
	// 关键：为整个请求设置超时，避免请求挂死
	ctx, cancel := context.WithTimeout(context.Background(), 8*time.Second)
	defer cancel()

	req, err := http.NewRequestWithContext(ctx, http.MethodGet, url, nil)
	if err != nil {
		return nil, err
	}

	// 关键：Client 也设置超时（双保险，覆盖连接/重定向等场景）
	client := &http.Client{
		Timeout: 8 * time.Second,
	}

	resp, err := client.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()

	// 关键：检查 HTTP 状态码，避免把错误页当成正常数据
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		// 读取少量响应体用于排错（避免大响应占用内存）
		b, _ := io.ReadAll(io.LimitReader(resp.Body, 4<<10))
		return nil, fmt.Errorf("unexpected status: %s, body: %s", resp.Status, string(b))
	}

	// 关键：限制读取大小，避免超大响应导致内存问题（按需调整上限）
	const maxBody = 2 << 20 // 2MB
	body, err := io.ReadAll(io.LimitReader(resp.Body, maxBody))
	if err != nil {
		return nil, err
	}

	return body, nil
}

func main() {
	url := "https://httpbin.org/json"
	data, err := fetchProductData(url)
	if err != nil {
		fmt.Println("fetch error:", err)
		return
	}
	fmt.Println(string(data))
}
```

关键修改点（简要）：
1. 增加 `context.WithTimeout` + `http.Client{Timeout: ...}`，防止请求无限阻塞。
2. 增加状态码校验，非 2xx 直接返回错误并附带少量响应体便于排查。
3. 使用 `io.LimitReader` 限制最大读取大小，避免大响应造成内存风险。
4. 使用 `io` 替代已弃用的 `ioutil`（Go 1.16+）。

