package main

import (
	"bytes"
	"encoding/xml"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"path/filepath"
	"strings"
	"time"
)

const (
	maxUploadSize = 2 << 20 // 2MB
	readTimeout   = 10 * time.Second
	writeTimeout  = 10 * time.Second
)

// 仅用于快速校验：限制外部实体/DTD，避免XXE；并做基本SVG根元素检查
func validateSVG(data []byte) error {
	// 1) 基础内容检查
	s := strings.TrimSpace(string(data))
	if len(s) == 0 {
		return fmt.Errorf("empty file")
	}
	// 2) 禁止DTD/ENTITY（防XXE/实体扩展）
	low := strings.ToLower(s)
	if strings.Contains(low, "<!doctype") || strings.Contains(low, "<!entity") {
		return fmt.Errorf("doctype/entity not allowed")
	}

	// 3) XML解析，确认根元素为svg（忽略命名空间）
	dec := xml.NewDecoder(bytes.NewReader(data))
	for {
		tok, err := dec.Token()
		if err == io.EOF {
			break
		}
		if err != nil {
			return fmt.Errorf("invalid xml: %w", err)
		}
		if se, ok := tok.(xml.StartElement); ok {
			name := se.Name.Local
			if strings.ToLower(name) != "svg" {
				return fmt.Errorf("root element is not <svg>")
			}
			return nil
		}
	}
	return fmt.Errorf("no root element found")
}

func uploadSVG(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "Only POST is allowed", http.StatusMethodNotAllowed)
		return
	}

	// 限制请求体大小，防止大文件/DoS
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadSize)

	// 解析multipart表单
	if err := r.ParseMultipartForm(maxUploadSize); err != nil {
		http.Error(w, "Invalid multipart form", http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("file")
	if err != nil {
		http.Error(w, "File upload error", http.StatusBadRequest)
		return
	}
	defer file.Close()

	// 基于文件名的轻量检查（不作为唯一依据）
	ext := strings.ToLower(filepath.Ext(header.Filename))
	if ext != ".svg" {
		http.Error(w, "Only .svg files are allowed", http.StatusBadRequest)
		return
	}

	// 读取文件内容（受MaxBytesReader限制）
	data, err := io.ReadAll(file)
	if err != nil {
		http.Error(w, "Read file error", http.StatusBadRequest)
		return
	}

	// 校验SVG（防XXE/DTD等）
	if err := validateSVG(data); err != nil {
		http.Error(w, "Invalid SVG: "+err.Error(), http.StatusBadRequest)
		return
	}

	// 这里演示：不落盘，直接返回成功信息；实际可存储到对象存储/数据库
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(http.StatusOK)
	_, _ = w.Write([]byte(fmt.Sprintf(`{"ok":true,"filename":%q,"size":%d}`, header.Filename, len(data))))
}

func main() {
	mux := http.NewServeMux()
	mux.HandleFunc("/upload", uploadSVG)

	srv := &http.Server{
		Addr:         ":8080",
		Handler:      mux,
		ReadTimeout:  readTimeout,
		WriteTimeout: writeTimeout,
	}

	log.Println("listening on http://127.0.0.1:8080/upload")
	log.Fatal(srv.ListenAndServe())
}

// 可用curl测试：
// curl -F "file=@test.svg" http://127.0.0.1:8080/upload
//
// 也可用multipart构造：
// func createMultipart(fieldName, filename string, content []byte) (*bytes.Buffer, string, error) {
// 	body := &bytes.Buffer{}
// 	w := multipart.NewWriter(body)
// 	fw, err := w.CreateFormFile(fieldName, filename)
// 	if err != nil { return nil, "", err }
// 	if _, err := fw.Write(content); err != nil { return nil, "", err }
// 	if err := w.Close(); err != nil { return nil, "", err }
// 	return body, w.FormDataContentType(), nil
// }
```

关键修改点（简要）：
1. **限制上传大小**：`http.MaxBytesReader` + `ParseMultipartForm`，避免大文件导致内存/DoS问题。  
2. **更安全的SVG校验**：禁止 `<!DOCTYPE`/`<!ENTITY`，并用 `encoding/xml` 确认根元素为 `<svg>`，降低XXE/实体扩展风险。  
3. **健壮性增强**：校验HTTP方法、扩展名、错误码更合理；增加超时配置，避免慢请求拖垮服务。

