下面是等价的 Go 实现（可直接运行），并对“在线文件管理系统”场景做了必要的安全优化：限制只能读取指定根目录下的文件，防止路径穿越（如 `../../etc/passwd`）。

## Go 代码（可运行）

```go
package main

import (
	"errors"
	"fmt"
	"os"
	"path/filepath"
	"strings"
)

// readFile 在 baseDir 目录范围内读取用户指定的相对路径文件内容（文本）
// - 防止路径穿越：确保最终路径仍在 baseDir 下
// - 返回文件内容字符串
func readFile(baseDir, userPath string) (string, error) {
	if userPath == "" {
		return "", errors.New("empty file path")
	}

	// 1) 规范化 baseDir
	baseAbs, err := filepath.Abs(baseDir)
	if err != nil {
		return "", err
	}
	baseAbs = filepath.Clean(baseAbs)

	// 2) 将用户输入当作“相对路径”处理：去掉可能的前导分隔符，避免被当成绝对路径
	userPath = filepath.Clean(userPath)
	userPath = strings.TrimLeft(userPath, string(os.PathSeparator))

	// 3) 拼接并得到目标绝对路径
	targetAbs, err := filepath.Abs(filepath.Join(baseAbs, userPath))
	if err != nil {
		return "", err
	}
	targetAbs = filepath.Clean(targetAbs)

	// 4) 校验：targetAbs 必须在 baseAbs 目录内
	rel, err := filepath.Rel(baseAbs, targetAbs)
	if err != nil {
		return "", err
	}
	if rel == "." || strings.HasPrefix(rel, ".."+string(os.PathSeparator)) || rel == ".." {
		return "", errors.New("path traversal detected")
	}

	// 5) 读取文件
	data, err := os.ReadFile(targetAbs)
	if err != nil {
		return "", err
	}
	return string(data), nil
}

func main() {
	// 只允许读取该目录下的文件（示例：./data）
	baseDir := "./data"

	// 示例：用户输入的文件路径（相对 baseDir）
	userInputPath := "example.txt"

	content, err := readFile(baseDir, userInputPath)
	if err != nil {
		fmt.Println("Error:", err)
		return
	}
	fmt.Println(content)
}
```

## 关键修改点（相对原 Python 版本）
1. **使用 `os.ReadFile` 读取文件内容**：等价于 Python 的 `open(...).read()`，更简洁。
2. **增加路径安全校验**：通过 `Clean/Join/Abs/Rel` 确保最终路径仍在 `baseDir` 下，防止路径穿越攻击。
3. **将用户输入强制按相对路径处理**：去掉前导分隔符，避免用户传入绝对路径绕过限制。

如果你希望支持二进制文件、按行读取、或限制最大读取大小（防止大文件占用内存），我也可以继续帮你改。

