下面是等价功能的 Go 实现（可直接运行），并做了必要的安全与健壮性优化（目录自动创建、文件名清理、大小限制、避免覆盖等）。

## 可运行 Go 代码（main.go）

```go
package main

import (
	"crypto/rand"
	"encoding/hex"
	"fmt"
	"io"
	"log"
	"mime/multipart"
	"net/http"
	"os"
	"path/filepath"
	"sort"
	"strings"
	"time"
)

const (
	uploadDir      = "uploads"
	maxUploadBytes = 10 << 20 // 10MB
)

func main() {
	// 确保上传目录存在
	if err := os.MkdirAll(uploadDir, 0o755); err != nil {
		log.Fatalf("create upload dir: %v", err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("/upload", uploadHandler)
	mux.HandleFunc("/images", listImagesHandler)

	addr := ":8080"
	log.Printf("listening on %s", addr)
	// 生产环境建议放在反向代理后并启用 HTTPS
	if err := http.ListenAndServe(addr, logging(mux)); err != nil {
		log.Fatal(err)
	}
}

func uploadHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodPost {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	// 限制请求体大小，防止大文件/DoS
	r.Body = http.MaxBytesReader(w, r.Body, maxUploadBytes)

	// 解析 multipart 表单
	if err := r.ParseMultipartForm(maxUploadBytes); err != nil {
		http.Error(w, "invalid multipart form or file too large", http.StatusBadRequest)
		return
	}

	file, header, err := r.FormFile("image")
	if err != nil {
		http.Error(w, "missing form field 'image'", http.StatusBadRequest)
		return
	}
	defer file.Close()

	safeName := sanitizeFilename(header.Filename)
	if safeName == "" {
		http.Error(w, "invalid filename", http.StatusBadRequest)
		return
	}

	// 避免同名覆盖：加时间戳+随机串
	finalName := uniqueName(safeName)
	dstPath := filepath.Join(uploadDir, finalName)

	dst, err := os.OpenFile(dstPath, os.O_CREATE|os.O_WRONLY|os.O_EXCL, 0o644)
	if err != nil {
		http.Error(w, "failed to create file", http.StatusInternalServerError)
		return
	}
	defer dst.Close()

	if _, err := io.Copy(dst, file); err != nil {
		http.Error(w, "failed to save file", http.StatusInternalServerError)
		return
	}

	w.WriteHeader(http.StatusOK)
	fmt.Fprintf(w, "Image %s uploaded successfully", finalName)
}

func listImagesHandler(w http.ResponseWriter, r *http.Request) {
	if r.Method != http.MethodGet {
		http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
		return
	}

	entries, err := os.ReadDir(uploadDir)
	if err != nil {
		http.Error(w, "failed to read uploads", http.StatusInternalServerError)
		return
	}

	var names []string
	for _, e := range entries {
		if e.IsDir() {
			continue
		}
		names = append(names, e.Name())
	}
	sort.Strings(names)

	w.Header().Set("Content-Type", "text/html; charset=utf-8")
	// 与 Flask 示例一致：用 <br> 拼接
	fmt.Fprint(w, strings.Join(names, "<br>"))
}

func sanitizeFilename(name string) string {
	// 去掉路径，防止 ../ 之类的路径穿越
	name = filepath.Base(name)
	name = strings.TrimSpace(name)

	// 简单白名单：只保留常见安全字符
	var b strings.Builder
	for _, r := range name {
		switch {
		case r >= 'a' && r <= 'z':
			b.WriteRune(r)
		case r >= 'A' && r <= 'Z':
			b.WriteRune(r)
		case r >= '0' && r <= '9':
			b.WriteRune(r)
		case r == '.' || r == '-' || r == '_' :
			b.WriteRune(r)
		}
	}
	return b.String()
}

func uniqueName(original string) string {
	ext := filepath.Ext(original)
	base := strings.TrimSuffix(original, ext)

	// 8字节随机串
	rnd := make([]byte, 8)
	_, _ = rand.Read(rnd)

	return fmt.Sprintf("%s_%d_%s%s", base, time.Now().UnixNano(), hex.EncodeToString(rnd), ext)
}

func logging(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		start := time.Now()
		next.ServeHTTP(w, r)
		log.Printf("%s %s %s", r.Method, r.URL.Path, time.Since(start))
	})
}

// 仅用于避免未使用导入（如果你删改代码时用到）
var _ multipart.File
```

## 运行方式

```bash
go mod init imgshare
go run main.go
```

上传示例：

```bash
curl -F "image=@/path/to/a.jpg" http://localhost:8080/upload
curl http://localhost:8080/images
```

## 关键修改点（相对原 Flask 版本的优化）
1. **自动创建 uploads 目录**：避免目录不存在导致保存失败。  
2. **限制上传大小**：`http.MaxBytesReader` + `ParseMultipartForm` 防止超大请求。  
3. **文件名安全处理**：`filepath.Base` + 字符白名单，防止路径穿越与奇怪文件名。  
4. **避免同名覆盖**：保存时生成唯一文件名（时间戳 + 随机串）并用 `O_EXCL` 确保不覆盖。  
5. **基础访问日志**：便于调试与排查请求。

