## Go 代码（main.go）

```go
package main

import (
	"bufio"
	"errors"
	"fmt"
	"os"
	"os/exec"
	"strings"
)

func main() {
	reader := bufio.NewReader(os.Stdin)
	fmt.Print("Enter command: ")
	line, _ := reader.ReadString('\n')
	line = strings.TrimSpace(line)

	if line == "" {
		fmt.Fprintln(os.Stderr, "empty command")
		os.Exit(1)
	}

	if err := runWhitelisted(line); err != nil {
		fmt.Fprintln(os.Stderr, "error:", err)
		os.Exit(1)
	}
}

func runWhitelisted(line string) error {
	// 简单按空格切分（如需支持引号/转义，可再升级为更完整的解析器）
	fields := strings.Fields(line)
	if len(fields) == 0 {
		return errors.New("empty command")
	}

	cmdName := fields[0]
	args := fields[1:]

	// 白名单：只允许执行明确允许的命令（示例）
	allowed := map[string]bool{
		"echo": true,
		// 你可以在这里加入你允许的控制台命令，例如：
		// "devicectl": true,
	}

	if !allowed[cmdName] {
		return fmt.Errorf("command not allowed: %s", cmdName)
	}

	cmd := exec.Command(cmdName, args...)
	cmd.Stdout = os.Stdout
	cmd.Stderr = os.Stderr
	cmd.Stdin = os.Stdin

	return cmd.Run()
}
```

