func TestUploadImage_Success(t *testing.T) {
	// 构造一个最小 SVG 文件内容
	svg := `<svg xmlns="http://www.w3.org/2000/svg" width="1" height="1"></svg>`

	// 组装 multipart/form-data 请求体
	var body bytes.Buffer
	writer := multipart.NewWriter(&body)

	part, err := writer.CreateFormFile("image", "test.svg")
	if err != nil {
		t.Fatalf("CreateFormFile: %v", err)
	}
	if _, err := io.Copy(part, strings.NewReader(svg)); err != nil {
		t.Fatalf("write svg: %v", err)
	}
	if err := writer.Close(); err != nil {
		t.Fatalf("writer.Close: %v", err)
	}

	req := httptest.NewRequest(http.MethodPost, "/upload", &body)
	req.Header.Set("Content-Type", writer.FormDataContentType())

	rr := httptest.NewRecorder()
	uploadImage(rr, req)

	if rr.Code != http.StatusOK {
		t.Fatalf("expected status 200, got %d, body=%s", rr.Code, rr.Body.String())
	}

	// 由于原实现把 file(Reader) 直接传给模板 {{.}}，模板会输出类似 "&{...}"，
	// 并不会输出 base64；这里按“当前代码行为”做断言，确保页面结构正确。
	resp := rr.Body.String()
	if !strings.Contains(resp, `<img src="data:image/svg+xml;base64,`) {
		t.Fatalf("expected img data url prefix, got body=%s", resp)
	}
	if !strings.Contains(resp, `</html>`) {
		t.Fatalf("expected html output, got body=%s", resp)
	}

	// 额外校验：如果未来修复为真正 base64，这里给出期望值（不强制）
	_ = base64.StdEncoding.EncodeToString([]byte(svg))
}

func TestUploadImage_MissingFile(t *testing.T) {
	req := httptest.NewRequest(http.MethodPost, "/upload", nil)
	rr := httptest.NewRecorder()

	uploadImage(rr, req)

	if rr.Code != http.StatusBadRequest {
		t.Fatalf("expected status 400, got %d, body=%s", rr.Code, rr.Body.String())
	}
	if !strings.Contains(rr.Body.String(), "Unable to read file") {
		t.Fatalf("expected error message, got body=%s", rr.Body.String())
	}
}
