question:
下面给出一个可直接运行的 Go 在线注册功能示例（HTTP API + SQLite），包含：用户名/邮箱唯一性校验、密码强度校验、bcrypt 加密存储、基础输入校验、事务写入与错误处理。

## 实现思路（简要）
1. **HTTP 接口**：`POST /register` 接收 JSON：`username/password/email`。  
2. **输入校验**：检查必填、长度、邮箱格式、密码长度等。  
3. **安全存储**：使用 `bcrypt` 对密码哈希后入库，绝不存明文。  
4. **唯一性约束**：数据库层对 `username/email` 建唯一索引，避免并发下重复注册。  
5. **事务与错误映射**：插入失败时识别唯一约束冲突，返回 409；其他返回 500。  

---

## 可运行代码（单文件）
> 运行：`go run main.go`  
> 依赖：`go get github.com/mattn/go-sqlite3 golang.org/x/crypto/bcrypt`

```go
package main

import (
	"context"
	"database/sql"
	"encoding/json"
	"errors"
	"fmt"
	"log"
	"net/http"
	"regexp"
	"strings"
	"time"

	_ "github.com/mattn/go-sqlite3"
	"golang.org/x/crypto/bcrypt"
)

type RegisterRequest struct {
	Username string `json:"username"`
	Password string `json:"password"`
	Email    string `json:"email"`
}

type APIError struct {
	Error string `json:"error"`
}

type APISuccess struct {
	ID       int64  `json:"id"`
	Username string `json:"username"`
	Email    string `json:"email"`
}

var (
	emailRe = regexp.MustCompile(`^[A-Za-z0-9._%+\-]+@[A-Za-z0-9.\-]+\.[A-Za-z]{2,}$`)
)

func main() {
	db, err := sql.Open("sqlite3", "file:app.db?_foreign_keys=on&_busy_timeout=5000")
	if err != nil {
		log.Fatal(err)
	}
	defer db.Close()

	if err := initSchema(db); err != nil {
		log.Fatal(err)
	}

	mux := http.NewServeMux()
	mux.HandleFunc("POST /register", func(w http.ResponseWriter, r *http.Request) {
		registerHandler(db, w, r)
	})
	mux.HandleFunc("GET /healthz", func(w http.ResponseWriter, r *http.Request) {
		w.WriteHeader(http.StatusOK)
		_, _ = w.Write([]byte("ok"))
	})

	srv := &http.Server{
		Addr:              ":8080",
		Handler:           withJSON(withRequestLimit(mux, 1<<20)), // 1MB
		ReadHeaderTimeout: 5 * time.Second,
	}

	log.Println("listening on http://127.0.0.1:8080")
	log.Fatal(srv.ListenAndServe())
}

func initSchema(db *sql.DB) error {
	// SQLite：用 UNIQUE 约束保证并发下也不会重复
	schema := `
CREATE TABLE IF NOT EXISTS users (
  id INTEGER PRIMARY KEY AUTOINCREMENT,
  username TEXT NOT NULL,
  email TEXT NOT NULL,
  password_hash TEXT NOT NULL,
  created_at TEXT NOT NULL
);

CREATE UNIQUE INDEX IF NOT EXISTS idx_users_username ON users(username);
CREATE UNIQUE INDEX IF NOT EXISTS idx_users_email ON users(email);
`
	_, err := db.Exec(schema)
	return err
}

func registerHandler(db *sql.DB, w http.ResponseWriter, r *http.Request) {
	ctx, cancel := context.WithTimeout(r.Context(), 5*time.Second)
	defer cancel()

	var req RegisterRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		writeJSON(w, http.StatusBadRequest, APIError{Error: "invalid json"})
		return
	}

	req.Username = strings.TrimSpace(req.Username)
	req.Email = strings.TrimSpace(strings.ToLower(req.Email))

	if err := validateRegister(req); err != nil {
		writeJSON(w, http.StatusBadRequest, APIError{Error: err.Error()})
		return
	}

	// bcrypt 哈希
	hash, err := bcrypt.GenerateFromPassword([]byte(req.Password), bcrypt.DefaultCost)
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, APIError{Error: "failed to hash password"})
		return
	}

	tx, err := db.BeginTx(ctx, &sql.TxOptions{Isolation: sql.LevelSerializable})
	if err != nil {
		writeJSON(w, http.StatusInternalServerError, APIError{Error: "failed to start transaction"})
		return
	}
	defer tx.Rollback()

	now := time.Now().UTC().Format(time.RFC3339)
	res, err := tx.ExecContext(ctx,
		`INSERT INTO users(username, email, password_hash, created_at) VALUES(?,?,?,?)`,
		req.Username, req.Email, string(hash), now,
	)
	if err != nil {
		// SQLite 唯一约束冲突通常包含 "UNIQUE constraint failed"
		if isUniqueViolation(err) {
			writeJSON(w, http.StatusConflict, APIError{Error: "username or email already exists"})
			return
		}
		writeJSON(w, http.StatusInternalServerError, APIError{Error: "failed to create user"})
		return
	}

	if err := tx.Commit(); err != nil {
		writeJSON(w, http.StatusInternalServerError, APIError{Error: "failed to commit"})
		return
	}

	id, _ := res.LastInsertId()
	writeJSON(w, http.StatusCreated, APISuccess{
		ID:       id,
		Username: req.Username,
		Email:    req.Email,
	})
}

func validateRegister(req RegisterRequest) error {
	if req.Username == "" || req.Password == "" || req.Email == "" {
		return errors.New("username/password/email required")
	}
	if len(req.Username) < 3 || len(req.Username) > 32 {
		return errors.New("username length must be 3-32")
	}
	// 简单用户名字符限制（可按需放宽）
	for _, c := range req.Username {
		if !(c == '_' || c == '-' || (c >= '0' && c <= '9') || (c >= 'a' && c <= 'z') || (c >= 'A' && c <= 'Z')) {
			return errors.New("username contains invalid characters")
		}
	}
	if len(req.Password) < 8 || len(req.Password) > 72 {
		// bcrypt 对输入长度有效上限约 72 bytes
		return errors.New("password length must be 8-72")
	}
	if !emailRe.MatchString(req.Email) {
		return errors.New("invalid email")
	}
	return nil
}

func isUniqueViolation(err error) bool {
	msg := err.Error()
	return strings.Contains(msg, "UNIQUE constraint failed") ||
		strings.Contains(msg, "constraint failed") ||
		strings.Contains(strings.ToLower(msg), "unique")
}

func writeJSON(w http.ResponseWriter, status int, v any) {
	w.Header().Set("Content-Type", "application/json; charset=utf-8")
	w.WriteHeader(status)
	_ = json.NewEncoder(w).Encode(v)
}

func withJSON(next http.Handler) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		// 基础安全头（可按需扩展）
		w.Header().Set("X-Content-Type-Options", "nosniff")
		next.ServeHTTP(w, r)
	})
}

func withRequestLimit(next http.Handler, maxBytes int64) http.Handler {
	return http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
		r.Body = http.MaxBytesReader(w, r.Body, maxBytes)
		next.ServeHTTP(w, r)
	})
}
```

