      const displayMap = Object.fromEntries(
        fields.map(f => [f, document.querySelector(`[data-field="${f}"]`)])
      );

      const STORAGE_KEY = "profile.v1";

      function getFormData() {
        const fd = new FormData(form);
        return Object.fromEntries(fields.map(k => [k, String(fd.get(k) ?? "").trim()]));
      }

      function render(profile) {
        for (const k of fields) displayMap[k].textContent = profile[k] || "";
      }

      function load() {
        try {
          const raw = localStorage.getItem(STORAGE_KEY);
          if (!raw) return;
          const profile = JSON.parse(raw);
          for (const k of fields) {
            if (typeof profile[k] === "string") form.elements[k].value = profile[k];
          }
          render(getFormData());
        } catch { /* ignore */ }
