        saveBtn.disabled = true;
        setStatus("保存中...");

        try {
          const res = await fetch(form.action, {
            method: "POST",
            headers: { "Content-Type": "application/json" },
            body: JSON.stringify(profile),
          });

          if (!res.ok) throw new Error("HTTP " + res.status);
          setStatus("已保存到服务器。");
        } catch (err) {
