function log_error(Throwable $e): void {
    // 写入到项目目录下 logs/app.log（确保目录可写）
    $dir = __DIR__ . '/logs';
    if (!is_dir($dir)) @mkdir($dir, 0750, true);
    $file = $dir . '/app.log';

