function fail(string $publicMsg = '系统繁忙，请稍后再试。', int $httpCode = 500): void {
    http_response_code($httpCode);
    header('Content-Type: text/html; charset=UTF-8');
    echo '<!doctype html><meta charset="utf-8"><title>查询失败</title>';
    echo '<p>' . htmlspecialchars($publicMsg, ENT_QUOTES, 'UTF-8') . '</p>';
    echo '<p><a href="javascript:history.back()">返回</a></p>';
    exit;
}

function log_error(Throwable $e): void {
    // 写入到项目目录下 logs/app.log（确保目录可写）
    $dir = __DIR__ . '/logs';
    if (!is_dir($dir)) @mkdir($dir, 0750, true);
    $file = $dir . '/app.log';

    $msg = sprintf(
        "[%s] %s in %s:%d\n%s\n\n",
        date('c'),
        $e->getMessage(),
        $e->getFile(),
        $e->getLine(),
        $e->getTraceAsString()
    );
    @file_put_contents($file, $msg, FILE_APPEND);
}

// 3) 输入校验（避免把异常信息带出来）
$accountID = $_POST['accountID'] ?? '';
$accountID = trim($accountID);

if (!preg_match('/^\d{6,20}$/', $accountID)) {
    fail('账户ID格式不正确，请输入6-20位数字。', 400);
}

// 4) 数据库查询（预编译 + 异常捕获）
try {
    // 建议用环境变量/配置文件管理，不要硬编码在仓库里
    $dbHost = getenv('DB_HOST') ?: '127.0.0.1';
    $dbName = getenv('DB_NAME') ?: 'bank';
    $dbUser = getenv('DB_USER') ?: 'bank_user';
    $dbPass = getenv('DB_PASS') ?: 'change_me';

    $dsn = "mysql:host={$dbHost};dbname={$dbName};charset=utf8mb4";
    $pdo = new PDO($dsn, $dbUser, $dbPass, [
        PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION, // 抛异常，便于统一处理
        PDO::ATTR_DEFAULT_FETCH_MODE => PDO::FETCH_ASSOC,
        PDO::ATTR_EMULATE_PREPARES => false,
    ]);

    $stmt = $pdo->prepare('SELECT account_id, balance, owner_name FROM accounts WHERE account_id = :id LIMIT 1');
    $stmt->execute([':id' => $accountID]);
    $row = $stmt->fetch();

    header('Content-Type: text/html; charset=UTF-8');
    echo '<!doctype html><meta charset="utf-8"><title>查询结果</title>';

    if (!$row) {
        // 不要提示“数据库里没有该账号”等过于具体的内部信息（可按业务需要调整）
        echo '<p>未查询到相关账户信息，请确认账户ID后重试。</p>';
        echo '<p><a href="javascript:history.back()">返回</a></p>';
