    }

    // 输入获取与校验
    $comment = $_POST['comment'] ?? '';
    $comment = trim($comment);

    if ($comment === '') {
        $errors[] = '评论不能为空。';
    } elseif (mb_strlen($comment, 'UTF-8') > 1000) {
        $errors[] = '评论过长（最多 1000 字）。';
