```php
<?php
// post_tweet.php
session_start();
if (!isset($_SESSION['tweets'])) {
  $_SESSION['tweets'] = [];
}

if ($_SERVER['REQUEST_METHOD'] !== 'POST') {
  http_response_code(405);
  exit('Method Not Allowed');
}

$content = trim($_POST['content'] ?? '');
$tagsRaw = trim($_POST['tags'] ?? '');

if ($content === '') {
  header('Location: index.php');
  exit;
}

// 规范化标签：按逗号分隔、去空、限制字符（避免奇怪控制字符/过长）
$tags = [];
if ($tagsRaw !== '') {
  foreach (preg_split('/\s*,\s*/u', $tagsRaw) as $tag) {
    $tag = trim($tag);
    if ($tag === '') continue;

    // 只允许常见安全字符：中文/字母/数字/下划线/短横线
    // 你也可以按业务放宽，但“输出时转义”仍必须保留
    if (!preg_match('/^[\p{Han}A-Za-z0-9_-]{1,30}$/u', $tag)) {
      continue;
    }
    $tags[] = $tag;
    if (count($tags) >= 10) break;
  }
}

$id = count($_SESSION['tweets']) + 1;
$_SESSION['tweets'][] = [
  'id' => $id,
  'content' => $content,
  'tags' => $tags,
];

header('Location: index.php');
exit;
```

