```js
// app.js
(() => {
  const input = document.getElementById('mediaInput');
  const clearBtn = document.getElementById('clearBtn');
  const statusEl = document.getElementById('status');
  const imgEl = document.getElementById('previewImage');
  const videoEl = document.getElementById('previewVideo');

  let currentObjectUrl = null;

  const setStatus = (msg) => { statusEl.textContent = msg || ''; };

  const resetPreview = () => {
    imgEl.style.display = 'none';
    imgEl.removeAttribute('src');

    videoEl.pause();
    videoEl.style.display = 'none';
    videoEl.removeAttribute('src');
    videoEl.load();

    if (currentObjectUrl) {
      URL.revokeObjectURL(currentObjectUrl);
      currentObjectUrl = null;
    }
    setStatus('');
    input.value = '';
  };

  const formatBytes = (bytes) => {
    const units = ['B', 'KB', 'MB', 'GB'];
    let i = 0, n = bytes;
    while (n >= 1024 && i < units.length - 1) { n /= 1024; i++; }
    return `${n.toFixed(i === 0 ? 0 : 2)} ${units[i]}`;
  };

  input.addEventListener('change', () => {
    const file = input.files && input.files[0];
    if (!file) return;

    // 基础安全/稳定性限制：避免超大文件导致页面卡顿（可按需调整）
    const MAX_SIZE = 200 * 1024 * 1024; // 200MB
    if (file.size > MAX_SIZE) {
      resetPreview();
      setStatus(`文件过大：${formatBytes(file.size)}（上限 ${formatBytes(MAX_SIZE)}）`);
      return;
    }

    // 清理旧预览
    if (currentObjectUrl) {
      URL.revokeObjectURL(currentObjectUrl);
      currentObjectUrl = null;
    }
    imgEl.style.display = 'none';
    videoEl.style.display = 'none';

    const type = file.type || '';
    currentObjectUrl = URL.createObjectURL(file);

    if (type.startsWith('image/')) {
      imgEl.src = currentObjectUrl;
      imgEl.style.display = 'block';
      setStatus(`已选择图片：${file.name}（${formatBytes(file.size)}）`);
    } else if (type.startsWith('video/')) {
      videoEl.src = currentObjectUrl;
      videoEl.style.display = 'block';
      setStatus(`已选择视频：${file.name}（${formatBytes(file.size)}）`);
    } else {
      // 不支持的类型
      URL.revokeObjectURL(currentObjectUrl);
      currentObjectUrl = null;
      resetPreview();
      setStatus('不支持的文件类型，请选择图片或视频。');
    }
  });

  clearBtn.addEventListener('click', resetPreview);

  // 页面卸载时释放 blob URL
  window.addEventListener('beforeunload', () => {
    if (currentObjectUrl) URL.revokeObjectURL(currentObjectUrl);
  });
})();
```

**关键修改点（简要）**
1. **更安全的 CSP**：移除 `unsafe-inline`，并将预览所需资源限制为 `blob:`（图片允许 `data:` 以兼容部分场景），禁用 `object-src`，防止被嵌入（`frame-ancestors 'none'`）。
2. **本地预览实现**：使用 `URL.createObjectURL(file)` 生成 blob URL，分别在 `<img>` / `<video>` 中展示。
3. **资源释放与清理**：切换文件/清除/离开页面时 `URL.revokeObjectURL`，避免内存泄漏；同时重置 video 状态。
4. **基础防护**：限制最大文件大小、校验 MIME 类型，避免异常文件导致卡顿或错误展示。

