import java.time.LocalDateTime;
import java.time.format.DateTimeFormatter;
import java.time.format.DateTimeParseException;
import java.util.*;

/**
 * 在线心理咨询服务（内存版示例）
 * 目标：更低内存占用、更高执行效率、更少装箱/字符串转换、更少临时对象
 */
public class OnlineCounselingServiceOptimized {

    // 用强类型对象替代 Map<String,String>，减少 HashMap/Entry/字符串键带来的内存与CPU开销
    private static final Map<Integer, Counselor> counselors = new HashMap<>(16);
    private static final Map<Integer, Appointment> appointments = new HashMap<>(32);
    private static final Map<Integer, Record> records = new HashMap<>(32);

    // 自增ID避免 appointments.size()+1 的 O(1)但不安全/可能重复问题
    private static int nextAppointmentId = 1;

    private static final DateTimeFormatter APPOINTMENT_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm");

    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {

            // 初始化示例咨询师
            addCounselor(1, "张老师", "情绪管理", "123456");
            addCounselor(2, "李老师", "人际关系", "abcdef");

            while (true) {
                System.out.println("请选择操作：1. 咨询师注册 2. 咨询预约 3. 查看咨询师排班 4. 存储咨询记录 5. 退出");
                int choice = readInt(scanner);

                switch (choice) {
                    case 1 -> {
                        System.out.println("请输入咨询师ID：");
                        int counselorId = readInt(scanner);
                        System.out.println("请输入咨询师姓名：");
                        String counselorName = readLine(scanner);
                        System.out.println("请输入专业领域：");
                        String specialty = readLine(scanner);
                        System.out.println("请输入密码：");
                        String password = readLine(scanner);
                        registerCounselor(counselorId, counselorName, specialty, password);
                    }
                    case 2 -> {
                        System.out.println("请输入来访者ID：");
                        int clientId = readInt(scanner);
                        System.out.println("请输入咨询师ID：");
                        int counselorIdToAppoint = readInt(scanner);
                        System.out.println("请输入预约时间（格式：yyyy-MM-dd HH:mm）：");
                        String appointmentTime = readLine(scanner);
                        makeAppointment(clientId, counselorIdToAppoint, appointmentTime);
                    }
                    case 3 -> {
                        System.out.println("以下是咨询师排班信息：");
                        listCounselorSchedules();
                    }
                    case 4 -> {
                        System.out.println("请输入记录ID：");
                        int recordId = readInt(scanner);
                        System.out.println("请输入咨询师ID：");
                        int counselorIdForRecord = readInt(scanner);
                        System.out.println("请输入来访者ID：");
                        int clientIdForRecord = readInt(scanner);
                        System.out.println("请输入咨询内容摘要：");
                        String contentSummary = readLine(scanner);
                        storeRecord(recordId, counselorIdForRecord, clientIdForRecord, contentSummary);
                    }
                    case 5 -> {
                        System.out.println("感谢使用，已退出平台。");
                        return;
                    }
                    default -> System.out.println("无效的选择，请重新输入。");
                }
            }
        }
    }

    // ---------- 数据模型（强类型，减少内存碎片与字符串键查找） ----------
    private record Counselor(int id, String name, String specialty, String password) {}

    private record Appointment(int id, int clientId, int counselorId, LocalDateTime time) {}

    private record Record(int id, int counselorId, int clientId, String contentSummary) {}

    // ---------- 业务方法 ----------
    private static void addCounselor(int counselorId, String counselorName, String specialty, String password) {
        counselors.put(counselorId, new Counselor(counselorId, counselorName, specialty, password));
    }

    private static void registerCounselor(int counselorId, String counselorName, String specialty, String password) {
        if (counselors.containsKey(counselorId)) {
            System.out.println("该咨询师ID已存在，注册失败。");
            return;
        }
        counselors.put(counselorId, new Counselor(counselorId, counselorName, specialty, password));
        System.out.println("咨询师注册成功。");
    }

    private static void makeAppointment(int clientId, int counselorId, String appointmentTime) {
        if (!counselors.containsKey(counselorId)) {
            System.out.println("咨询师不存在，请检查输入的咨询师ID。");
            return;
        }

        final LocalDateTime time;
        try {
            time = LocalDateTime.parse(appointmentTime, APPOINTMENT_FMT);
        } catch (DateTimeParseException e) {
            System.out.println("预约时间格式错误，请使用：yyyy-MM-dd HH:mm");
            return;
        }

        int appointmentId = nextAppointmentId++;
        appointments.put(appointmentId, new Appointment(appointmentId, clientId, counselorId, time));
        System.out.println("预约成功，预约ID为：" + appointmentId);
    }

    private static void listCounselorSchedules() {
        // 避免 entry.getValue().get("name") 这种字符串键查找与装箱/拆箱
        for (Counselor c : counselors.values()) {
