        FeedbackObject obj = new FeedbackObject("这是一条用户反馈：推荐更关注AI与Java性能优化。");
        try (OutputStream fos = Files.newOutputStream(FILE);
             ObjectOutputStream oos = new ObjectOutputStream(fos)) {
            oos.writeObject(obj);
        }
        System.out.println("Wrote: " + FILE.toAbsolutePath());
    }

    private static void readSafely() throws IOException, ClassNotFoundException {
        if (!Files.exists(FILE)) {
            System.out.println("File not found: " + FILE.toAbsolutePath());
            return;
        }

        // try-with-resources：自动关闭流，避免泄漏
        try (InputStream fis = Files.newInputStream(FILE);
             ObjectInputStream ois = new ObjectInputStream(fis)) {

