            // 只允许 FeedbackObject、String 以及少量基础类型；限制深度/引用数/字节数，防止反序列化炸弹
            ObjectInputFilter filter = ObjectInputFilter.Config.createFilter(
                    "maxdepth=5;maxrefs=1000;maxbytes=1048576;" +
                    "java.base/*;FeedbackObject;!*"
            );
            ois.setObjectInputFilter(filter);

            Object obj = ois.readObject();
            if (!(obj instanceof FeedbackObject feedback)) {
                throw new InvalidObjectException("Unexpected type: " + obj.getClass());
