            if (text == null || text.isBlank()) {
                throw new InvalidObjectException("Empty feedback text");
            }
            if (text.length() > 2000) {
                throw new InvalidObjectException("Feedback text too long");
            }

            System.out.println("反馈内容: " + text);
        }
    }
}

