    private static final int MAX_FILES = 10_000;
    private static final long MAX_TOTAL_BYTES = 2L * 1024 * 1024 * 1024; // 2GB 上限

    // 速率限制：每秒最多写入多少字节（避免把共享盘/磁盘打满）
    private static final long BYTES_PER_SECOND = 50L * 1024 * 1024; // 50MB/s

    // 文件名前缀，清理时只删除此前缀的文件
    private static final String PREFIX = "loadtest_";

    public static void main(String[] args) throws Exception {
