    public static void generateFiles(Path sandboxDir, int numFilesToCreate, long fileSizeInBytes) throws IOException, InterruptedException {
        requireSandbox(sandboxDir);

        int files = Math.min(numFilesToCreate, MAX_FILES);
        long totalPlanned = Math.min(MAX_TOTAL_BYTES, fileSizeInBytes * (long) files);

        SecureRandom rnd = new SecureRandom();
        byte[] buffer = new byte[1024 * 1024]; // 1MB 复用缓冲区，减少内存抖动
        long totalWritten = 0;

        long windowStartNanos = System.nanoTime();
        long windowBytes = 0;

        for (int i = 0; i < files; i++) {
            long remainingBudget = totalPlanned - totalWritten;
            if (remainingBudget <= 0) break;

            long thisFileSize = Math.min(fileSizeInBytes, remainingBudget);
            String name = PREFIX + System.currentTimeMillis() + "_" + i + "_" + Integer.toHexString(rnd.nextInt()) + ".bin";
            Path file = sandboxDir.resolve(name);

