            try (OutputStream out = Files.newOutputStream(file, StandardOpenOption.CREATE_NEW, StandardOpenOption.WRITE)) {
                long left = thisFileSize;
                while (left > 0) {
                    int chunk = (int) Math.min(buffer.length, left);
                    rnd.nextBytes(buffer); // 写入随机内容（可改为固定内容以减少CPU）
                    out.write(buffer, 0, chunk);
                    left -= chunk;

                    totalWritten += chunk;
                    windowBytes += chunk;

                    // 简单速率限制
                    throttle(windowStartNanos, windowBytes);
                    if (Duration.ofNanos(System.nanoTime() - windowStartNanos).toMillis() >= 1000) {
                        windowStartNanos = System.nanoTime();
                        windowBytes = 0;
                    }
                }
            }

            System.out.println("Created: " + file.toAbsolutePath() + " (" + thisFileSize + " bytes)");
        }

        System.out.println("Done. Total written: " + totalWritten + " bytes in " + sandboxDir.toAbsolutePath());
