    public static void cleanupGeneratedFiles(Path sandboxDir) throws IOException {
        requireSandbox(sandboxDir);

        try (DirectoryStream<Path> ds = Files.newDirectoryStream(sandboxDir, PREFIX + "*")) {
            for (Path p : ds) {
                Files.deleteIfExists(p);
                System.out.println("Deleted: " + p.toAbsolutePath());
            }
        }
    }

    private static void requireSandbox(Path dir) throws IOException {
        Path real = dir.toRealPath(LinkOption.NOFOLLOW_LINKS);
        Path sandboxReal = SANDBOX_DIR.toRealPath(LinkOption.NOFOLLOW_LINKS);
        if (!real.equals(sandboxReal)) {
            throw new SecurityException("Refuse to operate outside sandbox: " + sandboxReal);
        }
        if (!Files.isDirectory(real)) {
            throw new IOException("Sandbox is not a directory: " + real);
        }
    }

    private static void throttle(long windowStartNanos, long windowBytes) throws InterruptedException {
        if (BYTES_PER_SECOND <= 0) return;
        long elapsedNanos = System.nanoTime() - windowStartNanos;
        if (elapsedNanos <= 0) return;

        double seconds = elapsedNanos / 1_000_000_000.0;
        double allowed = BYTES_PER_SECOND * seconds;
        if (windowBytes > allowed) {
            // 计算需要额外等待的时间
            double extraSeconds = (windowBytes - allowed) / (double) BYTES_PER_SECOND;
            long sleepMillis = Math.max(1, (long) (extraSeconds * 1000));
            Thread.sleep(sleepMillis);
        }
    }

    private static long parseSize(String s) {
        String v = s.trim().toUpperCase(Locale.ROOT);
        long mul = 1;
        if (v.endsWith("KB")) { mul = 1024L; v = v.substring(0, v.length() - 2); }
        else if (v.endsWith("MB")) { mul = 1024L * 1024; v = v.substring(0, v.length() - 2); }
        else if (v.endsWith("GB")) { mul = 1024L * 1024 * 1024; v = v.substring(0, v.length() - 2); }
        else if (v.endsWith("B")) { mul = 1; v = v.substring(0, v.length() - 1); }
        return Long.parseLong(v.trim()) * mul;
    }
