                            "在确保自身安全且具备条件时，使用合适的灭火器材并持续冷却（遵循当地消防建议）。",
                            "火势受控后仍可能复燃，保持监测并等待专业人员处理。"
                    )
            ));

            return new KnowledgeBase(list);
        }

        List<Instruction> getAll() {
            return instructions;
        }
    }

    // ===== Presentation =====
    interface InstructionPrinter {
        void printAll(List<Instruction> instructions);
    }

    static final class ConsoleInstructionPrinter implements InstructionPrinter {
        @Override
        public void printAll(List<Instruction> instructions) {
            for (Instruction instruction : instructions) {
                System.out.println("【" + instruction.getItemName() + "】");
