import java.math.BigDecimal;
import java.math.RoundingMode;
import java.util.Scanner;

class InsufficientFundsException extends Exception {
    public InsufficientFundsException(String message) {
        super(message);
    }
}

class InvalidAmountException extends Exception {
    public InvalidAmountException(String message) {
        super(message);
    }
}

class Account {
    // 金融金额避免使用 double，改用 BigDecimal，并固定到 2 位小数
    private BigDecimal balance;

    public Account(BigDecimal initialBalance) {
        if (initialBalance == null) throw new IllegalArgumentException("initialBalance is null");
        this.balance = normalize(initialBalance);
        if (this.balance.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("initialBalance must be >= 0");
        }
    }

    public synchronized BigDecimal getBalance() {
        return balance;
    }

    public synchronized void withdraw(BigDecimal amount)
            throws InvalidAmountException, InsufficientFundsException {

        if (amount == null) throw new InvalidAmountException("amount is null");
        amount = normalize(amount);

        // 禁止 0、负数、以及非正常金额
        if (amount.compareTo(BigDecimal.ZERO) <= 0) {
            throw new InvalidAmountException("取款金额必须大于 0");
        }

        if (amount.compareTo(balance) > 0) {
            // 不在底层打印敏感信息，交由上层统一处理
            throw new InsufficientFundsException("余额不足");
        }

        balance = balance.subtract(amount);
    }

    private static BigDecimal normalize(BigDecimal v) {
        // 统一金额精度，避免 0.001 之类的输入造成异常行为
        return v.setScale(2, RoundingMode.HALF_UP);
    }
}

public class FinanceExceptionFixed {
    public static void main(String[] args) {
        try (Scanner scanner = new Scanner(System.in)) {
            Account account = new Account(new BigDecimal("1000.00"));

            System.out.println("请输入取款金额：");
            String input = scanner.nextLine().trim();

            BigDecimal withdrawAmount;
            try {
                // 用字符串构造 BigDecimal，避免 double 精度问题
                withdrawAmount = new BigDecimal(input);
            } catch (NumberFormatException ex) {
                System.out.println("输入金额格式不正确");
                return;
            }

            try {
                account.withdraw(withdrawAmount);
                System.out.println("取款成功，当前余额为: " + account.getBalance());
            } catch (InvalidAmountException e) {
                System.out.println("取款失败：无效金额");
            } catch (InsufficientFundsException e) {
                System.out.println("取款失败：余额不足，当前余额为: " + account.getBalance());
            } catch (Exception e) {
                // 兜底：不打印堆栈到控制台，避免泄露内部实现细节
                System.out.println("系统繁忙，请稍后重试");
            }
        }
    }
}
```

**关键修改点（面向金融交易安全/稳定）：**
1. **金额类型修复**：`double` 改为 `BigDecimal`（并固定 2 位小数），避免浮点精度导致的余额计算错误与绕过校验风险。  
2. **异常分级**：用受检异常 `InvalidAmountException / InsufficientFundsException` 替代直接抛 `RuntimeException`，让调用方必须显式处理关键失败路径。  
3. **输入与金额校验**：拒绝非数字、0、负数等异常金额；金额统一 `setScale(2)`，避免异常精度输入。  
4. **避免信息泄露**：移除 `printStackTrace()` 和底层 `System.out.println` 的敏感输出，改为上层统一返回可控提示，防止泄露内部栈信息。  
5. **并发安全**：`withdraw/getBalance` 加 `synchronized`，避免并发取款时出现竞态条件导致透支（单机内示例级修复；生产建议配合数据库事务/分布式锁）。

