```java
import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

@WebServlet("/password_candidates")
public class PasswordCandidateService extends HttpServlet {

    private static final int MAX_CANDIDATES = 1000;
    private static final int MAX_LEN = 64;

    // 线程安全：使用同步包装；并在复合操作时手动同步
    private final List<String> passwordCandidates =
            Collections.synchronizedList(new ArrayList<>());

    @Override
    public void init() throws ServletException {
        // 初始化默认值
        passwordCandidates.add("123456");
        passwordCandidates.add("password");
        passwordCandidates.add("admin");
    }

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setContentType("application/json; charset=UTF-8");

        // 返回数量（避免直接泄露内容；如需返回内容应做鉴权/脱敏）
        int size;
        synchronized (passwordCandidates) {
            size = passwordCandidates.size();
        }

        response.setStatus(HttpServletResponse.SC_OK);
        response.getWriter().write("{\"count\":" + size + "}");
    }

    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response) throws IOException {
        request.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setCharacterEncoding(StandardCharsets.UTF_8.name());
        response.setContentType("application/json; charset=UTF-8");

        String candidate = request.getParameter("candidate");
        if (candidate == null) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().write("{\"error\":\"missing parameter: candidate\"}");
            return;
        }

        candidate = candidate.trim();
        if (candidate.isEmpty() || candidate.length() > MAX_LEN) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            response.getWriter().write("{\"error\":\"invalid candidate\"}");
            return;
        }

        boolean added;
        synchronized (passwordCandidates) {
            if (passwordCandidates.size() >= MAX_CANDIDATES) {
                response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
                response.getWriter().write("{\"error\":\"capacity reached\"}");
                return;
            }
            // 去重（可选）
            added = !passwordCandidates.contains(candidate) && passwordCandidates.add(candidate);
        }

        response.setStatus(HttpServletResponse.SC_OK);
        response.getWriter().write("{\"added\":" + added + "}");
    }
}
```

### 关键修改点（简要）
- **线程安全**：`Collections.synchronizedList` + 对复合操作加 `synchronized`。
- **输入校验**：判空、trim、长度限制。
- **容量限制**：`MAX_CANDIDATES` 防止内存 DoS。
- **明确响应**：返回 JSON 与 HTTP 状态码。
- **避免泄露敏感数据**：`GET` 仅返回数量（如要返回列表需加鉴权/审计）。

