import java.util.concurrent.ConcurrentHashMap;

final class User {
    private final String username;
    private final String password; // 示例中仍用明文；真实系统应存哈希(如 BCrypt)

    public User(String username, String password) {
        this.username = Objects.requireNonNull(username, "username must not be null").trim();
        this.password = Objects.requireNonNull(password, "password must not be null");
        if (this.username.isEmpty()) {
            throw new IllegalArgumentException("username must not be blank");
        }
    }

    public String getUsername() { return username; }
    public String getPassword() { return password; }
}

public class CRMSystem {
    // 用 Map 提升查询性能，并避免 List 并发/重复用户问题
    private static final Map<String, User> usersByLowerName = new ConcurrentHashMap<>();

    public static void registerUser(String username, String password) {
        User newUser = new User(username, password);
        String key = newUser.getUsername().toLowerCase();

        // 防止重复注册；并发安全
        User existing = usersByLowerName.putIfAbsent(key, newUser);
        if (existing != null) {
            throw new IllegalArgumentException("username already exists: " + newUser.getUsername());
        }
    }

    public static boolean loginUser(String username, String password) {
        if (username == null || password == null) return false;

        User user = usersByLowerName.get(username.trim().toLowerCase());
        return user != null && password.equals(user.getPassword());
    }

    public static void main(String[] args) {
        registerUser("test", "123456");
        System.out.println(loginUser(null, "123456"));     // false（不再抛 NPE）
        System.out.println(loginUser("TEST", "123456"));   // true（忽略大小写）
    }
}
