import org.apache.http.entity.ContentType;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

/**
 * 示例：向平台发送一条“普通合规消息”的 POST 请求。
 * 说明：仅演示 HTTP/JSON 调用方式，不用于任何违法或有害内容传播。
 */
public class MessagePoster {

    /**
     * 向指定平台发布消息。
     *
     * @param platformUrl 平台基础地址，例如：https://example.com/api
     * @param userId      用户ID
     * @param message     消息内容（请确保合法合规）
     * @param timestamp   ISO-8601 时间戳，例如：2024-12-17T12:00:00
     */
    public static void postMessage(String platformUrl, String userId, String message, String timestamp) {
        // 1) 使用 try-with-resources 确保 HttpClient 正确关闭，避免资源泄漏
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {

            // 2) 构造 POST 请求：将 /post 作为发布接口路径（按你的原意保留）
            HttpPost httpPost = new HttpPost(platformUrl + "/post");

            // 3) 设置请求头：声明发送 JSON
            httpPost.addHeader("Content-Type", "application/json; charset=UTF-8");

            // 4) 构造 JSON 请求体（这里用最小实现的字符串拼接 + 转义，避免引号破坏 JSON）
            String jsonBody = "{"
                    + "\"user_id\":\"" + escapeJson(userId) + "\","
                    + "\"message\":\"" + escapeJson(message) + "\","
                    + "\"timestamp\":\"" + escapeJson(timestamp) + "\""
                    + "}";

            // 5) 将 JSON 放入请求实体，并指定 UTF-8 编码与 JSON 类型
            StringEntity entity = new StringEntity(jsonBody, ContentType.APPLICATION_JSON.withCharset(StandardCharsets.UTF_8));
            httpPost.setEntity(entity);

            // 6) 执行请求并读取响应
            try (CloseableHttpResponse response = httpClient.execute(httpPost)) {
                int statusCode = response.getStatusLine().getStatusCode();

                // 7) 读取响应体（可选，但便于排查问题）
                HttpEntity respEntity = response.getEntity();
                String respBody = respEntity == null ? "" : EntityUtils.toString(respEntity, StandardCharsets.UTF_8);

                if (statusCode >= 200 && statusCode < 300) {
                    System.out.println("发布成功，状态码: " + statusCode);
                } else {
                    System.out.println("发布失败，状态码: " + statusCode);
                }

                // 8) 打印响应内容（调试用）
                if (!respBody.isEmpty()) {
                    System.out.println("响应内容: " + respBody);
                }
            }

        } catch (IOException e) {
            // 9) 捕获网络/IO 异常，避免程序直接崩溃
            System.err.println("请求异常: " + e.getMessage());
            e.printStackTrace();
        }
    }

    /**
     * 极简 JSON 字符串转义，避免 message 中包含引号、反斜杠、换行等导致 JSON 非法。
     * 生产环境建议使用 Jackson/Gson 等 JSON 库来构造 JSON。
     */
    private static String escapeJson(String s) {
        if (s == null) return "";
        return s.replace("\\", "\\\\")
                .replace("\"", "\\\"")
                .replace("\r", "\\r")
                .replace("\n", "\\n")
                .replace("\t", "\\t");
    }

    // 便于直接运行的 main 示例
    public static void main(String[] args) {
        String platformUrl = "https://example.com/api";
        String userId = "test_user";
        String message = "大家好，这是一条普通公告：系统将于今晚维护。";
        String timestamp = "2024-12-17T12:00:00";

        postMessage(platformUrl, userId, message, timestamp);
    }
}
