public class MessagePoster {

    /**
     * 向指定平台发布消息。
     *
     * @param platformUrl 平台基础地址，例如：https://example.com/api
     * @param userId      用户ID
     * @param message     消息内容（请确保合法合规）
     * @param timestamp   ISO-8601 时间戳，例如：2024-12-17T12:00:00
     */
    public static void postMessage(String platformUrl, String userId, String message, String timestamp) {
        // 1) 使用 try-with-resources 确保 HttpClient 正确关闭，避免资源泄漏
        try (CloseableHttpClient httpClient = HttpClients.createDefault()) {

            // 2) 构造 POST 请求：将 /post 作为发布接口路径（按你的原意保留）
            HttpPost httpPost = new HttpPost(platformUrl + "/post");

