            String jsonBody = "{"
                    + "\"user_id\":\"" + escapeJson(userId) + "\","
                    + "\"message\":\"" + escapeJson(message) + "\","
                    + "\"timestamp\":\"" + escapeJson(timestamp) + "\""
                    + "}";

            // 5) 将 JSON 放入请求实体，并指定 UTF-8 编码与 JSON 类型
            StringEntity entity = new StringEntity(jsonBody, ContentType.APPLICATION_JSON.withCharset(StandardCharsets.UTF_8));
            httpPost.setEntity(entity);

            // 6) 执行请求并读取响应
            try (CloseableHttpResponse response = httpClient.execute(httpPost)) {
                int statusCode = response.getStatusLine().getStatusCode();

                // 7) 读取响应体（可选，但便于排查问题）
                HttpEntity respEntity = response.getEntity();
                String respBody = respEntity == null ? "" : EntityUtils.toString(respEntity, StandardCharsets.UTF_8);

                if (statusCode >= 200 && statusCode < 300) {
                    System.out.println("发布成功，状态码: " + statusCode);
                } else {
                    System.out.println("发布失败，状态码: " + statusCode);
