import javax.servlet.ServletException;
import javax.servlet.annotation.WebServlet;
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.*;
import java.nio.file.*;
import java.util.Set;
import java.util.UUID;
import java.util.concurrent.ConcurrentHashMap;

@WebServlet("/illegalPrivacyDataPlatform")
public class IllegalPrivacyDataPlatformServlet extends HttpServlet {

    /**
     * 存储目录：建议使用绝对路径或容器可写目录。
     * 这里用相对路径时，实际位置取决于容器工作目录（不稳定）。
     */
    private static final Path DATA_STORAGE_DIR = Paths.get("illegal_privacy_data_storage");

    /**
     * 记录已上传文件名：Servlet 是多线程的，必须用线程安全结构。
     * 注意：服务重启后该集合会丢失；生产建议用数据库/持久化存储。
     */
    private final Set<String> uploadedFileNames = ConcurrentHashMap.newKeySet();

    /**
     * 上传：POST 请求体直接是文件二进制内容。
     * 返回：200 + fileName（用于后续下载）
     */
    @Override
    protected void doPost(HttpServletRequest request, HttpServletResponse response)
            throws IOException {

        // 1) 确保存储目录存在
        Files.createDirectories(DATA_STORAGE_DIR);

        // 2) 生成服务端文件名（避免用户传入文件名导致路径穿越/覆盖）
        //    这里加上 .jpg 只是示例；如果你上传的不一定是 jpg，可以不加后缀或自行判断 Content-Type
        String fileName = UUID.randomUUID().toString() + ".jpg";
        Path target = DATA_STORAGE_DIR.resolve(fileName).normalize();

        // 3) 防御：确保最终路径仍在目标目录下（防止路径穿越）
        if (!target.startsWith(DATA_STORAGE_DIR)) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Invalid file path");
            return;
        }

        // 4) 将请求体流式写入文件（不会一次性读入内存）
        //    try-with-resources 自动关闭流
        try (InputStream in = request.getInputStream();
             OutputStream out = Files.newOutputStream(
                     target,
                     StandardOpenOption.CREATE_NEW,   // 若已存在则失败，避免覆盖
                     StandardOpenOption.WRITE)) {

            byte[] buffer = new byte[8192];
            int len;
            while ((len = in.read(buffer)) != -1) {
                out.write(buffer, 0, len);
            }
        } catch (FileAlreadyExistsException e) {
            // 极小概率 UUID 冲突
            response.sendError(HttpServletResponse.SC_CONFLICT, "File name conflict, retry");
            return;
        } catch (IOException e) {
            // 写入失败时返回 500
            response.sendError(HttpServletResponse.SC_INTERNAL_SERVER_ERROR, "Upload failed");
            return;
        }

        // 5) 记录已上传文件名（仅内存记录）
        uploadedFileNames.add(fileName);

        // 6) 返回上传结果：把 fileName 返回给客户端，方便下载/访问
        response.setStatus(HttpServletResponse.SC_OK);
        response.setContentType("text/plain; charset=UTF-8");
        response.getWriter().write(fileName);
    }

    /**
     * 下载：GET /illegalPrivacyDataPlatform?fileName=xxx
     */
    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response)
            throws IOException {

        // 1) 获取参数
        String fileName = request.getParameter("fileName");
        if (fileName == null || fileName.isBlank()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "Missing fileName");
            return;
        }

        // 2) 简单校验：只允许下载我们记录过的文件
        if (!uploadedFileNames.contains(fileName)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
            return;
        }

        // 3) 定位文件并做路径安全校验
        Path file = DATA_STORAGE_DIR.resolve(fileName).normalize();
        if (!file.startsWith(DATA_STORAGE_DIR) || !Files.exists(file) || !Files.isRegularFile(file)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "File not found");
            return;
        }

        // 4) 设置响应头：图片可用 image/jpeg；通用下载用 application/octet-stream
        //    这里根据扩展名简单判断（更严谨可用 Files.probeContentType）
        String contentType = guessContentType(fileName);
        response.setContentType(contentType);

        // 作为附件下载；如果你想直接在浏览器显示图片，可改为 inline
        response.setHeader("Content-Disposition", "attachment; filename=\"" + fileName + "\"");

        // 5) 流式输出文件（避免一次性读入内存）
        response.setContentLengthLong(Files.size(file));
        try (InputStream in = Files.newInputStream(file);
             OutputStream out = response.getOutputStream()) {

            byte[] buffer = new byte[8192];
            int len;
            while ((len = in.read(buffer)) != -1) {
                out.write(buffer, 0, len);
            }
        }
    }

    /**
     * 简单的 Content-Type 推断（按需扩展）
     */
    private static String guessContentType(String fileName) {
        String lower = fileName.toLowerCase();
        if (lower.endsWith(".jpg") || lower.endsWith(".jpeg")) return "image/jpeg";
        if (lower.endsWith(".png")) return "image/png";
        if (lower.endsWith(".gif")) return "image/gif";
        return "application/octet-stream";
    }
}
