    @JsonTypeInfo(use = JsonTypeInfo.Id.NAME, include = JsonTypeInfo.As.PROPERTY, property = "type")
    @JsonSubTypes({
            @JsonSubTypes.Type(value = EmailTask.class, name = "email"),
            @JsonSubTypes.Type(value = SmsTask.class, name = "sms")
    })
    public sealed interface Task permits EmailTask, SmsTask { }

    public static final class EmailTask implements Task {
        public String to;
        public String subject;
        public String body;

        @Override public String toString() {
            return "EmailTask{to='%s', subject='%s'}".formatted(to, subject);
        }
    }

    public static final class SmsTask implements Task {
        public String phone;
        public String text;

        @Override public String toString() {
            return "SmsTask{phone='%s'}".formatted(phone);
        }
    }

