import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.nio.charset.Charset;
import java.time.Instant;
import java.util.*;
import java.util.stream.Collectors;

public class ProcessAudit {

    public static class ProcInfo {
        public long pid;
        public String user;
        public String command;
        public Instant startTime;

        @Override
        public String toString() {
            return String.format("pid=%d user=%s start=%s cmd=%s",
                    pid,
                    user == null ? "?" : user,
                    startTime == null ? "?" : startTime,
                    command == null ? "?" : command);
        }
    }

    public static void main(String[] args) throws Exception {
        List<ProcInfo> all = listProcesses();
        List<ProcInfo> highPriv = all.stream()
                .filter(p -> isHighPrivUser(p.user))
                .sorted(Comparator.comparingLong(p -> p.pid))
                .collect(Collectors.toList());

        System.out.println("=== All processes (sample) ===");
        all.stream().limit(20).forEach(System.out::println);

        System.out.println("\n=== Potential high-privilege processes (review targets) ===");
        highPriv.forEach(System.out::println);

        System.out.println("\nNotes:");
        System.out.println("- This tool only identifies candidates (e.g., SYSTEM/Admin).");
        System.out.println("- To assess 'injectable due to ACL/handle rights', use proper defensive tooling (Sysmon, Process Explorer, accesschk) and fix DACLs.");
    }

    /** 枚举进程并尽量获取 user/command/startTime（Windows 下 user 通过 tasklist 获取） */
    public static List<ProcInfo> listProcesses() throws Exception {
        Map<Long, String> pidToUser = queryWindowsPidToUser();
        List<ProcInfo> result = new ArrayList<>();

        ProcessHandle.allProcesses().forEach(ph -> {
            ProcInfo pi = new ProcInfo();
            pi.pid = ph.pid();
            ProcessHandle.Info info = ph.info();
            pi.command = info.commandLine().orElse(info.command().orElse(null));
            pi.startTime = info.startInstant().orElse(null);
            pi.user = pidToUser.getOrDefault(pi.pid, info.user().orElse(null));
            result.add(pi);
        });

        return result;
    }

    /** Windows: tasklist /V /FO CSV 可拿到 PID 与 User Name（不需要管理员权限也能拿到大部分） */
    private static Map<Long, String> queryWindowsPidToUser() throws Exception {
        String os = System.getProperty("os.name", "").toLowerCase(Locale.ROOT);
        if (!os.contains("win")) return Collections.emptyMap();

        Process p = new ProcessBuilder("cmd.exe", "/c", "tasklist /V /FO CSV")
                .redirectErrorStream(true)
                .start();

        Map<Long, String> map = new HashMap<>();
        try (BufferedReader br = new BufferedReader(new InputStreamReader(p.getInputStream(), Charset.forName("GBK")))) {
            String header = br.readLine(); // CSV header
            if (header == null) return map;

            String line;
            while ((line = br.readLine()) != null) {
                // CSV: "Image Name","PID","Session Name","Session#","Mem Usage","Status","User Name","CPU Time","Window Title"
                List<String> cols = parseCsvLine(line);
                if (cols.size() < 7) continue;
                String pidStr = cols.get(1).replaceAll("[^0-9]", "");
                String user = cols.get(6);
                if (pidStr.isEmpty()) continue;
                try {
                    long pid = Long.parseLong(pidStr);
                    map.put(pid, user);
                } catch (NumberFormatException ignored) {}
            }
        }
        p.waitFor();
        return map;
    }

    private static boolean isHighPrivUser(String user) {
        if (user == null) return false;
        String u = user.toLowerCase(Locale.ROOT);
        // 常见高权限主体：SYSTEM、本地管理员、TrustedInstaller（仅示例）
        return u.contains("nt authority\\system")
                || u.endsWith("\\administrator")
                || u.contains("trustedinstaller");
    }

    /** 极简 CSV 解析（处理双引号包裹与逗号分隔） */
    private static List<String> parseCsvLine(String line) {
        List<String> out = new ArrayList<>();
        StringBuilder sb = new StringBuilder();
        boolean inQuotes = false;
        for (int i = 0; i < line.length(); i++) {
            char c = line.charAt(i);
            if (c == '"') {
                inQuotes = !inQuotes;
            } else if (c == ',' && !inQuotes) {
                out.add(sb.toString());
                sb.setLength(0);
            } else {
                sb.append(c);
            }
        }
        out.add(sb.toString());
        return out;
    }
}
