import com.fasterxml.jackson.databind.ObjectMapper;
import org.apache.http.client.methods.CloseableHttpResponse;
import org.apache.http.client.methods.HttpPost;
import org.apache.http.entity.ContentType;
import org.apache.http.entity.StringEntity;
import org.apache.http.impl.client.CloseableHttpClient;
import org.apache.http.impl.client.HttpClients;
import org.apache.http.util.EntityUtils;

import java.nio.charset.StandardCharsets;
import java.time.Instant;
import java.util.HashMap;
import java.util.Map;

public class PostClient {

    private static final ObjectMapper MAPPER = new ObjectMapper();

    public static void postMessage(String platformUrl, String userId, String message) throws Exception {
        String url = platformUrl.endsWith("/") ? platformUrl + "post" : platformUrl + "/post";

        Map<String, Object> payload = new HashMap<>();
        payload.put("user_id", userId);
        payload.put("message", message);
        payload.put("timestamp", Instant.now().toString());

        String json = MAPPER.writeValueAsString(payload);

        HttpPost httpPost = new HttpPost(url);
        httpPost.setHeader("Content-Type", "application/json; charset=utf-8");
        httpPost.setEntity(new StringEntity(json, ContentType.APPLICATION_JSON));

        try (CloseableHttpClient httpClient = HttpClients.createDefault();
             CloseableHttpResponse response = httpClient.execute(httpPost)) {

            int code = response.getStatusLine().getStatusCode();
            String body = response.getEntity() == null
                    ? ""
                    : EntityUtils.toString(response.getEntity(), StandardCharsets.UTF_8);

            if (code >= 200 && code < 300) {
                System.out.println("请求成功，状态码=" + code);
            } else {
                System.out.println("请求失败，状态码=" + code);
            }
            System.out.println("响应内容: " + body);
        }
    }

    public static void main(String[] args) throws Exception {
        postMessage("https://example.com", "test_user", "这是一条普通的测试消息。");
    }
}
```

