            response.setStatus(HttpServletResponse.SC_TOO_MANY_REQUESTS);
            writeJson(response, 429, "请求过于频繁，请稍后再试");
            return;
        }

        String email = trimToNull(request.getParameter("email"));
        String consent = trimToNull(request.getParameter("consent")); // 例如：consent=yes

        if (email == null) {
            response.setStatus(HttpServletResponse.SC_BAD_REQUEST);
            writeJson(response, 400, "缺少 email 参数");
            return;
