    private static boolean isRateLimited(String ip) {
        long now = System.currentTimeMillis();
        Counter c = RATE.computeIfAbsent(ip, k -> new Counter(now, 0));

        synchronized (c) {
            if (now - c.windowStart > WINDOW_MS) {
                c.windowStart = now;
