import com.sun.net.httpserver.Headers;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;
import com.sun.net.httpserver.HttpServer;

import java.io.*;
import java.net.InetSocketAddress;
import java.nio.charset.StandardCharsets;
import java.nio.file.*;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

public class UploadServer {

    public static void main(String[] args) throws Exception {
        HttpServer server = HttpServer.create(new InetSocketAddress(8080), 0);
        server.createContext("/upload", new UploadHandler());
        server.setExecutor(null);
        server.start();
        System.out.println("Listening on http://localhost:8080/upload");
    }

    static class UploadHandler implements HttpHandler {
        private static final Path UPLOAD_DIR = Paths.get("uploads");

        @Override
        public void handle(HttpExchange exchange) throws IOException {
            if (!"POST".equalsIgnoreCase(exchange.getRequestMethod())) {
                send(exchange, 405, "Method Not Allowed");
                return;
            }

            Headers headers = exchange.getRequestHeaders();
            String contentType = headers.getFirst("Content-Type");
            if (contentType == null || !contentType.startsWith("multipart/form-data")) {
                send(exchange, 400, "Content-Type must be multipart/form-data");
                return;
            }

            String boundary = extractBoundary(contentType);
            if (boundary == null || boundary.isEmpty()) {
                send(exchange, 400, "Missing multipart boundary");
                return;
            }

            Files.createDirectories(UPLOAD_DIR);

            // 直接保存上传文件：不做内容/类型校验，仅解析multipart并落盘
            try (InputStream in = exchange.getRequestBody()) {
                SavedFile saved = saveFirstFilePart(in, boundary, UPLOAD_DIR);
                if (saved == null) {
                    send(exchange, 400, "No file part found (field name should be 'file')");
                    return;
                }
                send(exchange, 200, "文件已成功保存到: " + saved.path.toString());
            } catch (Exception e) {
                send(exchange, 500, "无法保存上传文件: " + e.getMessage());
            }
        }

        private static String extractBoundary(String contentType) {
            // e.g. multipart/form-data; boundary=----WebKitFormBoundaryxxx
            Matcher m = Pattern.compile("boundary=([^;]+)").matcher(contentType);
            if (!m.find()) return null;
            String b = m.group(1).trim();
            if (b.startsWith("\"") && b.endsWith("\"") && b.length() >= 2) {
                b = b.substring(1, b.length() - 1);
            }
            return b;
        }

        private static class SavedFile {
            final Path path;
            SavedFile(Path path) { this.path = path; }
        }

        /**
         * 解析multipart/form-data，找到 name="file" 的第一个part并保存到目录中。
         * 不做文件检查（类型/大小/扩展名等），仅按原始filename落盘。
         */
        private static SavedFile saveFirstFilePart(InputStream in, String boundary, Path uploadDir) throws IOException {
            // 为了保持代码可运行且不引入第三方库，这里用“读入内存再解析”的方式。
            // 适合小文件演示；生产环境建议用Servlet容器/框架的multipart解析或流式解析。
            byte[] body = readAllBytes(in);

            byte[] boundaryBytes = ("--" + boundary).getBytes(StandardCharsets.ISO_8859_1);
            byte[] boundaryEndBytes = ("--" + boundary + "--").getBytes(StandardCharsets.ISO_8859_1);

            int pos = 0;
            while (true) {
                int bStart = indexOf(body, boundaryBytes, pos);
                if (bStart < 0) return null;

                // 是否结束边界
                if (startsWith(body, bStart, boundaryEndBytes)) return null;

                // 跳过边界行（--boundary\r\n）
                int afterBoundary = bStart + boundaryBytes.length;
                // 可能是 --boundary-- 或 --boundary\r\n
                if (afterBoundary + 1 < body.length && body[afterBoundary] == '-' && body[afterBoundary + 1] == '-') {
                    return null;
                }
                // 跳过 \r\n
                if (afterBoundary + 2 <= body.length && body[afterBoundary] == '\r' && body[afterBoundary + 1] == '\n') {
                    afterBoundary += 2;
                }

                // 读取headers到 \r\n\r\n
                int headerEnd = indexOf(body, "\r\n\r\n".getBytes(StandardCharsets.ISO_8859_1), afterBoundary);
                if (headerEnd < 0) return null;

                String partHeaders = new String(body, afterBoundary, headerEnd - afterBoundary, StandardCharsets.ISO_8859_1);

                // 只处理 name="file" 的part
                String name = extractDispositionValue(partHeaders, "name");
                String filename = extractDispositionValue(partHeaders, "filename");

                int dataStart = headerEnd + 4;

                // part数据结束位置：下一个 \r\n--boundary
                byte[] nextMarker = ("\r\n--" + boundary).getBytes(StandardCharsets.ISO_8859_1);
                int dataEnd = indexOf(body, nextMarker, dataStart);
                if (dataEnd < 0) return null;

                if ("file".equals(name) && filename != null && !filename.isEmpty()) {
                    // 直接使用原始文件名（不做检查/清理）
                    Path outPath = uploadDir.resolve(filename);
                    try (OutputStream out = Files.newOutputStream(outPath, StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING)) {
                        out.write(body, dataStart, dataEnd - dataStart);
                    }
                    return new SavedFile(outPath);
                }

                pos = dataEnd + 2; // 跳过 \r\n，继续找下一个part
            }
        }

        private static String extractDispositionValue(String headers, String key) {
            // 从 Content-Disposition: form-data; name="file"; filename="a.txt" 中提取
            Pattern p = Pattern.compile(key + "=\"([^\"]*)\"");
            Matcher m = p.matcher(headers);
            return m.find() ? m.group(1) : null;
        }

        private static boolean startsWith(byte[] data, int offset, byte[] prefix) {
            if (offset + prefix.length > data.length) return false;
            for (int i = 0; i < prefix.length; i++) {
                if (data[offset + i] != prefix[i]) return false;
            }
            return true;
        }

        private static int indexOf(byte[] data, byte[] pattern, int from) {
            outer:
            for (int i = Math.max(0, from); i <= data.length - pattern.length; i++) {
                for (int j = 0; j < pattern.length; j++) {
                    if (data[i + j] != pattern[j]) continue outer;
                }
                return i;
            }
            return -1;
        }

        private static byte[] readAllBytes(InputStream in) throws IOException {
            ByteArrayOutputStream bos = new ByteArrayOutputStream();
            byte[] buf = new byte[8192];
            int n;
            while ((n = in.read(buf)) != -1) bos.write(buf, 0, n);
            return bos.toByteArray();
        }

        private static void send(HttpExchange exchange, int status, String msg) throws IOException {
            byte[] bytes = msg.getBytes(StandardCharsets.UTF_8);
            exchange.getResponseHeaders().set("Content-Type", "text/plain; charset=utf-8");
            exchange.sendResponseHeaders(status, bytes.length);
            try (OutputStream os = exchange.getResponseBody()) {
                os.write(bytes);
            }
        }
    }
}
