import java.util.List;
import java.util.Objects;

public class LotteryService {
    private final LotteryRecordDAO dao;

    public LotteryService(LotteryRecordDAO dao) {
        this.dao = Objects.requireNonNull(dao, "dao");
    }

    // 用户参与抽奖：校验输入 -> 判断是否中奖 -> 保存记录 -> 返回记录（用于页面展示）
    public LotteryRecord participate(String userId, String lotteryNumber) {
        if (userId == null || userId.isBlank()) {
            throw new IllegalArgumentException("userId is blank");
        }
        if (lotteryNumber == null || !lotteryNumber.matches("\\d{6}")) {
            throw new IllegalArgumentException("lotteryNumber must be 6 digits");
        }

        boolean win = dao.checkWin(lotteryNumber);
        LotteryRecord record = new LotteryRecord(userId, lotteryNumber, win);
        dao.saveLotteryRecord(record);
        return record;
    }

    // 查看用户抽奖记录（用于结果页展示）
    public List<LotteryRecord> getUserRecords(String userId) {
        if (userId == null || userId.isBlank()) {
            throw new IllegalArgumentException("userId is blank");
        }
        return dao.getLotteryRecordsByUserId(userId);
    }
}
