        when(t1.getThreadName()).thenReturn("JDWP Transport Listener: dt_socket");

        ThreadInfo t2 = mock(ThreadInfo.class);
        when(t2.getThreadName()).thenReturn("main");

        when(mxBean.getThreadInfo(new long[]{1L, 2L}, Integer.MAX_VALUE))
                .thenReturn(new ThreadInfo[]{t1, t2});

        assertTrue(DebugEnvironmentDetection.checkIfInDebuggingByThreads(mxBean));
    }

