import java.lang.management.ManagementFactory;
import java.lang.management.ThreadInfo;
import java.lang.management.ThreadMXBean;
import java.util.Locale;

public class DebugEnvironmentDetection {

    public static void main(String[] args) {
        boolean isInDebugging = checkIfInDebuggingByThreads();
        System.out.println(isInDebugging ? "程序当前处于调试环境。" : "程序当前未处于调试环境。");
    }

    /**
     * 通过线程信息粗略判断是否处于调试/探针环境。
     * 说明：这是启发式检测，可能存在误报/漏报。
     */
    public static boolean checkIfInDebuggingByThreads() {
        return checkIfInDebuggingByThreads(ManagementFactory.getThreadMXBean());
    }

    // 便于单元测试注入 mock
    static boolean checkIfInDebuggingByThreads(ThreadMXBean threadMXBean) {
        if (threadMXBean == null) return false;

        long[] ids = threadMXBean.getAllThreadIds();
        if (ids == null || ids.length == 0) return false;

        ThreadInfo[] infos = threadMXBean.getThreadInfo(ids, Integer.MAX_VALUE);
        if (infos == null) return false;

        for (ThreadInfo info : infos) {
            if (info == null) continue;
            String name = info.getThreadName();
            if (name == null) continue;

            String n = name.toLowerCase(Locale.ROOT);

            // 常见调试/探针相关线程名（启发式）
            if (n.contains("jdwp") ||
                n.contains("debugger") ||
                n.contains("jdi") ||
                n.contains("attach listener") ||
                n.contains("jfr") ||
                n.contains("async-profiler") ||
                n.contains("arthas") ||
                n.contains("btrace")) {
                return true;
            }
        }
        return false;
    }
}
