import sqlite3
from contextlib import closing
from typing import Any, Dict, Optional, Tuple

DB_PATH = "restaurant_db.db"


class DatabaseError(Exception):
    pass


def execute_query(query: str, params: Tuple[Any, ...] = ()) -> list[tuple]:
    """Execute a SELECT query safely and return all rows."""
    try:
        with sqlite3.connect(DB_PATH) as conn:
            conn.row_factory = sqlite3.Row
            with closing(conn.cursor()) as cursor:
                cursor.execute(query, params)
                return cursor.fetchall()
    except sqlite3.Error as e:
        raise DatabaseError(f"Database Error: {e}") from e


def get_order_by_id(order_id: int) -> Optional[sqlite3.Row]:
    rows = execute_query("SELECT * FROM orders WHERE order_id = ?;", (order_id,))
    return rows[0] if rows else None


def process_order(order_details: Dict[str, Any]) -> sqlite3.Row:
    if "order_id" not in order_details:
        raise ValueError("Missing required field: order_id")

    try:
        order_id = int(order_details["order_id"])
    except (TypeError, ValueError) as e:
        raise ValueError("order_id must be an integer") from e

    order = get_order_by_id(order_id)
    if order is None:
        raise LookupError(f"Order not found: {order_id}")

    # sqlite3.Row supports dict-like access; convert to dict for clean printing/logging
    print(f"Order {order_id} found: {dict(order)}")
    return order


def place_order(order_details: Dict[str, Any]) -> bool:
    try:
        process_order(order_details)
        return True
    except (ValueError, LookupError, DatabaseError) as e:
        print(f"Error placing order: {e}")
        return False


if __name__ == "__main__":
    # Example usage
    place_order({"order_id": 1})
