## 可运行代码（FastAPI 后端）
> 文件：`app.py`

```python
from __future__ import annotations

import io
import json
import csv
from typing import Tuple

from fastapi import FastAPI, UploadFile, File, HTTPException
from fastapi.responses import JSONResponse

# 可选依赖：docx/pdf 解析
try:
    import docx  # python-docx
except Exception:
    docx = None

try:
    from pypdf import PdfReader
except Exception:
    PdfReader = None


app = FastAPI(title="Online Editor Upload API")

# 关键限制：最大文件大小（字节）
MAX_BYTES = 5 * 1024 * 1024  # 5MB

# 允许的扩展名
ALLOWED_EXT = {".txt", ".md", ".json", ".csv", ".docx", ".pdf"}


def _ext_of(filename: str) -> str:
    filename = filename or ""
    dot = filename.rfind(".")
    return filename[dot:].lower() if dot != -1 else ""


def _read_limited(upload: UploadFile, max_bytes: int) -> bytes:
    """
    读取上传内容并限制大小，避免一次性读入超大文件导致内存问题。
    """
    data = bytearray()
    chunk_size = 1024 * 1024  # 1MB
    while True:
        chunk = upload.file.read(chunk_size)
        if not chunk:
            break
        data.extend(chunk)
        if len(data) > max_bytes:
            raise HTTPException(status_code=413, detail="File too large")
    return bytes(data)


def _decode_text(data: bytes) -> str:
    """
    文本解码：优先 utf-8，失败则用 latin-1 兜底（不报错但可能乱码）。
    生产环境可引入 charset-normalizer/chardet 做更准确检测。
    """
    try:
        return data.decode("utf-8")
    except UnicodeDecodeError:
        return data.decode("latin-1", errors="replace")


def _parse_by_ext(ext: str, data: bytes) -> Tuple[str, str]:
    """
    返回 (detected_type, content)
    """
    if ext in {".txt", ".md"}:
        return ("text", _decode_text(data))

    if ext == ".json":
        text = _decode_text(data)
        try:
            obj = json.loads(text)
            pretty = json.dumps(obj, ensure_ascii=False, indent=2)
            return ("json", pretty)
        except json.JSONDecodeError:
            # JSON 不合法时仍返回原文，便于用户在编辑器里修复
            return ("json", text)

    if ext == ".csv":
        text = _decode_text(data)
        # 统一成“可读文本”展示：用 csv 解析后再格式化输出
        reader = csv.reader(io.StringIO(text))
        lines = []
        for row in reader:
            lines.append("\t".join(row))
        return ("csv", "\n".join(lines))

    if ext == ".docx":
        if docx is None:
            raise HTTPException(status_code=500, detail="python-docx not installed")
        f = io.BytesIO(data)
        document = docx.Document(f)
        content = "\n".join(p.text for p in document.paragraphs)
        return ("docx", content)

    if ext == ".pdf":
        if PdfReader is None:
            raise HTTPException(status_code=500, detail="pypdf not installed")
        f = io.BytesIO(data)
        reader = PdfReader(f)
        pages = []
        for i, page in enumerate(reader.pages):
            pages.append(page.extract_text() or "")
        return ("pdf", "\n\n".join(pages))

    raise HTTPException(status_code=400, detail="Unsupported file type")


@app.post("/api/upload")
async def upload(file: UploadFile = File(...)):
    ext = _ext_of(file.filename)
    if ext not in ALLOWED_EXT:
        raise HTTPException(status_code=400, detail=f"Unsupported extension: {ext}")

    data = _read_limited(file, MAX_BYTES)
    detected_type, content = _parse_by_ext(ext, data)

    return JSONResponse(
        {
            "filename": file.filename,
            "detected_type": detected_type,
            "content": content,
        }
    )


@app.get("/health")
def health():
    return {"ok": True}
```

