SET time_zone = '+00:00';

-- 清理（便于重复执行测试）
DROP PROCEDURE IF EXISTS submitComment;
DROP TABLE IF EXISTS comments;
DROP TABLE IF EXISTS fitness_posts;
DROP TABLE IF EXISTS students;

-- 学员表
CREATE TABLE students (
    student_id   INT PRIMARY KEY,
    student_name VARCHAR(100) NOT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 动态表
CREATE TABLE fitness_posts (
    post_id      INT PRIMARY KEY,
    student_id   INT NOT NULL,
    post_content TEXT NOT NULL,
    post_date    DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_posts_student
      FOREIGN KEY (student_id) REFERENCES students(student_id)
      ON DELETE RESTRICT ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 评论表
CREATE TABLE comments (
    comment_id   BIGINT AUTO_INCREMENT PRIMARY KEY,
    student_id   INT NOT NULL,
    post_id      INT NOT NULL,
    comment_text TEXT NOT NULL,
    comment_date DATETIME NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT fk_comments_student
      FOREIGN KEY (student_id) REFERENCES students(student_id)
      ON DELETE RESTRICT ON UPDATE CASCADE,

    CONSTRAINT fk_comments_post
      FOREIGN KEY (post_id) REFERENCES fitness_posts(post_id)
      ON DELETE CASCADE ON UPDATE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

-- 常用查询索引：按动态查评论、按学员查评论
CREATE INDEX idx_comments_post_date ON comments(post_id, comment_date);
CREATE INDEX idx_comments_student_date ON comments(student_id, comment_date);

DELIMITER $$

CREATE PROCEDURE submitComment(
    IN  p_studentId   INT,
    IN  p_postId      INT,
    IN  p_commentText TEXT,
    OUT o_message     VARCHAR(500)
)
BEGIN
    DECLARE v_student_name VARCHAR(100);
    DECLARE v_post_content VARCHAR(200);
    DECLARE v_trimmed_text TEXT;

    -- 任何 SQL 异常：回滚并返回错误信息
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        SET o_message = '提交评论失败：数据库异常（可能是外键/约束/数据类型等问题）';
    END;

    -- 基本校验
    SET v_trimmed_text = TRIM(p_commentText);

    IF v_trimmed_text IS NULL OR CHAR_LENGTH(v_trimmed_text) = 0 THEN
        SET o_message = '提交评论失败：评论内容不能为空';
        LEAVE proc_end;
    END IF;

    -- 事务：保证插入与读取展示信息一致
    START TRANSACTION;

    -- 校验学员存在并取名（FOR UPDATE 可避免并发下读到不一致；可按需去掉）
    SELECT s.student_name
      INTO v_student_name
      FROM students s
     WHERE s.student_id = p_studentId
     FOR UPDATE;

    IF v_student_name IS NULL THEN
        ROLLBACK;
        SET o_message = '提交评论失败：学员不存在';
        LEAVE proc_end;
    END IF;

    -- 校验动态存在并取内容
    SELECT LEFT(p.post_content, 200)
      INTO v_post_content
      FROM fitness_posts p
     WHERE p.post_id = p_postId
     FOR UPDATE;

    IF v_post_content IS NULL THEN
        ROLLBACK;
        SET o_message = '提交评论失败：动态不存在';
        LEAVE proc_end;
    END IF;

    -- 写入评论
    INSERT INTO comments(student_id, post_id, comment_text, comment_date)
    VALUES (p_studentId, p_postId, v_trimmed_text, NOW());

    COMMIT;

    SET o_message = CONCAT(
        '学员 "', v_student_name,
        '" 发表评论: "', LEFT(v_trimmed_text, 200),
        '" 于动态 "', v_post_content, '"'
    );

    proc_end: BEGIN END;
END$$

DELIMITER ;

