DROP PROCEDURE IF EXISTS simulate_storage_growth;
DELIMITER $$

CREATE PROCEDURE simulate_storage_growth(
  IN p_batch_id CHAR(36),
  IN p_rows INT,
  IN p_bytes_per_row INT,
  IN p_max_total_bytes BIGINT
)
BEGIN
  DECLARE i INT DEFAULT 0;
  DECLARE current_bytes BIGINT DEFAULT 0;

  IF p_rows <= 0 OR p_bytes_per_row <= 0 THEN
    SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'p_rows and p_bytes_per_row must be > 0';
