  SELECT IFNULL(SUM(OCTET_LENGTH(payload)), 0) INTO current_bytes
  FROM disk_fill_sim;

  WHILE i < p_rows DO
    IF current_bytes + p_bytes_per_row > p_max_total_bytes THEN
      LEAVE WHILE;
    END IF;

    INSERT INTO disk_fill_sim(batch_id, payload)
    VALUES (p_batch_id, RANDOM_BYTES(p_bytes_per_row));

    SET current_bytes = current_bytes + p_bytes_per_row;
    SET i = i + 1;
  END WHILE;

  SELECT p_batch_id AS batch_id, i AS rows_inserted, current_bytes AS approx_total_payload_bytes;
END$$

DELIMITER ;
```

## 3) 存储过程：按批次清理（释放空间）
```sql
DROP PROCEDURE IF EXISTS cleanup_storage_growth;
DELIMITER $$

