question:
下面给你一套**可直接执行**的 MySQL 单元测试脚本（基于 MySQL 8.0 的 `mysqltest` 风格断言：`SIGNAL` + 结果校验）。思路是：每个用例在事务里执行，失败就 `SIGNAL` 报错；最后统一 `ROLLBACK`，不污染数据。

> 说明：MySQL 原生没有像 JUnit 那样的内置 UT 框架，常见做法是用 **mysqltest** 或者用 SQL 写“断言”。下面脚本属于“SQL 断言式单元测试”，在 CI/部署时可直接跑，任何断言失败会中断并报错。

---

## 1) 测试脚本（可直接运行）

> 建议在**测试库**执行：`USE his_test;`

```sql
/* =========================================================
   Test Suite: HIS Patient/Visit/Payment Stored Procedures
   MySQL 8.0+
   ========================================================= */

-- 建议：在测试库执行
-- CREATE DATABASE IF NOT EXISTS his_test;
-- USE his_test;

-- 为了可重复执行：先清理
DROP PROCEDURE IF EXISTS add_patient;
DROP PROCEDURE IF EXISTS add_visit_record;
DROP PROCEDURE IF EXISTS make_payment;

DROP TABLE IF EXISTS payment_records;
DROP TABLE IF EXISTS visit_records;
DROP TABLE IF EXISTS patients;

-- 重新创建表
CREATE TABLE IF NOT EXISTS patients (
    patient_id INT PRIMARY KEY,
    patient_name VARCHAR(255),
    gender VARCHAR(10),
    age INT,
    contact_number VARCHAR(20)
);

CREATE TABLE IF NOT EXISTS visit_records (
    record_id INT AUTO_INCREMENT PRIMARY KEY,
    patient_id INT,
    doctor_id INT,
    visit_date DATETIME,
    diagnosis TEXT,
    treatment_plan TEXT,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id)
);

CREATE TABLE IF NOT EXISTS payment_records (
    payment_id INT AUTO_INCREMENT PRIMARY KEY,
    patient_id INT,
    total_amount DECIMAL(10, 2),
    payment_date DATETIME,
    FOREIGN KEY (patient_id) REFERENCES patients(patient_id)
);

-- 重新创建存储过程
DELIMITER $$

CREATE PROCEDURE add_patient(
    IN p_patient_id INT,
    IN p_patient_name VARCHAR(255),
    IN p_gender VARCHAR(10),
    IN p_age INT,
    IN p_contact_number VARCHAR(20)
)
DETERMINISTIC
BEGIN
    INSERT INTO patients (patient_id, patient_name, gender, age, contact_number)
    VALUES (p_patient_id, p_patient_name, p_gender, p_age, p_contact_number);
END$$

CREATE PROCEDURE add_visit_record(
    IN p_patient_id INT,
    IN p_doctor_id INT,
    IN p_visit_date DATETIME,
    IN p_diagnosis TEXT,
    IN p_treatment_plan TEXT
)
DETERMINISTIC
BEGIN
    INSERT INTO visit_records (patient_id, doctor_id, visit_date, diagnosis, treatment_plan)
    VALUES (p_patient_id, p_doctor_id, p_visit_date, p_diagnosis, p_treatment_plan);
END$$

CREATE PROCEDURE make_payment(
    IN p_patient_id INT,
    IN p_total_amount DECIMAL(10, 2),
    IN p_payment_date DATETIME
)
DETERMINISTIC
BEGIN
    INSERT INTO payment_records (patient_id, total_amount, payment_date)
    VALUES (p_patient_id, p_total_amount, p_payment_date);
END$$

DELIMITER ;

-- =========================================================
-- 断言工具：不满足条件就抛错
-- =========================================================
DROP PROCEDURE IF EXISTS assert_true;
DELIMITER $$
CREATE PROCEDURE assert_true(IN cond BOOLEAN, IN msg VARCHAR(255))
BEGIN
    IF cond IS NULL OR cond = FALSE THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = msg;
    END IF;
END$$
DELIMITER ;

-- =========================================================
-- Test Case 1: add_patient 正常插入
-- =========================================================
START TRANSACTION;

CALL add_patient(1, '张三', '男', 30, '13812345678');

CALL assert_true(
    (SELECT COUNT(*) FROM patients WHERE patient_id = 1) = 1,
    'TC1 failed: patient not inserted'
);

CALL assert_true(
    (SELECT patient_name FROM patients WHERE patient_id = 1) = '张三',
    'TC1 failed: patient_name mismatch'
);

CALL assert_true(
    (SELECT age FROM patients WHERE patient_id = 1) = 30,
    'TC1 failed: age mismatch'
);

ROLLBACK;

-- =========================================================
-- Test Case 2: add_patient 主键重复应失败
-- =========================================================
START TRANSACTION;

CALL add_patient(1, '张三', '男', 30, '13812345678');

-- 捕获预期错误：主键重复
SET @dup_ok = 0;
BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET @dup_ok = 1;
    CALL add_patient(1, '李四', '男', 40, '13900000000');
END;

CALL assert_true(@dup_ok = 1, 'TC2 failed: duplicate PK did not raise error');

ROLLBACK;

-- =========================================================
-- Test Case 3: add_visit_record 正常插入（依赖患者存在）
-- =========================================================
START TRANSACTION;

CALL add_patient(1, '张三', '男', 30, '13812345678');
CALL add_visit_record(1, 101, '2026-03-01 10:00:00', '感冒', '开药治疗');

CALL assert_true(
    (SELECT COUNT(*) FROM visit_records WHERE patient_id = 1 AND doctor_id = 101) = 1,
    'TC3 failed: visit record not inserted'
);

CALL assert_true(
    (SELECT diagnosis FROM visit_records WHERE patient_id = 1 AND doctor_id = 101 LIMIT 1) = '感冒',
    'TC3 failed: diagnosis mismatch'
);

ROLLBACK;

-- =========================================================
-- Test Case 4: add_visit_record 外键不存在应失败
-- =========================================================
START TRANSACTION;

SET @fk_ok = 0;
BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET @fk_ok = 1;
    CALL add_visit_record(999, 101, '2026-03-01 10:00:00', '感冒', '开药治疗');
END;

CALL assert_true(@fk_ok = 1, 'TC4 failed: FK violation did not raise error');

ROLLBACK;

-- =========================================================
-- Test Case 5: make_payment 正常插入
-- =========================================================
START TRANSACTION;

CALL add_patient(1, '张三', '男', 30, '13812345678');
CALL make_payment(1, 100.00, '2026-03-01 11:00:00');

CALL assert_true(
    (SELECT COUNT(*) FROM payment_records WHERE patient_id = 1 AND total_amount = 100.00) = 1,
    'TC5 failed: payment not inserted'
);

CALL assert_true(
    (SELECT total_amount FROM payment_records WHERE patient_id = 1 ORDER BY payment_id DESC LIMIT 1) = 100.00,
    'TC5 failed: total_amount mismatch'
);

ROLLBACK;

-- =========================================================
-- Test Case 6: make_payment 外键不存在应失败
-- =========================================================
START TRANSACTION;

SET @pay_fk_ok = 0;
BEGIN
    DECLARE CONTINUE HANDLER FOR SQLEXCEPTION SET @pay_fk_ok = 1;
    CALL make_payment(999, 100.00, '2026-03-01 11:00:00');
END;

CALL assert_true(@pay_fk_ok = 1, 'TC6 failed: payment FK violation did not raise error');

ROLLBACK;

-- =========================================================
-- All tests passed if script reaches here
-- =========================================================
SELECT 'ALL TESTS PASSED' AS result;
```

